const state={route:location.hash.slice(1)||'today',collapsed:localStorage.getItem('pokerlab-pro-collapsed')==='1',scenario:draft?.players?.length>=2?draft:clone(defaultScenario),selectedPlayer:0,caseId:draftSettings?.caseId||null,selectedHand:'AKo',paint:'inspect',heroBlock:false,metadata:null,hardware:null,analysis:null,analysisKey:null,analyzing:false,analysisError:null,tab:'coach',baseline:null,coach:null,coachBusy:false,coachQuestion:'',job:null,node:null,nodePath:[],solving:false,solveConfig:false,settings:{...clone(defaultSettings),...(draftSettings?.settings||{})},lessons:[],summary:null,cases:[],jobs:[],caseFilter:'',caseFormat:'all',lesson:null,lessonStarted:0,answer:null,reasons:[],confidence:60,feedback:null,grading:false,parse:null,picker:null,trainingFilter:'all',notesOpen:false};
