function toast(message,error=false){const stack=$('#toast-stack');if(!stack)return;if(!error)stack.querySelectorAll('.toast:not(.error)').forEach(n=>n.remove());while(stack.children.length>=3)stack.firstElementChild.remove();const el=document.createElement('div');el.className='toast'+(error?' error':'');el.innerHTML=`${icon(error?'info':'check')}<span>${esc(message)}</span><button aria-label="关闭提示">×</button>`;el.querySelector('button').onclick=()=>el.remove();stack.append(el);setTimeout(()=>el.remove(),error?9500:5000);}
async function api(path,data,options={}){const r=await fetch(path,{...options,...(data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)})});let body;try{body=await r.json();}catch{throw Error('本地服务没有返回有效数据，请检查服务是否已启动。');}if(!r.ok||body?.error)throw Error(body.error||`请求失败（${r.status}）`);return body;}
function key(s=state.scenario){return JSON.stringify({board:s.board,pot:s.pot,players:s.players.map(p=>({id:p.id,position:p.position,range:p.range,stack:p.stack})),hero:s.hero,heroSeat:s.heroSeat,toAct:s.toAct,rake:s.rake??0,rakeCap:s.rakeCap??0});}
function stale(){return !!state.analysis&&key()!==state.analysisKey;}
function persist(){localStorage.setItem('pokerlab-pro-draft',JSON.stringify(state.scenario));localStorage.setItem('pokerlab-pro-draft-settings',JSON.stringify({settings:state.settings,lockSignature:state.lockSignature,caseId:state.caseId}));}
function touch(){state.coach=null;state.coachError=null;persist();}
function parseCards(text){try{return cards(text);}catch{return [];}}
function card(c,small=false,extra=''){if(c===undefined||c===null)return `<button class="playing-card placeholder ${small?'small':''} clickable" ${extra}>+</button>`;const t=typeof c==='number'?cardText(c):c;return `<button class="playing-card ${t[1]} ${small?'small':''} ${extra?'clickable':''}" ${extra}><span>${t[0]==='T'?'T':t[0]}</span><i>${symbols[t[1]]}</i></button>`;}
function inlineHand(text){try{return cards(text).map(c=>{const t=cardText(c);return `<span class="inline-card ${t[1]}">${t[0]}${symbols[t[1]]}</span>`;}).join(' ');}catch{return esc(text);}}
function boardHTML(text,small=false){return parseCards(text).map(c=>card(c,small)).join('');}
function safeRange(i=state.selectedPlayer){try{const dead=parseCards(state.scenario.board);if(state.heroBlock&&i!==heroIndex(state.scenario))dead.push(...parseCards(state.scenario.hero));return range(state.scenario.players[i]?.range||'',dead);}catch(e){return {error:e.message,count:0,weighted:0,removed:0,groups:{},live:[]};}}
function nav(route){state.route=route;location.hash=route;render();window.scrollTo(0,0);if(route==='library')loadCases();if(route==='progress'||route==='today')loadSummary();}
function gpuDeviceLabel(){const devices=state.hardware?.accelerator?.devices;return Array.isArray(devices)&&devices.length?devices.map(d=>d.name).join(' / '):'GPU 型号尚未识别';}
function render(){const titles={today:'今日训练',study:'局面研究',train:'训练实验室',library:'研究档案',progress:'能力档案'};$('#app').innerHTML=`<div class="layout ${state.collapsed?'collapsed':''}"><aside class="sidebar"><a href="#today" class="brand" data-action="nav" data-route="today"><div class="brand-mark">♠</div><div class="brand-info"><div class="brand-title">观局</div><div class="brand-caption">RANGEMIND · 私人训练室</div></div></a><div class="nav-label">你的训练工作台</div><nav>${[['today','今日训练'],['study','局面研究'],['train','训练实验室'],['library','研究档案'],['progress','能力档案']].map(([id,name])=>`<button class="nav-button ${state.route===id?'active':''}" data-action="nav" data-route="${id}" title="${name}">${icon(id)}<span class="nav-text">${name}</span>${id==='train'&&dueCount()?`<span class="nav-badge">${dueCount()}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><button class="nav-button" data-action="capabilities" title="计算能力与边界">${icon('cpu')}<span class="nav-text">本地计算引擎</span></button><a class="nav-button" href="/research" title="训练方法与新版指南">${icon('book')}<span class="nav-text">训练方法与指南</span></a><a class="nav-button" href="/legacy" title="打开旧版实验工具">${icon('book')}<span class="nav-text">旧版实验工具</span></a><div class="local-status"><div class="row" style="gap:7px"><i class="dot ${state.hardware?'':'amber'}"></i><strong>${state.hardware?'本地工作台已连接':'正在连接本地服务'}</strong></div><div>${state.hardware?`${fmt(state.hardware.threads||32,0)} 线程 · ${fmt(state.hardware.memoryGB||64,0)} GB 内存`:'所有研究记录保存在此电脑'}</div><div>${esc(gpuDeviceLabel())}${state.hardware?.gpuKernel?' · 权益内核已安装':''}</div></div><div class="sidebar-collapse"><button class="icon-button" data-action="collapse" aria-label="${state.collapsed?'展开':'收起'}侧栏">${icon(state.collapsed?'expand':'collapse')}</button></div></div></aside><div class="main"><header class="topbar"><div class="breadcrumb"><span>私人训练工作台</span>${icon('chevron')}<strong>${titles[state.route]}</strong></div><div class="topbar-actions"><span class="topbar-status badge green"><i class="dot"></i> LOCAL FIRST</span><button class="command-trigger" data-action="commands" title="快捷操作 Ctrl K">${icon('search')}<span>快速操作</span><kbd class="key">Ctrl K</kbd></button></div></header><main class="content">${renderLoadStatus()}${({today:renderToday,study:renderStudy,train:renderTraining,library:renderLibrary,progress:renderProgress}[state.route])()}</main></div></div>`;bindSpecial();}
function dueCount(){return state.summary?.due?.length??state.summary?.dueCount??0;}
function attemptCount(){return state.summary?.totalAttempts??state.summary?.attemptsCount??state.summary?.attempts?.length??0;}
function renderToday(){const next=state.summary?.recommended?.[0]||state.lessons[0],recent=state.cases.slice(0,3);return `<div class="page-heading"><div><div class="eyebrow">YOUR NEXT EDGE</div><h1 style="margin-top:7px">把每一次研究，变成实战能力。</h1><p class="subtitle">先作判断，再看证据。每次专注解决一个真正影响决策的问题。</p></div><span class="muted" style="font-size:11px;white-space:nowrap">${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</span></div><div class="welcome"><section class="panel focus-card"><span class="badge green">${dueCount()?'有待复习项目':'从机制理解开始'}</span><h2>${dueCount()?'检验上次学会的，<br>今天还能否独立判断。':'权益相同，<br>加注为什么会截然不同？'}</h2><p>从对手继续范围出发，拆开弃牌、跟注和再加注的收益。把“这手牌该怎么打”推进到“什么条件改变时，我需要换一种打法”。</p>${btn(`开始今日训练 ${icon('arrow')}`,dueCount()?'due-training':next?'lesson':'nav','primary',next&&!dueCount()?`data-id="${esc(next.id)}"`:'data-route="train"')}</section><section class="panel daily-card"><div class="row spread"><h3>一轮有效训练</h3><span class="badge">主动提取 → 验证</span></div><div class="daily-line"><span class="step-number">01</span><div><h4>先给出自己的判断</h4><p>行动、关键理由、信心程度；答案暂时隐藏。</p></div></div><div class="daily-line"><span class="step-number">02</span><div><h4>找出让结论改变的条件</h4><p>看组合和分支收益，做一次单变量对照。</p></div></div><div class="daily-line"><span class="step-number">03</span><div><h4>换一个局面，再做一次</h4><p>留下实战观察任务，用延迟复测检验保持。</p></div></div></section></div><div class="section-gap"><div class="section-title"><h2>从你的问题开始</h2><small>线上与现场，共用一套研究流程</small></div><div class="quick-grid"><button class="panel quick-card" data-action="import">${icon('paste')}<div><h3>粘贴牌谱或中文速记</h3><p>自动重建行动，核对底池与筹码。</p></div></button><button class="panel quick-card" data-action="nav" data-route="study">${icon('branch')}<div><h3>研究一个具体局面</h3><p>编辑范围、看组合、比较行动树。</p></div></button><button class="panel quick-card" data-action="templates">${icon('target')}<div><h3>从精心构造的案例开始</h3><p>单挑与多人，分别研究一个核心机制。</p></div></button></div></div><div class="section-gap"><div class="section-title"><h2>你的训练记录</h2>${btn('查看能力档案 '+icon('arrow'),'nav','ghost small','data-route="progress"')}</div><div class="metric-grid"><div class="panel metric"><span class="muted">已完成练习</span><div class="metric-number">${state.summary?attemptCount():'—'}<small>次判断</small></div><div class="metric-note">每次判断及依据保存在本机</div></div><div class="panel metric"><span class="muted">待复习项目</span><div class="metric-number">${state.summary?dueCount():'—'}<small>项</small></div><div class="metric-note">根据实际表现安排复测</div></div><div class="panel metric"><span class="muted">个人研究档案</span><div class="metric-number">${state.cases.length}<small>个案例</small></div><div class="metric-note">参数、范围与研究笔记</div></div><div class="panel metric"><span class="muted">迁移检验</span><div class="metric-number">${state.summary?.transferAttempts??'—'}<small>${state.summary?.transferAttempts===undefined?'尚待积累':'次'}</small></div><div class="metric-note">与同题练习分别报告</div></div></div></div>${recent.length?`<div class="section-gap"><div class="section-title"><h2>继续最近的研究</h2>${btn('所有案例 '+icon('arrow'),'nav','ghost small','data-route="library"')}</div><div class="case-grid">${recent.map(renderCaseCard).join('')}</div></div>`:''}`;}
function renderStudy(){const s=state.scenario,p=s.players[state.selectedPlayer]||s.players[0],r=safeRange(),board=parseCards(s.board),hero=parseCards(s.hero);return `<div class="page-heading"><div><div class="eyebrow">RANGE → RESPONSE → DECISION</div><h1 style="margin-top:6px">局面研究</h1><p class="subtitle">从范围和行动分支中，找出决策真正依赖的条件。</p></div><div class="row">${btn(icon('chip')+'现场记录','live-open')}${btn(icon('paste')+'快捷录入','import')}${state.caseId?btn('另存副本','save-case-copy','small',state.savingCase?'disabled':''):''}${btn(state.savingCase?'<span class="spinner"></span>保存中…':icon('save')+(state.caseId?'更新案例':'保存案例'),'save-case','primary',state.savingCase?'disabled':'')}</div></div><div class="panel study-toolbar"><input class="title-input grow" aria-label="研究标题" data-field="title" value="${esc(s.title)}"><div class="format-toggle"><button data-action="format" data-value="online" class="${s.format==='online'?'active':''}">线上</button><button data-action="format" data-value="live" class="${s.format==='live'?'active':''}">现场</button></div>${btn(icon('target')+'载入案例','templates','small')}${btn(icon('download'),'export-draft','ghost small','title="导出当前局面"')}${btn(icon('chip'),'analyze','small',`title="计算范围权益" ${state.analyzing?'disabled':''}`)}${btn(icon('branch')+'求解','solve','primary small',`title="求解完整行动策略" ${state.solving?'disabled':''}`)}</div><div class="study-grid"><div class="study-left"><section class="panel table-panel"><div class="panel-header"><div class="row"><h3>研究牌桌</h3><span class="badge">${s.players.length} 人底池</span></div><button class="button ghost small" data-action="cards" data-target="board" data-index="0">${icon('edit')}编辑牌面</button></div><div class="poker-table"><div class="table-surface"></div><div class="table-top">${s.players.filter((_,i)=>i>=2).map((v,j)=>renderSeat(v,j+2)).join('')||'<span class="badge">HEADS-UP</span>'}</div><div class="community"><div class="pot-label"><span>STREET START</span>${fmt(s.pot)} <small>BB</small></div><div class="cards-row">${Array.from({length:5},(_,i)=>card(board[i],false,`data-action="cards" data-target="board" data-index="${i}" aria-label="编辑第 ${i+1} 张公共牌"`)).join('')}</div><div class="faint" style="font-size:9px;margin-top:8px">${({0:'选择公共牌',3:'翻牌',4:'转牌',5:'河牌'}[board.length])||'牌面尚未完整'} · 点击牌张即可更换</div></div><div class="table-bottom">${s.players.slice(0,2).map((v,i)=>renderSeat(v,i)).join('')}</div></div><div class="table-config-side"><div class="table-info"><label><span class="label">本街起始底池 · BB</span><input type="number" min="0.01" step="0.5" data-field="pot" value="${esc(s.pot)}"></label><label><span class="label">本街先行动</span><select data-field="toAct">${s.players.map((v,i)=>`<option value="${i}" ${Number(s.toAct)===i?'selected':''}>${esc(v.position||v.name)}</option>`).join('')}</select></label><label><span class="label">聚焦手牌位置</span><select data-field="heroSeat">${s.heroSeat===null?'<option value="" disabled selected>Hero不在当前底池</option>':''}${s.players.map((v,i)=>`<option value="${i}" ${heroIndex(s)===i?'selected':''}>${esc(v.position||v.name)}</option>`).join('')}</select></label></div><div class="table-controls"><div class="row spread"><div><span class="label">聚焦手牌 · 可留空</span><div class="row" style="gap:4px">${Array.from({length:2},(_,i)=>card(hero[i],true,`data-action="cards" data-target="hero" data-index="${i}" aria-label="编辑第 ${i+1} 张手牌"`)).join('')}${hero.length?`<button class="icon-button" data-action="clear-hero" title="清空聚焦手牌">${icon('close')}</button>`:''}</div></div><div class="row">${btn(icon('plus')+'玩家','add-player','small',s.players.length>=9?'disabled':'')}${s.players.length>2?btn(icon('trash'),'remove-player','ghost small','title="移除当前选中的玩家"'):''}</div></div><div class="player-editor"><div class="row spread" style="margin-bottom:9px"><span class="label" style="margin:0">当前编辑：${esc(p.position)} ${esc(p.name)}</span><span class="badge ${state.selectedPlayer===heroIndex(s)?'green':''}">${state.selectedPlayer===heroIndex(s)?'聚焦玩家':'独立范围假设'}</span></div><div class="field-row three"><label><span class="label">名称</span><input data-player-field="name" value="${esc(p.name)}"></label><label><span class="label">位置</span><select data-player-field="position">${['SB','BB','UTG','UTG+1','UTG+2','LJ','MP','HJ','CO','BTN','OOP','IP'].map(pos=>`<option ${pos===p.position?'selected':''}>${pos}</option>`).join('')}</select></label><label><span class="label">街起点剩余 · BB</span><input type="number" min="0" data-player-field="stack" value="${esc(p.stack)}"></label></div></div><details style="margin-top:13px"><summary class="board-text-toggle">直接输入牌张与抽水</summary><div class="field-row" style="margin-top:10px"><label><span class="label">公共牌</span><input data-field="board" value="${esc(s.board)}" placeholder="Ks 7h 2h 9c 3s"></label><label><span class="label">聚焦手牌</span><input data-field="hero" value="${esc(s.hero)}" placeholder="Ac Kd"></label><label><span class="label">抽水比例 · %</span><input type="number" min="0" max="20" step="0.1" data-field="rake" value="${esc(s.rake??0)}"></label><label><span class="label">封顶 · BB</span><input type="number" min="0" step="0.1" data-field="rakeCap" value="${esc(s.rakeCap??0)}"></label></div><p class="help">本街起点输入；填写抽水时，底池使用未扣抽水金额。已经封顶的固定抽水仍需通过引擎检查；不受支持的动态抽水规则会明确拒绝。平台/赌场的比例与封顶请据实际规则填写。</p></details></div></div></section><div class="panel notes-box"><div class="panel-header"><h3>研究问题与假设</h3>${btn('保存局面并立研究问题','lab-project-draft','ghost small')}</div><div class="panel-body"><textarea data-field="notes" aria-label="研究问题与笔记" placeholder="我想验证什么？哪些范围来自观察，哪些只是推测？">${esc(s.notes||'')}</textarea><p class="help">写下可被推翻的假设，例如：“BB 冷跟变紧，会使 BTN 的哪些加注失去价值？”</p></div></div></div><div class="study-right"><section class="panel range-panel"><div class="player-tabs">${s.players.map((v,i)=>`<button class="player-tab ${i===state.selectedPlayer?'active':''}" data-action="player" data-index="${i}">${esc(v.position)}${i===heroIndex(s)?'<span class="hero-pin">H</span>':''}</button>`).join('')}</div><div class="range-bank-toolbar"><span class="help">复用经过自己核对的范围假设</span><div class="row">${btn(icon('library')+'范围片段库','range-bank-open','ghost small')}${btn(icon('save')+'保存此范围','range-bank-create','ghost small')}</div></div><div class="range-tools"><div class="tool-group">${[['inspect','检查'],['100','100%'],['50','50%'],['0','移除']].map(([v,l])=>`<button class="tool ${state.paint===v?'active':''}" data-action="paint-mode" data-value="${v}">${l}</button>`).join('')}</div><label class="blockers-toggle"><input type="checkbox" id="hero-block" ${state.heroBlock?'checked':''}>移除聚焦手牌</label></div><div class="matrix-wrap"><div class="range-matrix" id="range-matrix">${renderMatrix(r)}</div></div><div class="range-summary"><div><strong>${r.error?'—':r.count}</strong><small>合法组合</small></div><div><strong>${r.error?'—':fmt(r.weighted)}</strong><small>加权组合</small></div><div><strong>${r.error?'—':r.removed}</strong><small>已阻断</small></div></div><div class="range-text"><textarea aria-label="${esc(p.position)} 范围" data-player-field="range" spellcheck="false" placeholder="例如：77,22,AKs,KQo:50%,AhQh">${esc(p.range)}</textarea><div class="range-source">范围是当前街起点的研究假设；支持 22+、A5s-A2s、具体组合及 :50% 权重。</div>${r.error?`<div class="issue error">${esc(r.error)}</div>`:''}</div><div class="combo-drawer">${renderCombos(r)}</div></section></div></div><section class="panel research-bottom"><div class="run-bar"><div class="run-description"><b style="color:var(--text);font-weight:500">先看范围，再研究行动。</b><br>权益显示摊牌概率；策略树比较过牌、下注、跟注、加注与再加注。</div><div class="run-actions">${btn(icon('sliders'),'solve-settings','ghost','title="计算与建树设置"')}${btn(state.analyzing?'<span class="spinner"></span>计算中…':icon('chip')+'范围权益','analyze','',state.analyzing?'disabled':'')}${state.analyzing?btn('取消','cancel-analysis','ghost small'):''}${btn(state.solving?'<span class="spinner"></span>求解中…':icon('branch')+'求解行动策略','solve','primary',state.solving?'disabled':'')}</div></div>${state.solveConfig?renderSettings():''}${renderJobStatus()}${stale()?`<div class="stale-notice">${icon('info')}输入已改变。下方权益结果属于上一次计算，请重新计算后用于判断。</div>`:''}<div class="result-tabs">${[['coach','教练解析'],['equity','范围与组合证据'],['tree','行动树'],['compare','对照实验']].map(([v,l])=>`<button class="result-tab ${state.tab===v?'active':''}" data-action="result-tab" data-value="${v}">${l}</button>`).join('')}</div><div class="result-body" id="result-body">${renderResult()}</div></section>`;}
function renderSeat(p,i){const r=safeRange(i),isHero=i===heroIndex(state.scenario);return `<button class="player-seat ${i===state.selectedPlayer?'active':''}" data-action="player" data-index="${i}">${i===Number(state.scenario.toAct)?'<span class="turn-pin" title="本街先行动"></span>':''}<div class="seat-name"><b>${esc(p.position||p.name)}</b>${isHero?'<span class="hero-pin">HERO</span>':''}<span class="muted">${p.name!==p.position?esc(p.name):''}</span></div><div class="seat-stack">${fmt(p.stack)} <small>BB</small></div><div class="seat-range">${r.error?'范围待补':fmt(r.weighted)+' 加权组合'}</div></button>`;}
function renderMatrix(r){let html='';for(let i=0;i<13;i++)for(let j=0;j<13;j++){const hand=i===j?GRID[i]+GRID[j]:i<j?GRID[i]+GRID[j]+'s':GRID[j]+GRID[i]+'o',g=r.groups[hand],weight=g?.after?g.weighted/g.after:0;html+=`<button class="range-cell ${i===j?'pair':i<j?'suited':'off'} ${weight?'live':''} ${state.selectedHand===hand?'selected':''}" data-action="range-cell" data-hand="${hand}" style="--weight:${weight}" title="${hand} · ${g?.after??0} 合法组合 / ${fmt(g?.weighted??0)} 加权组合" aria-label="${hand}"><span>${hand}</span><small>${weight?fmt(g.weighted,1):'·'}</small></button>`;}return html;}
function renderCombos(r){const hand=state.selectedHand;let group=r.groups[hand],combos=group?.combos;if(!combos){const dead=parseCards(state.scenario.board);if(state.heroBlock&&state.selectedPlayer!==heroIndex(state.scenario))dead.push(...parseCards(state.scenario.hero));try{combos=range(hand).all.map(c=>({...c,weight:0,blocked:c.cards.some(c=>dead.includes(c))}));}catch{combos=[];}}return `<div class="row spread"><h4>${esc(hand)} <span class="muted" style="font-weight:400">· 具体花色组合</span></h4><span class="faint" style="font-size:9px">可直接改每个组合频率</span></div><div class="combo-grid">${combos.map(c=>`<div class="combo-item ${c.blocked?'blocked':''}"><span>${inlineHand(c.label)}</span>${c.blocked?'<span class="faint">阻断</span>':`<span class="row" style="gap:0"><input type="number" min="0" max="100" data-combo="${esc(c.label)}" value="${fmt(c.weight*100,1)}" aria-label="${c.label} 频率"><small>%</small></span>`}</div>`).join('')}</div><div class="selection-bar"><span class="muted">整类 ${esc(hand)}</span><input id="class-weight" type="number" min="0" max="100" value="100" aria-label="整类频率"><span class="muted">%</span>${btn('应用','class-weight','small')}</div>`;}
function renderSettings(){return `<div class="solver-config"><div class="row spread" style="margin-bottom:13px"><h4>计算与建树设置</h4><span class="badge">金额口径保持可见</span></div><div class="field-row four"><label><span class="label">权益采样数</span><select data-setting="samples">${[100000,1000000,5000000].map(n=>`<option value="${n}" ${Number(state.settings.samples)===n?'selected':''}>${fmt(n/10000,0)} 万次</option>`).join('')}</select></label><label><span class="label">迭代次数</span><input type="number" min="10" max="100000" step="100" data-setting="iterations" value="${state.settings.iterations}"></label><label><span class="label">下注 · 底池 %</span><input data-setting="sizes" value="${esc(state.settings.sizes)}" placeholder="50,100"></label><label><span class="label">加注 · 跟注后底池 %</span><input data-setting="raiseSizes" value="${esc(state.settings.raiseSizes)}" placeholder="100"></label><label><span class="label">最多加注层数</span><select data-setting="maxRaises">${[0,1,2,3].map(n=>`<option ${n===Number(state.settings.maxRaises)?'selected':''}>${n}</option>`).join('')}</select></label><label style="display:flex;align-items:center;gap:7px;margin-top:20px"><input type="checkbox" id="all-in" ${state.settings.allIn?'checked':''}><span>包含全下</span></label></div><p class="help">更多尺寸与加注层数会明显增加计算规模。多人策略只在引擎明确支持的街、规则和资源范围内运行；不支持时会显示原因。</p></div>`;}
function renderJobStatus(){const j=state.job;if(!j)return '';const running=['queued','running','preparing','cancelling'].includes(j.status),status=({queued:'等待本地计算资源',running:'正在求解行动策略',preparing:'检查范围与构建行动树',cancelling:'正在停止计算并释放资源',complete:'策略求解完成',completed:'策略求解完成',cancelled:'计算已取消',failed:'求解未完成'}[j.status])||j.status;const d=j.diagnostics||j.result?.diagnostics,stats=j.stats||j.result?.stats;return `<div class="job-status"><div class="row spread"><div class="row">${running?'<span class="spinner"></span>':icon(j.status==='failed'?'info':'check')}<strong style="font-size:12px;font-weight:500">${esc(status)}</strong>${stats?.iterations?`<span class="badge">${fmt(stats.iterations,0)} 次迭代</span>`:''}${stats?.seconds?`<span class="muted" style="font-size:10px">${fmt(stats.seconds,1)} 秒</span>`:''}</div>${running?btn(j.status==='cancelling'?'正在停止…':'停止计算','cancel-solve','danger small',j.status==='cancelling'?'disabled':''):btn('查看策略','result-tab','small','data-value="tree"')}</div>${running?'<div class="loading-line" style="margin-top:12px"></div>':''}${d&&numeric(d.nashConv)?`<p class="help">指定树内 NashConv ${fmt(d.nashConv,4)} BB${d.nashConvPctPot!==undefined?' · 起始底池的 '+fmt(d.nashConvPctPot,3)+'%':''}。${esc(d.verifiedBy||'各玩家偏离增益详见策略证据。')}</p>`:''}${j.error?`<div class="issue error">${esc(j.error)}</div>`:''}${j.log?`<details style="margin-top:9px"><summary class="muted" style="font-size:10px;cursor:pointer">计算日志</summary><pre>${esc(Array.isArray(j.log)?j.log.map(v=>typeof v==='string'?v:JSON.stringify(v)).join('\n'):j.log)}</pre></details>`:''}</div>`;}
function renderResult(){if(state.tab==='tree')return renderTree();if(state.tab==='compare')return renderComparison();if(state.analyzing&&!state.analysis)return `<div class="empty"><span class="spinner"></span><h3 style="margin-top:15px">正在计算各方范围与聚焦手牌</h3><p>先验证牌张互斥，再在同一联合发牌分布中计算。完成后将显示采样方法与误差。</p></div>`;if(state.analysisError&&!state.analysis)return `<div class="empty"><span class="empty-icon">${icon('info')}</span><h3>这次计算需要修正输入</h3><p>${esc(state.analysisError)}</p>${btn('检查牌面与范围','scroll-input','small')}</div>`;if(!state.analysis)return `<div class="empty"><span class="empty-icon">${icon('target')}</span><h3>先提出一个问题，再用计算检验</h3><p>点击“范围权益”查看真实组合与摊牌概率；点击“求解行动策略”研究包含加注和再加注的行动树。</p><div class="row" style="justify-content:center"><span class="badge">范围假设可编辑</span><span class="badge">结果有证据来源</span><span class="badge">权益 ≠ 行动 EV</span></div></div>`;return state.tab==='equity'?renderEquity():renderCoach();}
function renderCoach(){const a=state.analysis,e=a.explanation||{},sections=e.sections||e.lines||[];return `<div class="result-grid"><div><span class="eyebrow">EVIDENCE FIRST</span><h2 class="coach-lead" style="margin-top:10px">${esc(e.headline||'先理解范围结构，再判断哪些行动值得继续研究。')}</h2><div class="evidence-list">${sections.map((v,i)=>`<article class="evidence-card"><h4><span class="evidence-number">${String(i+1).padStart(2,'0')}</span>${esc(v.title)}</h4><p>${esc(v.body)}</p>${v.evidenceIds?.length?`<details><summary>计算依据</summary>${v.evidenceIds.map(x=>`<span class="badge">${esc(x)}</span>`).join(' ')}</details>`:''}</article>`).join('')||'<p class="muted">计算已完成。切换到“范围与组合证据”查看数值，使用行动树进一步研究决策。</p>'}</div></div><div><div class="coach-principle"><span class="eyebrow">THE QUESTION TO ASK</span><h3 style="margin-top:10px">什么条件改变，会让我的判断反转？</h3><p>固定牌面，只改变一位玩家的继续范围。先写预测，重新计算，再对照差异。不要把同时改变多个条件的结果归因于一个原因。</p><div class="row" style="margin-top:15px">${btn(icon('copy')+'设为对照 A','pin-baseline','small')}${btn('打开实验','result-tab','ghost small','data-value="compare"')}</div></div><div class="evidence-card" style="margin-top:13px"><div class="row spread"><h4>中文教练 · 深入解读</h4><span class="badge">本地</span></div><p>围绕当前证据追问机制、反例和实战观察。未计算出的动作 EV 不会由文字补造。</p><textarea id="coach-question" style="margin-top:12px;font-size:11px;min-height:75px" placeholder="例如：谁的范围更依赖薄价值？如何设计一个能验证的加注实验？">${esc(state.coachQuestion)}</textarea>${btn(state.coachBusy?(state.coachStage==='language'?'<span class="spinner"></span>证据已就绪，正在根据问题选择教学重点…':'<span class="spinner"></span>正在读取计算证据…'):icon('spark')+'详细解读当前证据','coach','small',state.coachBusy||stale()?'disabled':'')}<div id="coach-response">${state.coachError?`<div class="issue error">${esc(state.coachError)}</div>`:''}${state.coach?`<div class="divider"></div><div class="coach-text">${coachResponseHTML(state.coach)}</div><div class="result-meta"><span class="badge">${esc(state.coach.model||'证据模板')}</span>${state.coach.grounding?`<span>${esc(typeof state.coach.grounding==='string'?state.coach.grounding:'基于当前计算证据')}</span>`:''}</div>${(state.coach.limitations||[]).map(l=>`<p class="help">${esc(l)}</p>`).join('')}`:''}</div></div>${renderAssumptions(a)}</div></div>`;}
function coachResponseHTML(response){if(response?.composition==='verified-lesson-selection'&&response.structured?.reasoning?.length)return '<div class="coach-evidence-sections"><div class="callout">'+esc(response.structured.summary)+'</div>'+response.structured.reasoning.map((r,i)=>'<article><h4><span class="evidence-number">'+String(i+1).padStart(2,'0')+'</span>'+esc(r.title)+'</h4>'+richText(r.claim)+'</article>').join('')+(response.structured.exercise?'<article><h4>迁移练习</h4>'+richText(response.structured.exercise)+'</article>':'')+'</div>';if(response?.grounding==='deterministic'&&response.report?.sections?.length)return `<div class="coach-evidence-sections">${response.report.sections.map((s,i)=>`<article><h4><span class="evidence-number">${String(i+1).padStart(2,'0')}</span>${esc(s.title)}</h4>${richText(s.body)}</article>`).join('')}</div>`;return richText(response?.text);}
function richText(text){return String(text||'').split(/\n\s*\n/).map(p=>`<p>${esc(p).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\n/g,'<br>')}</p>`).join('');}
function renderAssumptions(a){const list=[...(a.assumptions||[]),...(a.warnings||[]),...(a.explanation?.limitations||[])];return list.length?`<details style="margin-top:15px"><summary class="muted" style="font-size:11px;cursor:pointer">假设与适用边界 · ${list.length} 项</summary><ul class="assumption-list">${list.map(v=>`<li>${esc(typeof v==='string'?v:v.message||v.title||JSON.stringify(v))}</li>`).join('')}</ul></details>`:'';}
function renderEquity(){const a=state.analysis,players=a.players||[],p=players.find(v=>v.id===state.scenario.players[state.selectedPlayer]?.id)||players[0],rows=(p?.combos||[]).filter(c=>!state.equityFilter||(c.label||c.hand||'').toLowerCase().includes(state.equityFilter.toLowerCase()));return `<div class="result-grid"><div><div class="row spread" style="margin-bottom:22px"><h3>各方摊牌权益</h3><span class="badge ${a.exact?'green':'amber'}">${a.exact?'精确枚举':'采样估计'}</span></div><div class="equity-bars">${players.map((v,i)=>`<div class="equity-row"><span>${esc(v.position||v.name)}</span><div class="bar-track"><div class="bar-fill tone${i}" style="width:${Math.max(0,Math.min(100,Number(v.equity)*100))}%"></div></div><b>${pct(v.equity)}</b></div>`).join('')}</div><div class="result-meta"><span>${esc(a.engine||'本地权益引擎')}</span>${a.samples?`<span>· ${fmt(a.samples,0)} ${a.exact?'兼容发牌':'样本'}</span>`:''}${a.milliseconds!==undefined?`<span>· 内核 ${fmt(a.milliseconds,1)} ms</span>`:''}</div>${!a.exact?`<p class="help">95% 近似区间：${players.map(v=>esc(v.position||v.name)+' ±'+fmt(Number(v.ci||0)*100,3)+' 个百分点').join('；')}。采样区间不衡量策略误差。</p>`:''}${a.hero?`<div class="callout" style="margin-top:20px"><div class="row spread"><span>聚焦手牌 ${inlineHand(a.hero.hand||state.scenario.hero)}</span><strong class="mono" style="font-size:20px">${pct(a.hero.equity)}</strong></div><p class="help">固定这两张牌后，重新处理所有对手的阻断关系。${a.hero.exact?'精确计算。':'95% 近似区间 ±'+fmt(Number(a.hero.ci||0)*100,3)+' 个百分点。'}</p></div>`:''}<p class="help" style="margin-top:17px">权益假设直接发完公共牌并摊牌，不包含后续弃牌、下注、权益实现或行动次序的收益。</p>${renderAssumptions(a)}</div><div><div class="row spread"><h3>${esc(p?.position||p?.name||'范围')} · 成牌结构</h3><select id="evidence-player" style="width:auto;padding:5px 8px;font-size:11px">${players.map((v,i)=>`<option value="${Math.max(0,state.scenario.players.findIndex(x=>x.id===v.id))}" ${v.id===p?.id?'selected':''}>${esc(v.position||v.name)}</option>`).join('')}</select></div><div class="composition-chart">${(p?.composition||[]).slice().reverse().map(v=>`<div class="composition-row"><span>${esc(v.name)}</span><div class="bar-track"><div class="bar-fill" style="width:${Number(v.percent)*100}%"></div></div><strong>${pct(v.percent)}</strong></div>`).join('')||'<p class="help">当前结果没有输出牌型结构。</p>'}</div><p class="help">按牌面与两张底牌的最佳成牌分类；公共牌本身的牌型也会计入。</p></div></div>${p?.combos?.length?`<div class="divider"></div><div class="row spread" style="margin-bottom:12px"><h3>${esc(p.position||p.name)} · 组合权益</h3><input id="equity-filter" style="max-width:185px;padding:6px 9px;font-size:11px" value="${esc(state.equityFilter||'')}" placeholder="搜索具体组合"></div><div class="table-scroll strategy-combo-scroll"><table class="data-table"><thead><tr><th>具体组合</th><th>输入权重</th><th>权益</th><th>采样 / 误差</th></tr></thead><tbody>${rows.slice(0,200).map(c=>`<tr><td>${inlineHand(c.label||c.hand)}</td><td class="mono">${fmt(c.weight)}</td><td class="mono">${pct(c.equity,2)}</td><td class="muted mono">${c.samples?fmt(c.samples,0)+' · ':''}${c.ci!==undefined?'±'+fmt(c.ci*100,2)+'pp':'—'}</td></tr>`).join('')}</tbody></table></div>${rows.length>200?'<p class="help">显示前 200 个组合；输入组合名称可筛选。</p>':''}`:''}`;}
function actionColor(a,i){return a.type==='fold'?'#83929a':a.type==='check'||a.type==='call'?'#9dbb87':a.type==='raise'?'#dc8d77':colors[i%colors.length];}
function renderTree(){const n=state.node,j=state.job,d=j?.diagnostics||j?.result?.diagnostics,stats=j?.stats||j?.result?.stats;if(!n)return `<div class="empty"><span class="empty-icon">${icon('branch')}</span><h3>${state.solving?'正在生成可追踪的行动树':'查看一整段范围如何分配行动'}</h3><p>求解后可沿 bet、call、raise、re-raise 分支继续查看。每个节点同时展示组合策略、行动 EV 和到达权重。</p>${!state.solving?btn('检查建树设置','solve-settings','small'):''}</div>`;const rows=(n.combos||[]).filter(c=>strategyMatch(c)),actor=state.scenario.players[n.actor],terminal=n.terminal;return `<div class="tree-breadcrumb"><button data-action="tree-back" data-depth="0">本街起点</button>${state.nodePath.map((a,i)=>`<span class="faint">›</span><button data-action="tree-back" data-depth="${i+1}">${esc(actionLabel(a))}</button>`).join('')}</div><div class="row spread wrap"><div><h3>${terminal?'本条行动线已结束':esc(actor?.position||n.actorId||'玩家')+' 行动'}${!terminal?`<span class="badge" style="margin-left:9px">节点 ${esc(n.id)}</span>`:''}</h3><p class="help">底池 ${fmt(n.pot)} BB${n.toCall!==undefined?' · 需跟 '+fmt(n.toCall)+' BB':''}${n.reach!==undefined?' · 到达权重 '+fmt(n.reach,5):''}</p></div>${compactBoard(n.board||state.jobScenario?.board||state.scenario.board)===compactBoard(state.jobScenario?.board||state.scenario.board)?`<div class="cards-row tree-current-board" aria-label="当前决策公共牌">${boardHTML(n.board||state.jobScenario?.board||state.scenario.board,true)}</div>`:''}${state.nodePath.length?btn(icon('back')+'上一步','tree-up','small'):''}</div>${terminal?`<div class="callout" style="margin-top:18px">${esc(n.reason||n.type||'摊牌或其余玩家弃牌；本节点没有后续决策。')}${n.payoffs?'<p>'+n.payoffs.map((v,i)=>esc(state.scenario.players[i]?.position||i)+': '+signed(v)+' BB').join(' · ')+'</p>':''}</div>`:`<div class="action-grid">${(n.actions||[]).map((a,i)=>`<button class="action-card" data-action="tree-action" data-id="${esc(a.id)}" style="--action-color:${actionColor(a,i)}"><b>${esc(a.label||actionLabel(a.id))}</b><div class="action-frequency">${a.frequency===null||a.frequency===undefined?'—':pct(a.frequency)}</div><small>${a.ev===null||a.ev===undefined?'EV 未输出':signed(a.ev)+' BB'} · 查看后续 →</small><span class="action-strip"></span></button>`).join('')}</div><p class="help">EV 以当前决策点继续投入为口径，弃牌 EV = 0；当前街已投入属于沉没成本。聚合频率按到达此节点的合法联合分布加权。</p><div class="row spread wrap" style="margin:21px 0 11px"><h3>逐组合策略与行动 EV</h3><input id="strategy-filter" style="max-width:180px;padding:6px 9px;font-size:11px" value="${esc(state.strategyFilter||'')}" placeholder="筛选，例如 AcKd">${rows.length>250?btn(state.allCombos?'只显示前250个':'查看全部 '+rows.length+' 个组合','toggle-all-combos','ghost small'):''}</div><div class="table-scroll strategy-combo-scroll"><table class="data-table"><thead><tr><th>具体组合</th><th>到达权重</th><th>策略构成</th>${(n.actions||[]).map(a=>`<th>${esc(a.label||actionLabel(a.id))}<br><small>频率 / EV</small></th>`).join('')}</tr></thead><tbody>${rows.slice(0,state.allCombos?rows.length:250).map(c=>`<tr class="${sameHand(c.combo||c.hand,state.scenario.hero)?'hero-row':''}"><td>${inlineHand(c.combo||c.hand)}</td><td class="mono">${fmt(c.reach??c.weight,5)}</td><td><div class="strategy-stack">${(c.probabilities||[]).map((p,i)=>`<span style="width:${Math.max(0,Number(p)*100)}%;background:${actionColor(n.actions[i],i)}" title="${esc(n.actions[i]?.label||'')} ${pct(p)}"></span>`).join('')}</div></td>${(c.probabilities||[]).map((p,i)=>`<td class="mono">${pct(p)}<br><small class="muted">${c.actionEV?.[i]!==null&&c.actionEV?.[i]!==undefined?signed(c.actionEV[i])+' BB':'—'}</small></td>`).join('')}</tr>`).join('')||`<tr><td colspan="10">没有可解释的正权重到达组合，或当前筛选无结果。</td></tr>`}</tbody></table></div>`}${d&&numeric(d.nashConv)?`<details style="margin-top:20px"><summary class="muted" style="cursor:pointer;font-size:11px">求解证据：各玩家最佳应对增益与计算规模</summary><div class="table-scroll" style="margin-top:11px"><table class="data-table"><thead><tr><th>玩家</th><th>当前策略 EV</th><th>最佳应对 EV</th><th>偏离增益</th></tr></thead><tbody>${(d.gain||[]).map((v,i)=>`<tr><td>${esc(state.scenario.players[i]?.position||i)}</td><td>${signed(d.profileEV?.[i])} BB</td><td>${signed(d.bestResponseEV?.[i])} BB</td><td>${fmt(v,5)} BB</td></tr>`).join('')}</tbody></table></div><p class="help">NashConv = ${fmt(d.nashConv,5)} BB。${esc(d.verifiedBy||'')}。只适用于这棵有限树及其输入范围，不等于真实牌局全尺寸误差。</p>${stats?`<p class="help">${fmt(stats.publicNodes,0)} 个公开节点 · ${fmt(stats.legalDeals,0)} 种合法联合发牌 · ${fmt(stats.infoSets,0)} 个信息集 · ${esc(stats.algorithm||'')}</p>`:''}</details>`:''}${(j?.result?.limits||j?.limits||[]).length?`<ul class="assumption-list">${(j.result?.limits||j.limits).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}`;}
function sameHand(a,b){try{return cards(a).sort().join(',')===cards(b).sort().join(',');}catch{return false;}}
function actionLabel(id){const s=String(id);if(/^(river|deal)_[2-9TJQKA][cdhs]$/i.test(s)){const c=s.slice(s.indexOf('_')+1);return '发牌 '+c[0]+symbols[c[1].toLowerCase()];}return s.replace(/^check$/i,'过牌').replace(/^call$/i,'跟注').replace(/^fold$/i,'弃牌').replace(/^allin$/i,'全下').replace(/^bet[_ ]?/i,'下注 ').replace(/^raise[_ ]?/i,'加注到 ');}
function renderComparison(){const a=state.baseline,b=state.analysis;if(!a)return `<div class="empty"><span class="empty-icon">${icon('copy')}</span><h3>只改变一个条件，观察结论是否改变</h3><p>先完成一次权益计算，将它固定为 A。然后修改一位玩家的范围、一个花色或一个筹码条件，重新计算得到 B。</p>${btn('将当前权益结果固定为 A','pin-baseline','primary',!b||stale()?'disabled':'')}</div>`;const changes=diffScenario(a.scenario,state.scenario);return `<div class="row spread wrap" style="margin-bottom:16px"><div><h3>假设对照 A / B</h3><p class="help">目前比较的是范围权益；筹码与下注的变化需要重新求解策略树才有决策意义。</p></div>${btn('替换对照 A','pin-baseline','small',!b||stale()?'disabled':'')}</div><div class="compare-change">变化项：${changes.length?changes.map(esc).join('、'):'尚未改变条件'}。${changes.length>1?'同时改变了多个条件，不能把差异归因于单一因素。':'先预测方向，再看计算结果。'}</div><div class="compare-grid">${[{label:'A · 固定基线',data:a},{label:'B · 当前结果',data:b}].map(({label,data})=>`<div class="compare-card"><div class="compare-label">${label}</div>${data?`<div class="cards-row" style="justify-content:flex-start">${boardHTML(data.scenario?.board||state.scenario.board,true)}</div><div class="equity-bars" style="margin-top:18px">${(data.players||[]).map((p,i)=>`<div class="equity-row"><span>${esc(p.position||p.name)}</span><div class="bar-track"><div class="bar-fill tone${i}" style="width:${p.equity*100}%"></div></div><b>${pct(p.equity)}</b></div>`).join('')}</div>`:'<p class="muted">修改条件并计算后，将在此显示。</p>'}</div>`).join('')}</div>${b&&!stale()?`<div class="table-scroll" style="margin-top:16px"><table class="data-table"><thead><tr><th>玩家</th><th>A 权益</th><th>B 权益</th><th>B − A</th></tr></thead><tbody>${(b.players||[]).map((p,i)=>`<tr><td>${esc(p.position||p.name)}</td><td>${pct(a.players?.find(v=>v.id===p.id)?.equity,2)}</td><td>${pct(p.equity,2)}</td><td class="mono">${a.players?.find(v=>v.id===p.id)?signed((p.equity-a.players.find(v=>v.id===p.id).equity)*100)+' 个百分点':'新增玩家'}</td></tr>`).join('')}</tbody></table></div>`:''}<div class="callout" style="margin-top:17px">下一步：如果权益变化很小，行动 EV 仍可能明显变化。对手面对你的加注如何继续，以及身后玩家的响应，必须在行动树里验证。</div>`;}
function diffScenario(a,b){const changes=[];for(const [k,l]of [['board','公共牌'],['hero','聚焦手牌'],['heroSeat','手牌位置'],['pot','起始底池'],['toAct','行动顺序'],['rake','抽水']])if(JSON.stringify(a?.[k])!==JSON.stringify(b[k]))changes.push(l);if(a?.players?.length!==b.players.length)changes.push('玩家人数');b.players.forEach((p,i)=>{if(a?.players?.[i]?.range!==p.range)changes.push(`${p.position} 范围`);if(a?.players?.[i]?.stack!==p.stack)changes.push(`${p.position} 筹码`);});return changes;}
function renderTraining(){if(state.lesson)return renderActiveLesson();const themes=[...new Set(state.lessons.map(l=>l.theme||l.skill).filter(Boolean))],lessons=state.lessons.filter(l=>state.trainingFilter==='all'||(l.theme||l.skill)===state.trainingFilter);return `<div class="page-heading"><div><div class="eyebrow">UNDERSTAND. TRANSFER. RETAIN.</div><h1 style="margin-top:6px">专项训练</h1><p class="subtitle">先独立判断，再看证据解释。学会一个机制，然后在新条件下重建判断。</p></div>${dueCount()?btn(icon('clock')+`复习 ${dueCount()} 项`,'due-training','primary'):''}</div><div class="callout" style="margin-bottom:23px">每道题注明参考模型。条件 EV 题训练收益机制；概念题训练关键变量识别。它们不会被包装成整局 GTO 答案。</div><div class="row wrap" style="margin-bottom:19px"><button class="pill ${state.trainingFilter==='all'?'active':''}" data-action="training-filter" data-value="all">全部主题</button>${themes.map(t=>`<button class="pill ${state.trainingFilter===t?'active':''}" data-action="training-filter" data-value="${esc(t)}">${esc(t)}</button>`).join('')}</div><div class="lesson-grid">${lessons.map((l,i)=>`<button class="panel lesson-card" data-action="lesson" data-id="${esc(l.id)}"><div class="lesson-symbol">${String(i+1).padStart(2,'0')}</div><div class="row wrap"><span class="badge">${esc(l.theme||l.skill||'决策机制')}</span>${l.variantOf?'<span class="badge amber">迁移练习</span>':''}</div><h3>${esc(l.title)}</h3><p>${esc(l.description||l.objective||'先选行动与理由，再查看可核验的解释。')}</p><div class="lesson-bottom"><span>${esc(l.difficulty||'进阶')} · ${l.minutes||5} 分钟</span><span class="accent">开始 ${icon('arrow')}</span></div></button>`).join('')||'<div class="panel empty" style="grid-column:1/-1"><h3>训练课正在载入</h3><p>若本地服务尚未准备完成，可以先在研究台编辑局面。</p></div>'}</div>`;}
function lessonScenario(l){return l.scenario||l.context||{};}
function renderActiveLesson(){const raw=state.lesson,l=raw.assessment&&!state.feedback?{...raw,title:'独立判断 · 先完成这次决策',theme:'不提前提供主题提示'}:raw,s=l.displayScenario||lessonScenario(l),f=state.feedback;return `<div class="training-shell"><div class="training-top">${btn(icon('back')+'所有训练','leave-lesson','ghost small')}<div class="training-progress"><span class="done"></span><span class="${state.answer?'done':''}"></span><span class="${f?'done':''}"></span></div><span class="badge">${esc(l.theme||l.skill||'专项训练')}</span></div><div class="page-heading"><div><div class="eyebrow">${l.variantOf?'TRANSFER CHECK':'THINK BEFORE REVEAL'}</div><h1 style="margin-top:6px;font-size:25px">${esc(l.title)}</h1></div><span class="muted" style="font-size:11px">${l.minutes||5} 分钟 · ${esc(l.difficulty||'进阶')}</span></div><div class="training-grid"><aside class="panel training-context"><h3>题目条件</h3>${s.board?`<div class="cards-row">${boardHTML(s.board)}</div>`:''}${s.hero?`<div class="row" style="justify-content:center;margin-bottom:15px"><span class="muted" style="font-size:11px">Hero</span>${boardHTML(s.hero,true)}</div>`:''}${s.description?`<p class="help">${esc(s.description)}</p>`:''}${s.pot!==undefined?`<div class="context-item"><span class="muted">${l.private?'当前节点底池':s.bet?'对手下注前底池':'起始底池'}</span><strong class="mono">${fmt(s.pot)} BB</strong></div>`:''}${s.bet!==undefined?`<div class="context-item"><span class="muted">对手下注</span><strong class="mono">${fmt(s.bet)} BB</strong></div>`:''}${s.stack!==undefined?`<div class="context-item"><span class="muted">有效剩余筹码</span><strong class="mono">${fmt(s.stack)} BB</strong></div>`:''}${s.players?.length?`<div class="context-item"><span class="muted">底池人数</span><strong>${s.players.length} 人</strong></div>`:''}${Object.entries(s).filter(([k,v])=>!['title','board','hero','pot','bet','stack','players','description','notes','format','heroSeat','toAct','unit','version'].includes(k)&&typeof v!=='object').slice(0,8).map(([k,v])=>`<div class="context-item"><span class="muted">${esc(({raiseTo:'加注到',worseCallFrequency:'较差牌跟注比例',rake:'抽水',rakeCap:'抽水封顶',alpha:'较差 Kx 跟注比例',opponentRange:'对手下注范围',range:'对手范围'}[k])||k)}</span><span style="text-align:right;max-width:60%;word-break:break-word">${esc(typeof v==='number'?fmt(v):v)}</span></div>`).join('')}${s.notes?`<div class="callout" style="margin-top:15px;font-size:11px">${esc(s.notes)}</div>`:''}${l.assumptions?.length?`<ul class="assumption-list">${l.assumptions.map(a=>`<li>${esc(a)}</li>`).join('')}</ul>`:''}<div class="divider"></div><p class="help">不要先猜软件期待的按钮。给出你真实会执行的判断，再记录自己有多确定。</p></aside><section class="panel training-question"><span class="eyebrow">01 / YOUR DECISION</span><h2>${esc(l.prompt)}</h2><div class="choice-list">${(l.choices||[]).map((c,i)=>`<button class="choice ${state.answer===c.id?'selected':''}" data-action="answer" data-id="${esc(c.id)}" ${f?'disabled':''}><span class="choice-key">${String.fromCharCode(65+i)}</span><span>${esc(c.label)}</span></button>`).join('')}</div>${l.reasonChoices?.length?`<div class="divider"></div><span class="eyebrow">02 / YOUR REASON</span><h4 style="margin-top:8px">关键依据是什么？<span class="muted" style="font-weight:400;font-size:10px"> 至少选一项，可多选</span></h4><div class="reason-list">${l.reasonChoices.map(c=>`<label class="reason-choice"><input type="checkbox" data-reason="${esc(c.id)}" ${state.reasons.includes(c.id)?'checked':''} ${f?'disabled':''}><span>${esc(c.label)}</span></label>`).join('')}</div>`:''}<div class="divider"></div><div class="row spread"><span class="eyebrow">${l.reasonChoices?.length?'03':'02'} / YOUR CONFIDENCE</span><span class="muted" style="font-size:10px">不确定也是有价值的信息</span></div><div class="confidence-row"><span class="muted" style="font-size:10px">猜测</span><input type="range" min="0" max="100" step="5" id="confidence" value="${state.confidence}" ${f?'disabled':''} aria-label="判断信心"><span class="muted" style="font-size:10px">确定</span><strong id="confidence-value">${state.confidence}%</strong></div>${!f?`<div class="row" style="justify-content:flex-end;margin-top:23px">${btn(state.grading?'<span class="spinner"></span>记录判断…':'提交判断 · 查看证据 '+icon('arrow'),'submit-answer','primary',!state.answer||state.grading||(l.reasonChoices?.length&&!state.reasons.length)?'disabled':'')}</div>`:''}</section></div>${f?renderFeedback(f,l):''}</div>`;}
function renderFeedback(f,l){const correct=f.correct??f.isCorrect??f.actionCorrect,ex=f.explanation,sections=f.sections||f.evidence||[];return `<section class="feedback-card ${correct===false?'incorrect':''}"><div class="row spread wrap"><div class="row">${icon(correct?'check':'target')}<h3 style="margin:0">${esc(f.headline||f.title||(correct?'行动判断与参考模型一致':'这里有一个值得修正的机制'))}</h3></div><span class="badge ${correct?'green':'amber'}">判断已记录</span></div>${numeric(f.loss)||numeric(f.evLoss)?`<div class="feedback-metrics"><div><strong>${fmt(f.evLoss??f.loss,3)}</strong><small>参考模型下行动损失 · BB</small></div>${f.referenceEV!==undefined?`<div><strong>${signed(f.referenceEV)}</strong><small>参考行动 EV · BB</small></div>`:''}</div>`:''}${typeof ex==='string'?richText(ex):ex?.body?richText(ex.body):''}${f.body?richText(f.body):''}${Array.isArray(sections)?sections.map(v=>typeof v==='string'?`<p>${esc(v)}</p>`:`<div class="evidence-card" style="margin-top:12px"><h4>${esc(v.title||v.label||'计算证据')}</h4><p>${esc(v.body||v.text||(v.value!==undefined?(v.unit==='比例'?pct(v.value,2):fmt(v.value,3)+' '+(v.unit||'')):''))}${v.calculation?'<br><span class="mono">'+esc(v.calculation)+'</span>':''}</p></div>`).join(''):''}${f.reasonFeedback?.length?`<div class="callout" style="margin-top:15px">${esc(Array.isArray(f.reasonFeedback)?f.reasonFeedback.join(' '):f.reasonFeedback)}</div>`:''}${f.principle||f.takeaway?`<div class="coach-principle" style="margin-top:16px"><span class="eyebrow">TAKE THIS TO THE TABLE</span><p>${esc(f.principle||f.takeaway)}</p></div>`:''}${f.counterexample?`<p><strong>结论何时改变：</strong>${esc(f.counterexample)}</p>`:''}${f.nextReviewAt?`<p class="help">下次复习：${time(f.nextReviewAt)}。复习表现与本次练习分别记录。</p>`:''}<div class="row wrap" style="justify-content:flex-end;margin-top:22px">${btn('回到课程','leave-lesson','small')}${canStudyLesson(l)?btn('带到研究台','lesson-to-study','small'):''}${btn('下一道 · 检验迁移 '+icon('arrow'),'next-lesson','primary')}</div></section>`;}
function canStudyLesson(l){const s=l.scenario;return !!(s?.players?.length>=2&&s?.board);}
function renderLibrary(){const cases=state.cases.filter(c=>{const s=c.scenario||c.state||{};return (!state.caseFilter||`${c.title} ${c.notes||s.notes||''} ${s.board||''}`.toLowerCase().includes(state.caseFilter.toLowerCase()))&&(state.caseFormat==='all'||s.format===state.caseFormat);});return `<div class="page-heading"><div><div class="eyebrow">YOUR RESEARCH, CONNECTED</div><h1 style="margin-top:6px">研究档案</h1><p class="subtitle">保留当时的参数、范围与判断依据。把一次研究变成可以继续验证的资产。</p></div><div class="row">${btn(icon('upload')+'导入案例','import-json')}${btn(icon('plus')+'新研究','new-study','primary')}</div></div><div class="library-toolbar"><div class="search-field">${icon('search')}<input id="case-search" value="${esc(state.caseFilter)}" placeholder="搜索标题、牌面或研究笔记"></div><div class="format-toggle">${[['all','全部'],['online','线上'],['live','现场']].map(([v,l])=>`<button class="${state.caseFormat===v?'active':''}" data-action="case-format" data-value="${v}">${l}</button>`).join('')}</div><span class="muted" style="margin-left:auto;align-self:center;font-size:11px">${cases.length} 个案例</span></div><div class="case-grid">${cases.map(renderCaseCard).join('')||`<div class="panel empty" style="grid-column:1/-1"><span class="empty-icon">${icon('library')}</span><h3>${state.caseFilter?'没有匹配的案例':'你的第一个研究，值得留下来'}</h3><p>在研究台保存局面，就能保留范围、参数和笔记。也可以导入以前导出的 PokerLab 案例。</p>${btn('进入研究台','nav','primary','data-route="study"')}</div>`}</div>${state.jobs.length?`<div class="section-gap"><div class="section-title"><h2>计算历史</h2><input id="job-search" style="max-width:300px;font-size:11px" value="${esc(state.jobFilter||'')}" placeholder="搜索历史标题、牌面或任务编号"></div><div class="panel table-scroll job-history-scroll"><table class="data-table"><thead><tr><th>研究局面</th><th>计算状态</th><th>时间</th><th></th></tr></thead><tbody>${state.jobs.filter(j=>!state.jobFilter||`${j.scenario?.title||j.title||''} ${j.scenario?.board||''} ${j.id}`.toLowerCase().includes(state.jobFilter.toLowerCase())).map(j=>`<tr><td>${esc(j.scenario?.title||j.input?.title||j.title||'策略研究')}<br><small class="muted">${esc(j.scenario?.board||j.input?.board||'')}</small></td><td>${esc(({complete:'完成',completed:'完成',running:'计算中',queued:'等待',cancelling:'停止中',failed:'失败',cancelled:'已取消'}[j.status])||j.status)}</td><td class="muted">${time(j.createdAt)}</td><td>${btn('打开','load-job','small',`data-id="${esc(j.id)}"`)}</td></tr>`).join('')}</tbody></table></div></div>`:''}`;}
function renderCaseCard(c){const s=c.scenario||c.state||{},a=c.analysis||c.result;return `<article class="panel case-card"><div class="row spread"><span class="badge">${s.format==='live'?'现场':'线上'} · ${s.players?.length||2} 人</span><span class="faint" style="font-size:10px">${date(c.savedAt||c.createdAt)}</span></div><h3>${esc(c.title||s.title||'未命名研究')}</h3><div class="cards-row">${boardHTML(s.board,true)}</div><p>底池 ${fmt(s.pot)} BB${s.players?.length?' · '+s.players.map(p=>esc(p.position)).join(' / '):''}<br>${esc((c.notes||s.notes||'尚未填写研究假设').slice(0,105))}</p><div class="case-footer">${btn('继续研究 '+icon('arrow'),'load-case','small',`data-id="${esc(c.id)}"`)}${btn(icon('download'),'export-case','ghost small',`data-id="${esc(c.id)}" title="导出案例"`)}${c.needsRanges||c.draft?'<span class="badge amber" style="margin-left:auto">草稿 · 范围待补</span>':a?'<span class="badge" style="margin-left:auto">有权益记录</span>':''}</div></article>`;}
function renderProgress(){const s=state.summary||{},attempts=s.recentAttempts||s.recent||s.attempts||[],skills=Array.isArray(s.skills)?s.skills:Object.entries(s.skills||{}).map(([name,v])=>({name,...v}));return `<div class="page-heading"><div><div class="eyebrow">MEASURE WHAT YOU CAN TRANSFER</div><h1 style="margin-top:6px">能力档案</h1><p class="subtitle">行动、推理、信心与保持分别观察。练习次数不等于实战提升。</p></div>${btn(icon('refresh')+'更新','refresh-summary','small')}</div><div class="metric-grid"><div class="panel metric"><span class="muted">已完成判断</span><div class="metric-number">${state.summary?attemptCount():'—'}<small>次</small></div><div class="metric-note">来自本机真实训练记录</div></div><div class="panel metric"><span class="muted">行动正确率</span><div class="metric-number">${s.accuracy!==undefined?pct(s.accuracy,0):'—'}</div><div class="metric-note">只在每道题注明的模型内评判</div></div><div class="panel metric"><span class="muted">高信心错误</span><div class="metric-number">${s.highConfidenceErrors??'—'}<small>次</small></div><div class="metric-note">优先复查“确定但判断错误”</div></div><div class="panel metric"><span class="muted">待复习</span><div class="metric-number">${state.summary?dueCount():'—'}<small>项</small></div><div class="metric-note">检测延迟后的独立判断能力</div></div></div><div class="progress-grid section-gap"><section class="panel"><div class="panel-header"><h3>按能力观察</h3><span class="badge">样本量保持可见</span></div><div class="panel-body">${skills.length?skills.map(v=>`<div class="skill-row"><div>${esc(v.name||v.theme||v.skill)}<br><small>${v.attempts??v.count??v.total??0} 次练习</small></div><div class="bar-track"><div class="bar-fill" style="width:${Math.max(0,Math.min(100,Number(v.accuracy||0)*100))}%"></div></div><span class="mono">${v.accuracy===undefined?'—':pct(v.accuracy,0)}</span></div>`).join(''):'<div class="empty"><h3>先建立你的真实基线</h3><p>完成几道不同主题的训练后，这里将显示各能力的表现。软件不会根据尚未提供的牌谱推断你的漏洞。</p>'+btn('开始专项训练','nav','primary','data-route="train"')+'</div>'}</div></section><section class="panel"><div class="panel-header"><h3>下一次值得练什么</h3>${icon('target')}</div><div class="panel-body">${dueCount()?`<p class="help">目前有 ${dueCount()} 项到期复习。先在没有提示的情况下重新判断，再查看先前解析。</p>${btn('开始到期复习','due-training','primary','style="margin-top:17px"')}`:'<p class="help">目前没有到期复习。你可以选择尚未完成的主题，或者带一个真实牌局进入研究台。系统会根据实际表现安排后续复测。</p>'}<div class="divider"></div><h4>怎样判断自己真的进步</h4><ul class="assumption-list"><li>陌生局面中的判断是否更稳定。</li><li>能否指出让结论改变的条件。</li><li>数天后能否无提示复现推理。</li><li>高信心且有损失的错误是否减少。</li></ul><p class="help">短期盈亏噪声很大；这里不把刷题表现换算成承诺的 bb/100。</p></div></section></div><div class="panel section-gap"><div class="panel-header"><h3>最近的判断</h3><span class="muted" style="font-size:10px">复盘答案，也复盘当时的信心</span></div><div class="panel-body"><div class="attempt-list">${attempts.slice(0,15).map(v=>{const correct=v.correct??v.actionCorrect;return `<div class="attempt-item"><span class="attempt-icon ${correct===false?'review':''}">${icon(correct?'check':'target')}</span><div class="grow"><h4>${esc(v.title||v.lessonTitle||state.lessons.find(l=>l.id===v.lessonId)?.title||v.lessonId||'训练判断')}</h4><p>${correct===undefined?'已记录':correct?'行动判断一致':'需要复查'} · 信心 ${v.confidence??'—'}%${v.evLoss!==undefined?' · 模型损失 '+fmt(v.evLoss)+' BB':''}${v.elapsedMs?' · '+fmt(v.elapsedMs/1000,1)+' 秒':''}</p></div><small class="faint">${time(v.createdAt||v.at)}</small></div>`;}).join('')||'<div class="empty"><p>提交第一次判断后，记录会出现在这里。</p></div>'}</div></div></div>`;}
function openModal(title,description,body,footer=''){$('#modal').classList.remove('live-recorder-modal');state.modalEpoch=(state.modalEpoch||0)+1;const modal=$('#modal');$('#modal-body').innerHTML=`<div class="modal-head"><div><h2>${esc(title)}</h2>${description?`<p>${esc(description)}</p>`:''}</div><button class="icon-button" data-action="close-modal" aria-label="关闭弹窗">${icon('close')}</button></div><div class="modal-content">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!modal.open)modal.showModal();}
function closeModal(){state.modalEpoch=(state.modalEpoch||0)+1;$('#modal').close();state.picker=null;}
function showPicker(target,index){const cs=parseCards(state.scenario[target]);state.picker={target,index:Math.min(Number(index),cs.length)};renderPicker();}
function renderPicker(){const {target,index}=state.picker,cs=parseCards(state.scenario[target]),other=parseCards(state.scenario[target==='board'?'hero':'board']),max=target==='board'?5:2;openModal(target==='board'?'选择公共牌':'选择聚焦手牌','点击一张牌后自动移到下一格；花色和阻断关系会同步更新。',`<div class="picker-targets">${Array.from({length:max},(_,i)=>card(cs[i],false,`class="${i===index?'active':''}" data-action="picker-slot" data-index="${i}"`).replace('clickable',i===index?'clickable active':'clickable')).join('')}</div><div class="deck">${['s','h','c','d'].flatMap(suit=>[...GRID].map(rank=>{const t=rank+suit,c=parseCards(t)[0],taken=other.includes(c)||cs.some((v,i)=>v===c&&i!==index);return `<button class="playing-card ${suit} ${cs[index]===c?'selected':''}" data-action="pick-card" data-card="${t}" ${taken?'disabled':''} aria-label="${t}"><span>${rank}</span><i>${symbols[suit]}</i></button>`;})).join('')}</div><p class="help">♠ 黑桃　<span class="inline-card h">♥ 红桃</span>　<span class="inline-card c">♣ 梅花</span>　<span class="inline-card d">♦ 方块</span>。已被占用的牌会禁用。</p>`,btn('移除当前牌','remove-card','ghost')+btn('完成','close-modal','primary'));}
function showImport({repair=false}={}){state.importRepairContext=repair?clone(state.scenario.inputContext||{}):null;state.parse=null;openModal('快捷录入一个牌局','粘贴已支持的线上牌谱，或用中文记录现场牌局。自动识别的金额与行动会先展示给你核对。',`<div class="row spread" style="margin-bottom:12px"><span class="badge">保留原始文本</span><button class="button ghost small" data-action="fill-import-example">填入中文示例</button></div><p class="help">整手现场速记请写明盲注、发牌前筹码和各街行动；加注请写“到多少”。只研究一个街起点时，可直接写公共牌、底池、各玩家筹码与范围。</p><textarea id="import-text" class="import-text" placeholder="例如：六人桌，SB/BB 为 0.5/1 BB。BTN 100BB，SB 150BB，BB 80BB。BTN 加注到3BB，SB跟注，BB跟注。翻牌 Qh Ts 7h，SB过牌，BB过牌，BTN下注6BB。我在SB，Ah Jh。">${esc(state.importText??state.scenario.inputContext?.raw??'')}</textarea><div class="field-row" style="margin-top:12px"><label><span class="label">原始金额单位</span><select id="import-unit"><option value="BB">BB（大盲）</option><option value="currency">实际金额</option></select></label><label><span class="label">大盲金额 · 货币模式时填写</span><input id="import-big-blind" type="number" min="0.01" value="1"></label></div><div id="parse-preview" class="parse-preview"></div>`,btn('取消','close-modal','ghost')+btn('现场逐步记录','live-open','small')+btn('批量牌谱文件','inbox-import','small')+btn(icon('spark')+'重建并核对','parse','primary'));const options=state.importOptions||{unit:state.scenario.inputContext?.sourceUnit||'BB',bigBlind:state.scenario.inputContext?.sourceBigBlind||1};$('#import-unit').value=options.unit;$('#import-big-blind').value=options.bigBlind;}
function importSignature(){return JSON.stringify({text:$('#import-text')?.value,unit:$('#import-unit')?.value,bigBlind:$('#import-big-blind')?.value});}
function invalidateImport(){state.parse=null;const preview=$('#parse-preview');if(preview&&preview.innerHTML)preview.innerHTML='<div class="callout warn">原文或金额口径已改变，请重新识别并核对。</div>';}
function renderParsePreview(){const p=state.parse;if(!p)return;const s=p.scenario,hasErrors=(p.issues||[]).some(v=>v.severity==='error'),issues=[...(p.issues||[]),...(p.missing||[]).map(v=>typeof v==='string'?{severity:'warning',message:'待补充：'+v}:v)];$('#parse-preview').innerHTML=`<div class="divider"></div><div class="row spread"><h3>识别草稿</h3><span class="badge ${p.ok&&!hasErrors?'green':'amber'}">${hasErrors?'原文尚有错误 · 暂不能计算':p.ok?'已解析 · 请核对':'需要补充或核对'}</span></div>${importStreetSelector(p)}${s?`<div class="callout" style="margin-top:12px">${s.board?'公共牌 '+inlineHand(s.board)+'<br>':''}本街起点底池 ${fmt(s.pot)} BB · ${s.players?.length||0} 名玩家${s.players?.length?'<br>'+s.players.map(v=>esc(v.position||v.name)+' 剩余 '+fmt(v.stack)+' BB').join(' · '):''}</div>`:''}${issues.map(v=>`<div class="issue ${v.severity==='error'?'error':''}">${esc(v.message||v.code||JSON.stringify(v))}</div>`).join('')}${p.ledger?.length?`<details style="margin-top:13px" open><summary class="muted" style="font-size:11px;cursor:pointer">行动账本 · ${p.ledger.length} 条</summary><div class="parse-ledger"><table class="data-table"><thead><tr><th>街 / 玩家</th><th>行动</th><th>金额</th></tr></thead><tbody>${p.ledger.map(v=>`<tr><td>${esc(({preflop:'翻前',flop:'翻牌',turn:'转牌',river:'河牌'}[v.street])||v.street||'')} ${esc(v.player||v.position||v.actor||'')}</td><td>${esc(({post:'投入盲注',raiseTo:'加注到',call:'跟注',street:'发出公共牌',check:'过牌',bet:'下注',fold:'弃牌',allin:'全下'}[v.action||v.type])||v.action||v.type||v.text||'')}${v.inferred?' <span class="badge amber">推导</span>':''}</td><td>${fmt(v.amount??v.to??v.pot)} ${v.amount!==undefined||v.to!==undefined?'BB':''}</td></tr>`).join('')}</tbody></table></div></details>`:''}${p.assumptions?.length?`<ul class="assumption-list">${p.assumptions.map(v=>`<li>${esc(typeof v==='string'?v:v.message||JSON.stringify(v))}</li>`).join('')}</ul>`:''}${s?.players?.length>=2?`<div class="row" style="justify-content:flex-end;margin-top:17px">${btn((hasErrors?'保留未核对草稿 · 暂不能计算':'将草稿带入研究台')+' '+icon('arrow'),'apply-parse',hasErrors?'small':'primary')}</div>`:''}`;}
function examples(){const m=state.metadata||{};return m.examples||m.scenarios||m.samples||[];}
function showTemplates(){const list=examples();openModal('选择一个研究起点','这些是明确标注假设的研究样例，可以更换所有参数与范围。',`<div class="template-list">${list.length?list.map((v,i)=>{const s=v.scenario||v;return `<button class="template-button" data-action="template" data-index="${i}"><span class="lesson-symbol" style="font:20px var(--mono);color:var(--accent2)">${String(i+1).padStart(2,'0')}</span><div class="grow"><h4>${esc(v.title||s.title)}</h4><p>${esc(v.description||s.notes||'可编辑研究假设')}<br>${s.players?.length||2} 人 · ${esc(s.board||'')} · ${fmt(s.pot)} BB</p></div>${icon('arrow')}</button>`;}).join(''):`<div class="empty"><p>服务尚未提供样例目录。你可以直接编辑当前局面。</p>${btn('使用三人河牌起点','default-template','primary')}</div>`}</div>`);}
function showCommands(){openModal('快速操作','研究快捷键：Ctrl / ⌘ + Enter 计算权益；Ctrl / ⌘ + S 保存案例。',`<div>${[['study','进入局面研究','study'],['train','开始专项训练','train'],['library','打开研究档案','library'],['progress','查看能力档案','progress']].map(([i,t,r])=>`<button class="command-item" data-action="command-nav" data-route="${r}">${icon(i)}${t}${icon('arrow')}</button>`).join('')}<div class="divider"></div><button class="command-item" data-action="import">${icon('paste')}粘贴牌谱或中文速记</button><button class="command-item" data-action="templates">${icon('target')}选择研究样例</button><button class="command-item" data-action="capabilities">${icon('cpu')}查看引擎与数学边界</button></div>`);}
function showCapabilities(){const m=state.metadata||{},engines=Array.isArray(m.engines)?m.engines:Array.isArray(m.capabilities)?m.capabilities:[];openModal('本地计算能力与边界','每项结果都应说明：计算了什么、没有计算什么，以及误差从哪里来。',`<div class="callout"><strong>权益、策略与解释是三项不同任务。</strong><br>GPU 权益计算速度不代表策略求解速度；流畅的文字也不能代替行动树。</div>${engines.length?`<div class="table-scroll" style="margin-top:17px"><table class="data-table capability-table"><thead><tr><th>引擎</th><th>适用范围</th><th>限制与状态</th></tr></thead><tbody>${engines.map(v=>`<tr><td>${esc(v.name||v.id||v.engine)}</td><td>${esc(v.description||v.scope||[v.players?'人数 '+(Array.isArray(v.players)?v.players.join(' / '):v.players):'',v.streets?Array.isArray(v.streets)?v.streets.join(' / '):v.streets:''].filter(Boolean).join(' · '))}</td><td>${esc((Array.isArray(v.limits)?v.limits.join('；'):v.limits)||v.status||v.note||'详见结果中的计算记录')}</td></tr>`).join('')}</tbody></table></div>`:''}<div class="evidence-list" style="margin-top:16px"><div class="evidence-card"><h4>权益证据</h4><p>精确枚举或采样的摊牌结果。采样区间衡量随机误差，不衡量行动策略是否最优。</p></div><div class="evidence-card"><h4>策略证据</h4><p>只适用于所选牌面、范围、尺寸、规则和行动树。多人自博弈没有一般性的纳什收敛保证；查看实际报告的各玩家偏离增益。</p></div><div class="evidence-card"><h4>教学证据</h4><p>条件 EV 练习会公开对手响应假设；独立作答、解释、迁移和延迟复测各有记录。训练表现不直接换算成实战盈利承诺。</p></div></div>`);}
function editWeight(token,weight){const w=Number(weight);if(!Number.isFinite(w)||w<0||w>100)throw Error('频率应在 0–100% 之间。');const p=state.scenario.players[state.selectedPlayer];p.range=(p.range||'').replace(/[,;\s]+$/,'')+(p.range?.trim()?',':'')+token+':'+Number((w/100).toFixed(6));touch();render();}
