function solveSettings(){if(state.settings.engine==='gpu-river'&&(parseCards(state.scenario.board).length!==5||state.scenario.players.length>3))throw Error('GPU策略实验引擎当前仅支持河牌2–3人；请切回自动选择或调整局面。');const parse=s=>String(s).split(/[,，\s]+/).filter(Boolean).map(Number),huFlop=parseCards(state.scenario.board).length===3&&state.scenario.players.length===2;const settings={...state.settings,iterations:Number(state.settings.iterations),sizes:parse(state.settings.sizes),raiseSizes:parse(state.settings.raiseSizes),maxRaises:Number(state.settings.maxRaises),samples:Number(state.settings.samples),riverSizes:parse(state.settings.riverSizes??(huFlop?state.settings.sizes:'50')),riverRaiseSizes:parse(state.settings.riverRaiseSizes??(huFlop?state.settings.raiseSizes:'50')),riverMaxRaises:Number(state.settings.riverMaxRaises??0)};settings.algorithm=huFlop?'dcfr':state.settings.algorithm||'alternating-cfr-plus';if(!settings.engine||settings.engine==='auto'){delete settings.engine;delete settings.gpuMemoryBytes;delete settings.adaptivePrecision;delete settings.adaptiveCheckEvery;}else settings.gpuMemoryBytes=Number(settings.gpuMemoryBytes||4e9);if(huFlop){settings.turnSizes=parse(state.settings.turnSizes??state.settings.sizes);settings.turnRaiseSizes=parse(state.settings.turnRaiseSizes??state.settings.raiseSizes);settings.turnMaxRaises=settings.maxRaises;settings.riverMaxRaises=settings.maxRaises;settings.outputScope=state.settings.outputScope||'auto';}return settings;}
