function importJSON(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const f=input.files[0];if(!f)return;if(f.size>4000000)throw Error('案例文件超过 4 MB。');const raw=JSON.parse(await f.text()),s=raw.scenario||raw.state;if(!s?.players?.length)throw Error('请选择新版 PokerLab 导出的多人 Scenario 案例。');await api('/api/pro/cases',{title:raw.title||s.title,scenario:s,notes:raw.notes||s.notes||'',inputContext:raw.inputContext||s.inputContext||null,settings:raw.settings||null});await loadCases();toast('案例已导入，计算结果需要重新验证。');}catch(e){toast(e.message,true);}};input.click();}
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();showCommands();}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'&&state.route==='study'&&!$('#modal').open){e.preventDefault();analyze();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'&&state.route==='study'&&!$('#modal').open){e.preventDefault();saveCase().catch(e=>toast(e.message,true));}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal();});
window.addEventListener('hashchange',()=>{const r=location.hash.slice(1);if(['today','study','train','library','progress'].includes(r)&&state.route!==r){state.route=r;render();}});

// Personal exercises preserve the exact solved node and hide their reference values before submission.
Object.assign(state,{privateCards:[],freeReason:'',strategyBaseline:null,compareMode:'equity',jobScenario:null,jobKey:null,lockDraft:null,lockSignature:null,afterSolvePath:null});
state.settings.locks=Array.isArray(draftSettings?.settings?.locks)?draftSettings.settings.locks:[];state.lockSignature=draftSettings?.lockSignature||null;
async function loadPrivateCards(){try{const r=await api('/api/pro/training/study-cards');state.privateCards=Array.isArray(r)?r:r.cards||[];if(state.route==='train'&&!state.lesson)render();}catch{}}
async function createStudyCard(combo){checkStrategyCapability('studyCards');if(!state.job?.id||!state.node)throw Error('请先完成策略求解。');if(state.jobKey&&state.jobKey!==key())throw Error('当前输入已改变，请从对应求解记录恢复局面后生成练习。');await api('/api/pro/training/from-solve',{jobId:state.job.id,nodePath:state.nodePath,combo});await loadPrivateCards();toast('已加入“我的求解练习”。训练时将隐藏策略与 EV，先由你独立判断。');}
async function startPrivateLesson(id){state.savedAttempt=null;state.lastAttempt=null;const c=state.privateCards.find(c=>c.id===id);if(!c?.publicQuestion)throw Error('找不到该个人题卡，请刷新后重试。');const q=clone(c.publicQuestion);state.lessonReview=privateReview(c);state.lesson={...q,id:c.id,private:true,theme:'我的真实求解',difficulty:'个人研究',minutes:3,scenario:clone(q.scenario),displayScenario:{...q.scenario,players:(q.scenario.players||[]).filter((_,i)=>!privateFolded(q,i)),hero:q.combo,board:q.nodeContext?.board||q.scenario?.board,pot:q.nodeContext?.pot??q.scenario?.pot,notes:[q.scenario?.notes,q.nodeContext?.history?.map(h=>h.actorName+' '+h.label).join(' → ')].filter(Boolean).join('\n')}};state.lesson.assessment=!!state.pendingAssessment;state.pendingAssessment=false;state.lessonStarted=Date.now();state.answer=null;state.reasons=[];state.freeReason='';state.confidence=60;state.feedback=null;state.grading=false;state.freeReason='';nav('train');}
const originalSubmitAnswer=submitAnswer;
submitAnswer=async function(){if(!state.lesson?.private)return originalSubmitAnswer();if(!state.answer||state.grading||state.feedback)return;state.grading=true;render();try{const r=await api('/api/pro/training/study-attempt',{cardId:state.lesson.id,answer:state.answer,confidence:state.confidence,reason:state.freeReason,elapsedMs:Date.now()-state.lessonStarted});state.lastAttempt=r.attempt||null;state.feedback=r.feedback||r;state.lessonReview=r.review||null;if(r.reviewSummary)state.studySummary={...(state.studySummary||{}),summary:r.reviewSummary};state.grading=false;render();$('.feedback-card')?.scrollIntoView({behavior:'smooth',block:'start'});loadPrivateCards();loadSummary();}catch(e){state.grading=false;toast(e.message,true);render();}};
const originalRenderTraining=renderTraining;
renderTraining=function(){let html=originalRenderTraining();if(state.lesson?.private){html=html.replace('<div class="confidence-row">',`<label class="label" style="margin-top:16px">你的判断依据 · 保留原文，不自动给语言表达打分</label><textarea id="training-reason" ${state.feedback?'disabled':''} placeholder="哪类组合在支撑这个动作？对手的什么响应会改变你的结论？">${esc(state.freeReason)}</textarea><div class="confidence-row">`);if(state.lesson.nodeContext){const n=state.lesson.nodeContext;html=html.replace('<h3>题目条件</h3>',`<h3>当前决策节点</h3><p class="help">${esc(n.actorName||n.actorId)} 行动 · 需跟 ${fmt(n.toCall)} BB</p>`);}return html;}if(state.lesson||!state.privateCards.length)return html;const cards=`<section class="section-gap" style="margin:0 0 27px"><div class="section-title"><h2>我的求解练习</h2><small>由你研究过的真实节点生成，答案在作答后揭示</small></div><div class="lesson-grid">${state.privateCards.map(c=>`<button class="panel lesson-card" data-action="private-lesson" data-id="${esc(c.id)}" style="min-height:175px"><span class="badge ${privateReview(c)?.due?'amber':'green'}">${esc(privateReviewLabel(privateReview(c)))} · ${Array.isArray(c.attempts)?c.attempts.length:Number(c.attempts)||0} 次练习</span><h3>${esc(c.publicQuestion?.title||'我的策略练习')}</h3><p>${inlineHand(c.publicQuestion?.combo)} · ${esc(c.publicQuestion?.nodeContext?.actorName||'')} · ${esc(c.publicQuestion?.nodeContext?.board||c.publicQuestion?.scenario?.board||'')}</p><p class="help">${privateReview(c)?.nextDueAt?'下一次复核 '+time(privateReview(c).nextDueAt):'先独立作答，再依据实际表现安排回访。'}</p><div class="lesson-bottom"><span>指定树内行动 EV</span><span class="accent">开始 ${icon('arrow')}</span></div></button>`).join('')}</div></section>`;return html.replace('<div class="callout"',cards+'<div class="callout"');};
const originalRenderFeedback=renderFeedback;
renderFeedback=function(f,l){let html=originalRenderFeedback(f,l);const extra=`${f.nextExperiment?`<div class="evidence-card" style="margin-top:16px"><h4>下一次对照实验</h4><p>${esc(f.nextExperiment)}</p></div>`:''}${f.fieldTask?`<div class="evidence-card" style="margin-top:12px"><h4>带到实战的观察任务</h4><p>${esc(f.fieldTask)}</p></div>`:''}${f.actionEV?`<div class="table-scroll" style="margin-top:15px"><table class="data-table"><thead><tr><th>动作</th><th>参考 EV</th><th>参考频率</th></tr></thead><tbody>${Object.entries(f.actionEV).map(([k,v],i)=>`<tr><td>${esc(l.choices?.find(c=>c.id===k)?.label||actionLabel(k))}</td><td>${signed(v)} BB</td><td>${pct(Array.isArray(f.frequencies)?f.frequencies[i]:f.frequencies?.[k])}</td></tr>`).join('')}</tbody></table></div>`:''}${f.reasonNote?`<p class="help">${esc(f.reasonNote)}</p>`:''}${f.review?.dueAt?`<p class="help">下次复习：${time(f.review.dueAt)} · ${'根据本次判断与信心安排复测'}</p>`:''}`;html=html.replace('<div class="row wrap" style="justify-content:flex-end;margin-top:22px">',extra+'<div class="row wrap" style="justify-content:flex-end;margin-top:22px">');return html;};

// Node locking is explicit: retain a baseline, edit an information-set policy, then re-solve.
function treeSignature(){return JSON.stringify({pot:state.scenario.pot,board:state.scenario.board,players:state.scenario.players.map(p=>({id:p.id,stack:p.stack})),toAct:state.scenario.toAct,sizes:state.settings.sizes,raiseSizes:state.settings.raiseSizes,maxRaises:state.settings.maxRaises,allIn:state.settings.allIn,riverSizes:state.settings.riverSizes,riverRaiseSizes:state.settings.riverRaiseSizes,riverMaxRaises:state.settings.riverMaxRaises,riverToAct:state.settings.riverToAct});}
function lockInitial(combo=''){const n=state.node;if(combo){const c=n.combos?.find(c=>c.combo===combo);if(c?.probabilities)return [...c.probabilities];}return n.actions.map(a=>Number(a.frequency)||0);}
function showLockModal(){checkStrategyCapability('nodeLock');if(pendingTreeSettings())throw Error('建树尺寸或约束已改变，请先恢复原设置或重新求解。');if(!state.node||state.node.terminal)throw Error('请先打开一个有决策动作的求解节点。');if(state.jobKey&&state.jobKey!==key())throw Error('输入已变动，不能将旧节点锁定直接用于新局面。');state.lockDraft={nodeId:state.node.id,path:[...state.nodePath],combo:'',probabilities:lockInitial()};renderLockModal();}
function renderLockModal(){const n=state.node,d=state.lockDraft;openModal('锁定一段响应，再让其他策略调整','这是一项条件实验：你指定部分策略，其余决策继续求解。锁定不是对真实对手行为的断言。',`<div class="callout">当前节点 ${esc(n.id)} · ${esc(state.scenario.players[n.actor]?.position||n.actorId)} 行动。实验会先保存当前节点为策略 A，再以相同树求解锁定后的策略 B。</div><label class="label" style="margin-top:17px">锁定范围</label><select id="lock-combo"><option value="">整个节点 · 对每个组合使用同一策略</option>${(n.combos||[]).map(c=>`<option value="${esc(c.combo)}" ${d.combo===c.combo?'selected':''}>${esc(c.combo)}</option>`).join('')}</select><div class="table-scroll" style="margin-top:15px"><table class="data-table"><thead><tr><th>动作</th><th>指定频率 · %</th></tr></thead><tbody>${n.actions.map((a,i)=>`<tr><td>${esc(a.label||actionLabel(a.id))}</td><td><input type="number" min="0" max="100" step="0.1" data-lock-index="${i}" value="${Number((d.probabilities[i]*100).toFixed(3))}" style="max-width:140px"></td></tr>`).join('')}</tbody></table></div><div class="row spread" style="margin-top:12px"><p class="help">频率总和必须为 100%。整节点锁定会逐组合应用；只改变聚合频率需要对组合构成另作假设。</p>${btn('按比例归一化','normalize-lock','small')}</div>`,btn('仅保存约束','apply-lock','small')+btn('锁定并重新求解 '+icon('arrow'),'apply-lock-solve','primary'));}
function pinStrategy(){if(pendingTreeSettings())throw Error('建树设置已改变，请恢复本次求解设置或重新求解后固定基线。');if(!state.node||!state.job)throw Error('请先完成一次求解。');state.strategyBaseline={jobId:state.job.id,scenario:clone(state.jobScenario||state.scenario),key:state.jobKey||key(),signature:treeSignature(),node:clone(state.node),path:[...state.nodePath],diagnostics:clone(state.job.diagnostics||state.job.result?.diagnostics||{}),settings:clone(state.settings)};state.compareMode='strategy';toast('已保存当前策略为 A。可以锁定响应后，比较相同节点的变化。');}
async function applyLock(run){const d=state.lockDraft,ps=d.probabilities,total=ps.reduce((a,b)=>a+b,0);if(ps.some(p=>!Number.isFinite(p)||p<0||p>1)||Math.abs(total-1)>.0001)throw Error('频率必须为 0–100%，总和应为 100%；可点击“按比例归一化”。');pinStrategy();const lock={nodeId:d.nodeId,probabilities:ps,...(d.combo?{combo:d.combo}:{})};state.settings.locks=state.settings.locks.filter(l=>!(l.nodeId===lock.nodeId&&(l.combo||'')===(lock.combo||'')));state.settings.locks.push(lock);state.lockSignature=treeSignature();state.afterSolvePath=[...d.path];closeModal();state.solveConfig=true;if(run)await solve();else render();}
const originalSolve=solve;
solve=async function(){if(state.settings.locks.length&&state.lockSignature!==treeSignature())throw Error('牌面、筹码或行动尺寸已改变，请清除旧节点约束后重新建树。');state.jobScenario=clone(state.scenario);state.jobKey=key();return originalSolve();};
const originalLoadNode=loadNode;
loadNode=async function(){if(state.afterSolvePath){state.nodePath=[...state.afterSolvePath];state.afterSolvePath=null;}return originalLoadNode();};
const originalRenderSettings=renderSettings;
renderSettings=function(){const html=originalRenderSettings();if(!state.settings.locks.length)return html;return html.replace('<p class="help">更多尺寸',`<div class="divider"></div><div class="row spread"><h4>已指定的响应约束 · ${state.settings.locks.length} 项</h4>${btn('清除全部','clear-locks','ghost small')}</div>${state.settings.locks.map((l,i)=>`<div class="row spread" style="margin-top:9px"><span class="help" style="margin:0">节点 ${esc(l.nodeId)} · ${l.combo?inlineHand(l.combo):'全部组合'} · ${l.probabilities.map(p=>pct(p,1)).join(' / ')}</span>${btn(icon('close'),'remove-lock','ghost small',`data-index="${i}" title="移除此约束"`)}</div>`).join('')}<p class="help">更多尺寸`);};
const originalRenderTree=renderTree;
renderTree=function(){const s=state.scenario;if(state.jobScenario)state.scenario=state.jobScenario;let html;try{html=originalRenderTree();}finally{state.scenario=s;}if(!state.node||state.node.terminal)return html;html=html.replace('<div class="tree-breadcrumb">',`<div class="row wrap" style="justify-content:flex-end;margin-bottom:16px">${btn(icon('copy')+'固定策略 A','pin-strategy','small')}${btn(icon('sliders')+'锁定响应并重算','lock-node','small')}${state.node.combos?.some(c=>sameHand(c.combo,state.strategyCombo||state.jobScenario?.hero||state.scenario.hero))?btn(icon('train')+'训练聚焦手牌','create-study-card','small',`data-combo="${esc(state.strategyCombo||state.jobScenario?.hero||state.scenario.hero)}"`):''}</div><div class="tree-breadcrumb">`);html=html.replace('<th>具体组合</th>','<th>具体组合 / 训练</th>');for(const c of(state.node.combos||[])){const hand=c.combo||c.hand;html=html.replace(`<td>${inlineHand(hand)}</td>`,`<td>${inlineHand(hand)} <button class="button ghost small" style="padding:1px 4px;font-size:9px" data-action="create-study-card" data-combo="${esc(hand)}" title="将此组合加入个人训练">练这手</button></td>`);}if(state.jobKey&&state.jobKey!==key())html=`<div class="callout warn" style="margin-bottom:16px">当前输入已经改变。下方是先前求解局面的策略，请重新求解后用于当前判断。</div>`+html;return html;};
const originalRenderComparison=renderComparison;
renderComparison=function(){const bar=`<div class="row" style="margin-bottom:17px"><button class="pill ${state.compareMode==='equity'?'active':''}" data-action="compare-mode" data-value="equity">范围权益对照</button><button class="pill ${state.compareMode==='strategy'?'active':''}" data-action="compare-mode" data-value="strategy">策略响应对照</button></div>`;if(state.compareMode!=='strategy')return bar+originalRenderComparison();const a=state.strategyBaseline,n=state.node;if(!a)return bar+`<div class="empty"><h3>观察调整之后，整段策略怎样变化</h3><p>在行动树中固定一个节点为策略 A，锁定某个响应并重新求解，然后比较相同节点的策略与 EV。</p>${btn('查看行动树','result-tab','primary','data-value="tree"')}</div>`;const same=n&&JSON.stringify(a.path)===JSON.stringify(state.nodePath)&&a.signature===treeSignature()&&a.key===state.jobKey,newJob=state.job?.id!==a.jobId;return bar+`<div class="row spread wrap"><div><h3>相同节点 · 策略 A / B</h3><p class="help">A：${esc(a.node.id)} · ${a.path.map(actionLabel).map(esc).join(' → ')||'本街起点'}；B：当前求解节点。</p></div>${btn('打开响应锁定','lock-node','small',!n||n.terminal?'disabled':'')}</div>${!same?'<div class="callout warn" style="margin-top:15px">请在相同牌面、范围、树尺寸及行动路径下比较。当前节点或输入不一致，暂不计算差值。</div>':!newJob?'<div class="callout" style="margin-top:15px">A 已保存。现在锁定部分响应并重新求解，才会产生独立的策略 B。</div>':`<div class="table-scroll" style="margin-top:17px"><table class="data-table"><thead><tr><th>动作</th><th>A 频率</th><th>B 频率</th><th>频率变化</th><th>A EV</th><th>B EV</th></tr></thead><tbody>${n.actions.map(b=>{const v=a.node.actions.find(v=>v.id===b.id);return `<tr><td>${esc(b.label)}</td><td>${pct(v?.frequency)}</td><td>${pct(b.frequency)}</td><td>${v?signed((b.frequency-v.frequency)*100)+' pp':'—'}</td><td>${signed(v?.ev)} BB</td><td>${signed(b.ev)} BB</td></tr>`;}).join('')}</tbody></table></div><p class="help">节点聚合值会随各条上游路径到达分布变化。组合级差异请回到行动树查看；锁定后的解只回答指定对手模型下的条件策略。</p>`}<div class="coach-principle" style="margin-top:18px"><span class="eyebrow">REBUILD THE REASON</span><p>解释变化时，追到具体组合：哪些强牌从 call 移到了 raise？哪些边缘牌因为对手响应改变获得了收益？然后检查剩余分支是否仍能合理应对。</p></div>`;};

const engineChinese={
 'information-set-consistent exact best response':'遵守信息集的精确最佳应对检验',
 'Multiplayer CFR has no general Nash-equilibrium convergence guarantee.':'多人 CFR 不具备一般性的纳什均衡收敛保证。',
 'NashConv is measured only within the chosen action tree; omitted sizes can create additional real-game exploits.':'NashConv 只衡量已建立的有限行动树；遗漏尺寸可能产生额外的可利用空间。',
 'Locked strategies can make the unrestricted best-response residual irreducible. BR metrics deliberately allow deviations from locks.':'锁定策略后，不受约束的最佳应对增益可能无法降至零；该指标允许玩家解除锁定后偏离。',
 'A small residual certifies a strategy profile for this stated model, not the correctness of the input ranges or real-world profitability.':'低残差仅是指定模型中策略的证据，不证明输入范围正确，也不保证实战盈利。',
 'River only, five public cards fixed. Independent input ranges conditioned jointly on legal card combinations.':'只计算河牌，五张公共牌固定。独立输入范围经联合牌张互斥处理。',
 'Dead starting pot is eligible to every entered player; no carried-over side pots. Current-street side pots and uncalled-bet refunds are exact.':'所有入池玩家均有起始底池资格；不包含之前街遗留边池。本街新产生的边池与未跟注返还计入计算。',
 'Continuous chips: tied pots split fractionally; no casino odd-chip allocation. See rakeModel for the explicitly modeled fixed fee.':'使用连续金额平分底池，不包含赌场零碎筹码分配；抽水以本题明确输入的固定规则为准。',
 'No rake. Continuous chips: tied pots split fractionally; no casino odd-chip allocation.':'无抽水；使用连续金额平分底池，不包含赌场零碎筹码分配规则。',
 'Action sizes and raise cap are a finite abstraction, not all legal no-limit actions. EVs are relative to the current node, excluding sunk contributions.':'下注尺寸与加注上限属于有限抽象，没有包含全部无限注动作。EV 从当前节点向后计算，不含已投入筹码。',
 'Ranges describe all players still in the pot. Folded-card bunching is not modeled.':'范围描述仍在底池的玩家，没有建模已弃牌者的牌张移除效应。'
};
const translateEngine=s=>Object.entries(engineChinese).reduce((t,[a,b])=>t.split(a).join(b),s);
const completeTreeRenderer=renderTree;
renderTree=function(){const n=state.node;if(!n)return completeTreeRenderer();const selected=n.combos?.some(c=>sameHand(c.combo,state.strategyCombo))?state.strategyCombo:null;const hero=selected||state.jobScenario?.hero||state.scenario.hero,focus=n.combos?.find(c=>sameHand(c.combo,hero)),useFocus=focus&&state.strategyScope!=='range';if(useFocus)state.node={...n,actions:n.actions.map((a,i)=>({...a,frequency:focus.probabilities[i],ev:focus.actionEV?.[i]??null}))};let html;try{html=completeTreeRenderer();}finally{state.node=n;}if(!n.terminal){const scope=`<div class="row wrap" style="margin:14px 0 8px"><span class="muted" style="font-size:10px">行动卡视角</span><button class="pill ${!useFocus?'active':''}" data-action="strategy-scope" data-value="range">整段范围</button>${focus?`<button class="pill ${useFocus?'active':''}" data-action="strategy-scope" data-value="hero">${inlineHand(hero)} · 聚焦组合</button>`:''}</div>`;html=html.replace('<div class="action-grid">',scope+'<div class="action-grid">');html=html.replace('聚合频率按到达此节点的合法联合分布加权。',useFocus?'上方频率和 EV 均属于这一个具体组合。':'上方 EV 表示整段到达范围强制采取该动作的均值，不能直接视为实际选择该动作子范围的 EV。频率按合法到达分布加权。');const e=state.nodeExplanation;if(e?.sections?.length){const explanation=`<details style="margin-top:22px" open><summary style="font-size:13px;cursor:pointer;color:var(--accent)">读懂当前节点 · 证据解释</summary><div class="evidence-list" style="margin-top:12px">${e.sections.slice(0,3).map((v,i)=>`<div class="evidence-card"><h4><span class="evidence-number">${String(i+1).padStart(2,'0')}</span>${esc(v.title)}</h4><p>${esc(v.body)}</p></div>`).join('')}</div>${e.sections.length>3?`<details style="margin-top:11px"><summary class="muted" style="font-size:11px;cursor:pointer">展开全部 ${e.sections.length} 条证据</summary>${e.sections.slice(3).map(v=>`<div class="evidence-card" style="margin-top:9px"><h4>${esc(v.title)}</h4><p>${esc(v.body)}</p></div>`).join('')}</details>`:''}</details><div class="evidence-card" style="margin-top:16px"><div class="row spread"><h4>深入拆解这个节点</h4><span class="badge">本地中文教练</span></div><textarea id="node-coach-question" style="margin-top:10px;min-height:65px;font-size:11px" placeholder="例如：哪些具体组合支撑这个加注范围？怎样验证阻断效应？">${esc(state.nodeCoachQuestion||'')}</textarea>${btn(state.nodeCoachBusy?(state.nodeCoachStage==='language'?'<span class="spinner"></span>证据已就绪，正在根据问题选择教学重点…':'<span class="spinner"></span>正在读取完整计算证据…'):icon('spark')+'解释机制与后续实验','node-coach','small',state.nodeCoachBusy?'disabled':'')}${state.nodeCoachError&&nodeCoachMatches()?`<div class="issue error">${esc(state.nodeCoachError)}</div>`:''}${state.nodeCoach&&nodeCoachMatches()?`<div class="divider"></div><div class="node-coach-response">${coachResponseHTML(state.nodeCoach)}</div>${state.nodeCoachEvidence&&state.nodeCoach.grounding!=='deterministic'?`<details class="node-coach-evidence"><summary>查看逐项计算证据</summary>${coachResponseHTML(state.nodeCoachEvidence)}</details>`:''}<div class="result-meta"><span class="badge">${esc(state.nodeCoach.model||'证据解释')}</span><span>${state.nodeCoach.grounding==='deterministic'?'当前使用可核验的证据模板':'核心教案由计算生成；本地模型选择重点'}</span></div>${state.nodeCoach.warning?`<p class="help gold">${esc(state.nodeCoach.warning)}</p>`:''}${state.nodeCoach.limitations?.length?`<details style="margin-top:10px"><summary class="muted" style="font-size:11px;cursor:pointer">本次解释的条件与边界</summary><ul class="assumption-list">${state.nodeCoach.limitations.map(v=>`<li>${esc(v)}</li>`).join('')}</ul></details>`:''}`:''}</div>`;html+=explanation;}}return translateEngine(html);};
async function explainEquity(){if(state.coachBusy)return;if(stale()||!state.analysis?.id)throw Error('请先计算当前局面的范围证据。');const context={key:key(),analysisId:state.analysis.id},request=Symbol('equity-coach'),payload={scenario:clone(state.scenario),analysisId:context.analysisId,question:state.coachQuestion||'请解释当前范围证据中最重要的机制，以及如何通过独立计算验证假设。只依据已有计算，不编造动作EV。'};state.coachRequest=request;state.coachBusy=true;state.coachStage='evidence';state.coachError=null;state.coach=null;render();const relevant=()=>state.coachRequest===request&&key()===context.key&&state.analysis?.id===context.analysisId;try{const evidence=await api('/api/pro/coach',{...payload,localModel:false});if(!relevant())return;state.coach=evidence;state.coachStage='language';render();const report=await api('/api/pro/coach',{...payload,localModel:true});if(relevant())state.coach=report;}catch(e){if(relevant()){state.coachError=(state.coach?'中文整理暂未完成；已计算的证据报告仍可阅读。':'')+e.message;toast(state.coachError,true);}}finally{if(state.coachRequest===request){state.coachBusy=false;state.coachStage=null;render();}}}
function nodeCoachFocus(){if(state.strategyScope==='range')return '';const wanted=state.strategyCombo||state.jobScenario?.hero||state.scenario.hero;return state.node?.combos?.find(c=>sameHand(c.combo,wanted))?.combo||'';}
function nodeCoachMatches(context=state.nodeCoachContext){return !!context&&state.job?.id===context.jobId&&state.node?.id===context.nodeId&&key()===context.key&&nodeCoachFocus()===context.combo&&JSON.stringify(state.nodePath)===context.path;}
async function explainNode(){if(state.nodeCoachBusy||!state.job?.id)return;if(state.jobKey&&state.jobKey!==key())throw Error('请恢复求解时的局面或重新求解后再解读。');state.nodeCoachQuestion=$('#node-coach-question')?.value||state.nodeCoachQuestion||'';const context={jobId:state.job.id,nodeId:state.node?.id,key:key(),combo:nodeCoachFocus(),path:JSON.stringify(state.nodePath)},request=Symbol('coach'),payload={scenario:clone(state.scenario),jobId:context.jobId,nodePath:[...state.nodePath],...(context.combo?{combo:context.combo}:{}),question:state.nodeCoachQuestion||'围绕当前节点解释：哪些具体组合支撑价值与诈唬分工，各响应分支怎样影响判断。只解释已提供的计算证据。'};state.nodeCoachRequest=request;state.nodeCoachContext=context;state.nodeCoachBusy=true;state.nodeCoachStage='evidence';state.nodeCoachError=null;state.nodeCoach=null;state.nodeCoachEvidence=null;render();const relevant=()=>state.nodeCoachRequest===request&&nodeCoachMatches(context);try{const evidence=await api('/api/pro/coach',{...payload,localModel:false});if(!relevant())return;state.nodeCoach=evidence;state.nodeCoachEvidence=evidence;state.nodeCoachStage='language';render();const report=await api('/api/pro/coach',{...payload,localModel:true});if(relevant())state.nodeCoach=report;}catch(e){if(relevant()){state.nodeCoachError=state.nodeCoachEvidence?'中文整理暂未完成，已计算的证据报告保留在下方。'+e.message:e.message;toast(state.nodeCoachError,true);}}finally{if(state.nodeCoachRequest===request){state.nodeCoachBusy=false;state.nodeCoachStage=null;render();}}}

const completeJobStatus=renderJobStatus;
renderJobStatus=function(){let html=translateEngine(completeJobStatus());const d=state.job?.diagnostics||state.job?.result?.diagnostics;if(d&&['complete','completed'].includes(state.job?.status)){const residual=d.optimizationResidualPctPot??d.nashConvPctPot,target=Number(state.job?.settings?.accuracy??state.settings.accuracy??.25);if(numeric(residual)&&residual>target)html=html.replace('策略求解完成','计算结束 · 尚未达到目标残差');if(d.locksPresent&&numeric(d.constrainedNashConvPctPot))html=html.replace('</div>',`</div><p class="help">遵守锁定约束的优化残差：${fmt(d.constrainedNashConvPctPot,4)}% 底池。下方不受约束的 NashConv 允许解除锁定，两者用途不同。</p>`);}return html;};
const completeSettingsRenderer=renderSettings;
renderSettings=function(){return completeSettingsRenderer().replace('<label><span class="label">迭代次数</span>',`<label><span class="label">目标残差 · % 底池</span><input type="number" min="0.01" max="20" step="0.05" data-setting="accuracy" value="${state.settings.accuracy??.25}"></label><label><span class="label">迭代上限</span>`);};
function refreshJobPanel(){const el=$('.job-status');if(el)el.outerHTML=renderJobStatus();else $('.result-tabs')?.insertAdjacentHTML('beforebegin',renderJobStatus());}
const personalCardCreation=createStudyCard;
createStudyCard=async function(combo){const lock=state.job?.settings?.locks?.find(l=>l.nodeId===state.node?.id&&(!l.combo||sameHand(l.combo,combo)));if(lock)throw Error('此组合的动作已被人为锁定。请选择未锁定的响应节点生成决策练习，避免将指定行为当作最优行动。');return personalCardCreation(combo);};
const trainingPageRenderer=renderTraining;
renderTraining=function(){let html=translateEngine(trainingPageRenderer());const q=state.lesson?.quality;if(q){const note=`<div class="callout ${q.provisional?'warn':''}" style="margin:0 0 17px"><div class="row wrap"><span class="badge ${q.provisional?'amber':'green'}">${q.provisional?'暂定参考 · 不计入技能掌握':'指定模型内参考'}</span>${numeric(q.residual)?`<span class="muted" style="font-size:10px">参考残差 ${fmt(q.residual,3)}% 底池</span>`:''}</div><details ${q.provisional?'open':''} style="margin-top:8px"><summary class="muted" style="font-size:11px;cursor:pointer">参考质量与评分边界</summary><p class="help">${esc(q.note||'此题仅检验当前输入与参考后续策略下的判断。')}</p></details></div>`;html=html.replace('<div class="training-grid">',note+'<div class="training-grid">');}return html;};

Object.assign(state,{catalog:[],guides:[],catalogFormat:'all',catalogCount:'all',catalogStreet:'all',catalogSearch:'',libraryMode:'catalog',activeGuide:null,guideIndex:0,guideComplete:false});
function catalogList(){return state.catalog.filter(p=>(state.catalogFormat==='all'||p.format===state.catalogFormat)&&(state.catalogCount==='all'||p.scenario?.players?.length===Number(state.catalogCount))&&(state.catalogStreet==='all'||parseCards(p.scenario?.board).length===Number(state.catalogStreet))&&(!state.catalogSearch||`${p.title} ${p.intent} ${p.prediction} ${p.scenario?.board}`.toLowerCase().includes(state.catalogSearch.toLowerCase())));}
function catalogFilters(){return `<div class="library-toolbar"><div class="search-field">${icon('search')}<input id="catalog-search" value="${esc(state.catalogSearch)}" placeholder="搜索机制、牌面或研究问题"></div><div class="format-toggle">${[['all','全部'],['online','线上'],['live','现场']].map(([v,l])=>`<button class="${state.catalogFormat===v?'active':''}" data-action="catalog-format" data-value="${v}">${l}</button>`).join('')}</div><div class="row" style="gap:5px">${[['all','人数'],['2','2 人'],['3','3 人'],['4','4 人'],['5','5 人']].map(([v,l])=>`<button class="pill ${state.catalogCount===v?'active':''}" data-action="catalog-count" data-value="${v}">${l}</button>`).join('')}</div><div class="row" style="gap:5px">${[['all','街数'],['3','翻牌'],['4','转牌'],['5','河牌']].map(([v,l])=>`<button class="pill ${state.catalogStreet===v?'active':''}" data-action="catalog-street" data-value="${v}">${l}</button>`).join('')}</div></div>`;}
function renderPreset(p,compact=false){const s=p.scenario,solved=p.solved;return `<article class="panel case-card preset-card"><div class="row spread"><span class="badge ${s.players.length>=3?'green':''}">${p.format==='live'?'现场':'线上'} · ${s.players.length} 人 · ${({3:'翻牌',4:'转牌',5:'河牌'})[parseCards(s.board).length]||'局面'}</span>${solved?.jobId?'<span class="badge">已有参考解</span>':''}</div><h3>${esc(p.title)}</h3><div class="cards-row">${boardHTML(s.board,true)}</div><p>${esc(p.intent||'')}</p>${compact?'':`<div class="preset-prediction"><span class="eyebrow">先预测</span><p>${esc(p.prediction||'')}</p></div>`}<div class="case-footer wrap">${btn('编辑研究','preset-edit','small',`data-id="${esc(p.id)}"`)}${solved?.jobId?btn('打开策略树','preset-solved','primary small',`data-id="${esc(p.id)}"`):''}${solved?.cardIds?.length?btn('练习','preset-drill','ghost small',`data-id="${esc(p.id)}"`):''}</div></article>`;}
function renderCatalog(){const list=catalogList();return `<div class="page-heading"><div><div class="eyebrow">A LIBRARY OF TESTABLE IDEAS</div><h1 style="margin-top:6px">研究起点</h1><p class="subtitle">每个局面围绕一个机制。先作预测，查看参考解，再只改变一个条件。</p></div>${btn(icon('plus')+'自由研究','new-study','primary')}</div>${libraryTabs()}<div class="callout" style="margin:18px 0">范围和到达权重是明确的教学假设，不能当作赌场人群数据或通用 GTO 翻前范围。预置局面与个人训练成绩分别保存。</div>${catalogFilters()}<div class="case-grid">${list.map(p=>renderPreset(p)).join('')||'<div class="panel empty" style="grid-column:1/-1"><p>没有匹配的研究起点。尝试清除筛选条件。</p></div>'}</div>`;}
function libraryTabs(){return `<div class="row wrap"><button class="pill ${state.libraryMode==='catalog'?'active':''}" data-action="library-mode" data-value="catalog">研究起点 · ${state.catalog.length}</button><button class="pill ${state.libraryMode==='personal'?'active':''}" data-action="library-mode" data-value="personal">个人案例 · ${state.cases.length}</button><button class="pill ${state.libraryMode==='inbox'?'active':''}" data-action="library-mode" data-value="inbox">实战收件箱${handInbox.total()!==null?' · '+fmt(handInbox.total(),0):''}</button></div>`;}
const personalLibraryRenderer=renderLibrary;
renderLibrary=function(){if(state.libraryMode==='catalog'&&state.catalog.length)return renderCatalog();let html=personalLibraryRenderer();return html.replace('<div class="library-toolbar">',libraryTabs()+'<div class="library-toolbar" style="margin-top:18px">');};
const basicTemplates=showTemplates;
showTemplates=function(){if(!state.catalog.length)return basicTemplates();openModal('选择一个研究起点','每个案例都有明确问题、范围假设和单变量对照；可以直接打开已经计算的策略树。',`<div id="catalog-modal">${catalogFilters()}<div class="case-grid catalog-modal-grid">${catalogList().map(p=>renderPreset(p,true)).join('')}</div></div>`);};
function refreshCatalog(){if($('#catalog-modal'))$('#catalog-modal').innerHTML=catalogFilters()+`<div class="case-grid catalog-modal-grid">${catalogList().map(p=>renderPreset(p,true)).join('')}</div>`;else render();}
async function usePreset(id,solved=false){const p=state.catalog.find(p=>p.id===id);if(!p)throw Error('找不到这个研究起点。');if($('#modal').open)closeModal();applyScenario({...clone(p.scenario),notes:[p.intent?'研究重点：'+p.intent:'',p.prediction?'先预测：'+p.prediction:'',p.oneChange?'单变量实验：'+p.oneChange:'',p.source].filter(Boolean).join('\n')});state.settings=settingsFromSource(p.settings||{});if(solved&&p.solved?.jobId){state.job=await api('/api/pro/jobs/'+encodeURIComponent(p.solved.jobId));state.jobScenario=clone(state.scenario);state.jobKey=key();state.nodePath=[];state.tab='tree';await loadNode();$('.research-bottom')?.scrollIntoView({behavior:'smooth',block:'start'});}else render();}
async function drillPreset(id){const p=state.catalog.find(p=>p.id===id);if(!p?.solved?.cardIds?.length)throw Error('此研究起点还没有预生成练习。');if($('#modal').open)closeModal();await loadPrivateCards();state.activeGuide=null;const idToUse=p.solved.cardIds.find(id=>state.privateCards.some(c=>c.id===id));if(!idToUse)throw Error('参考题卡尚在更新，请稍后重试。');await startPrivateLesson(idToUse);}
function presetForCard(id){return state.catalog.find(p=>p.solved?.cardIds?.includes(id));}
const privateLessonStarter=startPrivateLesson;
startPrivateLesson=async function(id){state.activeGuide=null;state.guideComplete=false;await privateLessonStarter(id);if(presetForCard(id)){state.lesson.theme='研究起点 · 模型练习';render();}};
const trainingWithPrivate=renderTraining;
renderTraining=function(){if(state.guideComplete&&state.activeGuide)return renderGuideFinish();const all=state.privateCards;if(!state.lesson)state.privateCards=all.filter(c=>!presetForCard(c.id));let html;try{html=trainingWithPrivate();}finally{state.privateCards=all;}if(state.lesson&&state.activeGuide){const g=state.activeGuide;const strip=`<div class="guided-strip"><div class="row spread"><div><span class="eyebrow">${esc(g.title)}</span><p class="help">第 ${state.guideIndex+1} / ${g.steps.length} 步 · ${esc(g.steps[state.guideIndex]?.title||'')}</p></div><span class="badge">循序训练</span></div><div class="guided-steps">${g.steps.map((s,i)=>`<button class="${i===state.guideIndex?'active':i<state.guideIndex?'done':''}" data-action="guide-step" data-index="${i}"><span>${String(i+1).padStart(2,'0')}</span>${esc(s.title)}</button>`).join('')}</div></div>`;html=html.replace('<div class="training-grid">',strip+'<div class="training-grid">');}if(state.lesson)return html;const guides=state.guides.length?`<section style="margin-bottom:27px"><div class="section-title"><h2>20 分钟 · 走完一个机制</h2><small>基线判断 → 机制 → 反例 → 迁移 → 实战观察</small></div><div class="guide-grid">${state.guides.map((g,i)=>`<button class="panel guide-card" data-action="guide" data-id="${esc(g.id)}"><span class="eyebrow">${String(i+1).padStart(2,'0')} / GUIDED STUDY</span><h3>${esc(g.title)}</h3><p>${esc(g.goal)}</p><div class="row spread"><span class="muted" style="font-size:10px">${g.minutes||20} 分钟 · 完整学习路径</span>${icon('arrow')}</div></button>`).join('')}</div></section>`:'';return html.replace('<div class="callout"',guides+'<div class="callout"');};
async function showGuide(id){const g=await api('/api/pro/training/guide?id='+encodeURIComponent(id));state.guidePreview=g.guide||g;const d=state.guidePreview;openModal(d.title,d.goal,`<div class="callout">${esc(d.instruction||'每一步先独立判断，再查看证据。')}</div><div style="margin-top:15px">${d.steps.map((s,i)=>`<div class="daily-line"><span class="step-number">${i+1}</span><div><h4>${esc(s.title)}</h4><p>${esc(({pretest:'建立真实基线，不先看讲解。',mechanism:'通过可核验的数字，重建收益机制。',counterexample:'主动寻找让结论反转的条件。',transfer:'换一组条件，独立迁移刚学到的判断。',field:'形成一条可执行的实战观察任务。'}[s.type])||'')}</p></div></div>`).join('')}</div>`,btn('开始这条训练路线 '+icon('arrow'),'begin-guide','primary',`data-id="${esc(d.id)}"`));}
async function startGuide(id){const g=state.guidePreview?.id===id?state.guidePreview:await api('/api/pro/training/guide?id='+encodeURIComponent(id));state.activeGuide=g.guide||g;state.guideIndex=0;state.guideComplete=false;if($('#modal').open)closeModal();await guideStep(0);}
async function guideStep(index){const g=state.activeGuide;if(!g)return;state.guideIndex=index;state.guideComplete=false;const s=g.steps[index];if(s.type==='field'){state.lesson=null;state.guideComplete=true;nav('train');return;}await startLesson(s.lessonId);localStorage.setItem('pokerlab-guide-progress',JSON.stringify({id:g.id,index,updatedAt:new Date().toISOString()}));}
async function advanceGuide(){await guideStep(Math.min(state.guideIndex+1,state.activeGuide.steps.length-1));}
function renderGuideFinish(){const g=state.activeGuide,task=g.steps.find(s=>s.type==='field')?.task||g.fieldTask;return `<div class="training-shell"><div class="page-heading"><div><div class="eyebrow">TAKE IT TO THE TABLE</div><h1 style="margin-top:7px">把机制带回真实牌局。</h1><p class="subtitle">${esc(g.title)}</p></div></div><div class="panel focus-card" style="min-height:280px"><span class="badge green">本轮学习路径已走到实战观察</span><h2 style="font-size:23px;max-width:700px">${esc(task)}</h2><p>在下一次复盘中记录一个支持这一判断的例子，也记录一个让它失效的例子。一次课程的完成不代表已经掌握，延迟复测会继续检验独立判断。</p><div class="row">${btn('查看复习安排','nav','primary','data-route="progress"')}${btn('返回训练路线','finish-guide','small')}</div></div><div class="callout" style="margin-top:20px">训练记录已按每一道实际提交的题目保存。跳过的步骤不会计入练习次数。</div></div>`;}

const riverTreeRenderer=renderTree;
renderTree=function(){const n=state.node;if(n?.chance){return `<div class="tree-breadcrumb"><button data-action="tree-back" data-depth="0">本街起点</button>${state.nodePath.map((a,i)=>`<span class="faint">›</span><button data-action="tree-back" data-depth="${i+1}">${esc(actionLabel(a))}</button>`).join('')}</div><div class="row spread"><div><span class="eyebrow">NEXT STREET / CHANCE NODE</span><h3 style="margin-top:8px">选择下一张公共牌，继续研究。</h3><p class="help">${n.reach>0?'这不是玩家的行动。每张牌的概率已经考虑此前行动筛选与所有范围的互斥。':'当前平均策略没有正到达质量。没有定义的条件发牌概率不会补成均匀分布；这里只显示引擎提供的分支。'}</p></div>${btn(icon('back')+'上一步','tree-up','small')}</div><div class="cards-row" style="justify-content:flex-start;margin:20px 0">${boardHTML(n.board)}<span class="playing-card placeholder">?</span></div><div class="runout-grid">${(n.actions||[]).map(a=>`<button class="runout-option" data-action="tree-action" data-id="${esc(a.id)}" ${a.frequency===0?'disabled':''}><span class="runout-rank ${cardText(a.card)[1]}">${inlineHand(cardText(a.card))}</span><span class="mono">${pct(a.frequency,2)}</span></button>`).join('')}</div><div class="callout" style="margin-top:18px">点击下一张公共牌后，查看该牌面真正的后续 check / bet / call / raise 策略。发牌概率不能解释为建议行动频率。</div>`;}let html=riverTreeRenderer();if(n?.board){const current=compactBoard(n.board),root=compactBoard(state.jobScenario?.board||state.scenario.board);if(current!==root)html=`<div class="node-board-bar"><div><span class="eyebrow">当前节点 · ${n.street==='river'?'河牌':'公共牌'}</span><p class="help">上方牌桌保留建树起点，这里显示当前行动路径的牌面。</p></div><div class="cards-row">${boardHTML(n.board,true)}</div></div>`+html;}return html;};
function compactBoard(v){return parseCards(v).map(cardText).join('');}
const riverSettingsRenderer=renderSettings;
renderSettings=function(){let html=riverSettingsRenderer();if(parseCards(state.scenario.board).length===4){const extra=`<div class="divider"></div><div class="row spread"><h4>下一街 · 河牌独立尺寸</h4>${btn('使用转牌小树起点','apply-turn-settings','small')}</div><div class="field-row three" style="margin-top:12px"><label><span class="label">河牌下注 · 底池 %</span><input data-setting="riverSizes" value="${esc(state.settings.riverSizes??'50')}"></label><label><span class="label">河牌加注 · 跟注后底池 %</span><input data-setting="riverRaiseSizes" value="${esc(state.settings.riverRaiseSizes??'50')}"></label><label><span class="label">河牌最多加注层数</span><select data-setting="riverMaxRaises">${[0,1,2].map(n=>`<option ${n===Number(state.settings.riverMaxRaises??0)?'selected':''}>${n}</option>`).join('')}</select></label></div><p class="help">转牌在组合与树预算内支持2–4人，枚举下一张公共牌与两街行动。四人宽范围需要更大的计算预算，不会自动放宽限制。默认河牌最多加注 0 次属于明确的树简化；需要研究河牌加注时请提高此值。组合、尺寸、再加注同时增加会扩大计算规模。</p>`;html=html.replace('<p class="help">更多尺寸',extra+'<p class="help">更多尺寸');}return html;};
const basicCapabilities=showCapabilities;
showCapabilities=async function(){try{const status=await api('/api/pro/status');state.metadata={...state.metadata,localCoach:status.localCoach};}catch{}basicCapabilities();$('.modal-content')?.insertAdjacentHTML('afterbegin',`<div class="callout" style="margin-bottom:16px"><strong>DGX Spark · 目标适配平台</strong><p>当前运行设备：${esc(gpuDeviceLabel())}。DGX Spark 尚未完成实机部署与验证；本次性能和精度记录来自实际记录的测试设备。</p></div>`);const m=state.metadata?.localCoach;if(m){$('.modal-content')?.insertAdjacentHTML('afterbegin',`<div class="engine-status-grid"><div class="engine-status"><span class="label">策略求解</span><strong>CPU / GPU · 行动树</strong><p>河牌可选GPU实验迭代；最终精度独立核验。</p></div><div class="engine-status"><span class="label">范围权益</span><strong>${esc(gpuDeviceLabel())}</strong><p>翻牌 / 转牌采样；小型河牌可精确枚举。</p></div><div class="engine-status"><span class="label">中文教练</span><strong>${esc(m.model||'本地模型')}</strong><p>${m.loading?'正在加载模型到显存':m.running?'已加载 · 本地生成':m.installed?'已安装 · 按需加载':'安装中 · 证据模板仍可使用'}</p></div></div>${m.running?`<div class="row" style="justify-content:flex-end;margin-bottom:14px">${btn('释放中文教练显存','unload-coach','ghost small')}</div>`:''}${m.lastError?`<div class="issue">${esc(m.lastError)}</div>`:''}`);}};
const completeLibraryRenderer=renderLibrary;
renderLibrary=function(){let html=completeLibraryRenderer();if(state.libraryMode==='personal')html=html.replace('<div class="library-toolbar"',`<div class="row" style="justify-content:flex-end;margin-top:12px">${btn(icon('download')+'导出记录 JSON','export-all','ghost small')}</div><p class="help" style="text-align:right;margin-bottom:12px">记录 JSON 包含研究、训练及任务元数据，不含求解树。完整备份请用“备份资料”。</p><div class="library-toolbar"`);return html;};

async function showBackups(){openModal('备份你的研究资料','手动完整备份包含案例、训练记录、个人题卡及求解树；恢复前自动快照只保留记录。','<div class="empty"><span class="spinner"></span><p style="margin-top:12px">正在读取本机备份…</p></div>');const epoch=state.modalEpoch;const r=await api('/api/pro/backups');if(!$('#modal').open||state.modalEpoch!==epoch)return;const list=Array.isArray(r)?r:r.backups||[];openModal('备份你的研究资料','手动完整备份包含案例、训练记录、个人题卡及求解树；恢复前自动快照只保留记录。',`<div class="callout"><strong>已有资料不会被恢复操作覆盖。</strong><br>恢复时只补充缺失记录，并先自动备份当前状态。不同版本的重复记录保持原样，便于追溯。</div><div class="table-scroll" style="margin-top:17px"><table class="data-table"><thead><tr><th>本机备份</th><th>大小</th><th>操作</th></tr></thead><tbody>${list.map(v=>`<tr><td>${time(v.createdAt)}<br><small class="faint">${esc(v.name.startsWith('auto-')?'恢复前记录快照 · 不含求解树':'手动完整备份 · 含求解树')}</small></td><td class="mono">${fmt(v.bytes/1024/1024,2)} MB</td><td><div class="row"><a class="button small" href="/api/pro/backups/download?name=${encodeURIComponent(v.name)}" download>下载</a>${btn('恢复缺失资料','restore-backup','ghost small',`data-name="${esc(v.name)}"`)}</div></td></tr>`).join('')||'<tr><td colspan="3" class="muted">还没有备份。创建第一份完整备份。</td></tr>'}</tbody></table></div>`,btn('关闭','close-modal','ghost')+btn(icon('upload')+'导入备份文件','choose-backup-file')+btn(icon('save')+'创建完整备份','create-backup','primary'));}

function chooseBackupFile(){const input=document.createElement('input');input.type='file';input.accept='.json.gz,.gz,application/gzip';input.addEventListener('change',()=>{const file=input.files?.[0];if(!file)return;if(!/\.gz$/i.test(file.name)){toast('请选择 PokerLab 导出的 .json.gz 压缩备份。',true);return;}if(file.size>128*1024*1024){toast('这份备份超过单文件128 MB上传限制。',true);return;}state.backupImportFile=file;openModal('从备份文件补充资料','先校验整份备份，再自动保留本机当前状态；已有记录不会被覆盖。',`<div class="evidence-card"><span class="label">准备导入的文件</span><h3 style="margin-top:8px;overflow-wrap:anywhere">${esc(file.name)}</h3><p class="help">${fmt(file.size/1024/1024,2)} MB · ${time(file.lastModified)}</p></div><div class="callout" style="margin-top:16px">合并备份中本机尚不存在的案例、训练记录、题卡、实验和求解树。请等待当前计算结束后再导入。上传上限128 MB，解压后上限512 MB。</div><div id="backup-import-status" style="margin-top:12px"></div>`,btn('返回备份列表','backups','ghost')+btn('确认导入这份文件','confirm-import-backup','primary'));});input.click();}
async function importBackupFile(){const file=state.backupImportFile;if(!file)throw Error('请重新选择备份文件。');const epoch=state.modalEpoch,b=$('[data-action="confirm-import-backup"]');if(b){b.disabled=true;b.innerHTML='<span class="spinner"></span>正在校验与合并…';}const status=$('#backup-import-status');if(status)status.innerHTML='<p class="help">正在上传到本机服务。完整校验与写入完成后才会显示结果，请保持服务运行。</p>';try{const response=await fetch('/api/pro/backups/import',{method:'POST',headers:{'Content-Type':'application/gzip'},body:file});const result=await response.json();if(!response.ok)throw Error(result.error||'备份导入失败，请检查文件是否完整。');state.backupImportFile=null;await Promise.allSettled([loadCases(),loadJobs(),loadSummary(),loadPrivateCards(),loadExperiments()]);if($('#modal').open&&state.modalEpoch===epoch)await showBackups();toast(`备份文件导入完成：补充 ${result.imported||0} 条记录，保留 ${result.skipped||0} 条已有记录。`);}catch(error){if($('#modal').open&&state.modalEpoch===epoch){const message=$('#backup-import-status');if(message)message.innerHTML=`<div class="callout warn">${esc(error.message)}</div>`;if(b){b.disabled=false;b.textContent='重新导入这份文件';}}toast(error.message,true);}}

async function createBackup(){const epoch=state.modalEpoch;const b=$('[data-action="create-backup"]');if(b){b.disabled=true;b.innerHTML='<span class="spinner"></span>正在备份…';}try{const r=await api('/api/pro/backups',{});if($('#modal').open&&state.modalEpoch===epoch)await showBackups();toast(`完整备份已保存：${fmt(r.bytes/1024/1024,2)} MB。`);}catch(e){toast(e.message,true);if(b){b.disabled=false;b.textContent='创建完整备份';}}}
function showRestoreBackup(name){openModal('恢复这份备份中的缺失资料','恢复会自动创建当前状态的备份，并仅补充本机尚不存在的记录。',`<div class="callout"><strong>${esc(name)}</strong>${name.startsWith('auto-')?'<br>这是一份记录快照，不包含完整求解树；树仍在本机时可继续使用，否则需要重新计算。':''}<br>已有案例、训练记录与求解结果不会被覆盖。当前有计算任务时，需要先等待任务结束。</div>`,btn('返回备份列表','backups','ghost')+btn('恢复缺失资料','confirm-restore-backup','primary',`data-name="${esc(name)}"`));}
async function restoreBackup(name){const epoch=state.modalEpoch;const b=$('[data-action="confirm-restore-backup"]');if(b){b.disabled=true;b.textContent='正在恢复…';}try{const r=await api('/api/pro/backups/restore',{name});await Promise.allSettled([loadCases(),loadJobs(),loadSummary(),loadPrivateCards()]);if($('#modal').open&&state.modalEpoch===epoch)await showBackups();toast(`恢复完成：补充 ${r.imported||0} 条记录，跳过 ${r.skipped||0} 条已有记录。`);}catch(e){toast(e.message,true);if(b){b.disabled=false;b.textContent='恢复缺失资料';}}}
const libraryWithExport=renderLibrary;
renderLibrary=function(){return libraryWithExport().replace('<div class="page-heading">',`<div class="row" style="justify-content:flex-end;margin-bottom:12px">${btn(icon('save')+'备份资料','backups','ghost small')}</div><div class="page-heading">`);};

const feedbackWithEvidence=renderFeedback;
renderFeedback=function(f,l){let html=feedbackWithEvidence(f,l);if(numeric(f.reasoningScore)&&Array.isArray(f.correctReasons)){const reasons=f.correctReasons.map(id=>l.reasonChoices?.find(r=>r.id===id)?.label||id);const block=`<div class="evidence-card" style="margin-top:15px"><div class="row spread"><h4>把行动判断和推理依据分开核对</h4><span class="badge ${f.reasoningScore===100?'green':'amber'}">参考理由覆盖 ${f.reasoningScore}%</span></div><p>${f.reasoningScore===100?'你识别了本题设定下的关键依据。':'对照下面的关键依据，找出自己遗漏或误用的条件。'}</p><ul class="assumption-list">${reasons.map(r=>`<li>${esc(r)}</li>`).join('')}</ul></div>`;html=html.replace('<div class="row wrap" style="justify-content:flex-end;margin-top:22px">',block+'<div class="row wrap" style="justify-content:flex-end;margin-top:22px">');}return html;};

let paintedHands=new Set();
function paintHand(hand){if(paintedHands.has(hand))return;paintedHands.add(hand);const p=state.scenario.players[state.selectedPlayer];p.range=(p.range||'').replace(/[,;\s]+$/,'')+(p.range?.trim()?',':'')+hand+':'+Number(state.paint)/100;state.selectedHand=hand;state.paintHandledAt=Date.now();const r=safeRange();const m=$('#range-matrix');if(m)m.innerHTML=renderMatrix(r);const t=$('[data-player-field="range"]');if(t)t.value=p.range;const d=$('.combo-drawer');if(d)d.innerHTML=renderCombos(r);}
document.addEventListener('pointerdown',e=>{const cell=e.target.closest('.range-cell');if(!cell||state.paint==='inspect'||e.button!==0)return;e.preventDefault();paintPointer=true;paintedHands=new Set();paintHand(cell.dataset.hand);});
document.addEventListener('pointerover',e=>{if(!paintPointer)return;const cell=e.target.closest('.range-cell');if(cell)paintHand(cell.dataset.hand);});
document.addEventListener('pointerup',()=>{if(!paintPointer)return;paintPointer=false;state.paintHandledAt=Date.now();touch();render();});
document.addEventListener('pointercancel',()=>{if(paintPointer){paintPointer=false;touch();render();}});
function observedSizes(){if(currentInputContext()?.provenance?.kind==='hypothetical-fork')return null;
 const ctx=state.scenario.inputContext,street=({3:'flop',4:'turn',5:'river'})[parseCards(state.scenario.board).length];
 if(!ctx?.ledger?.length||!street||ctx.issues?.some(v=>v.severity==='error'))return null;
 const start=ctx.ledger.findIndex(v=>v.type==='street'&&v.street===street&&compactBoard(v.board)===compactBoard(state.scenario.board)&&Math.abs(Number(v.potBefore)-Number(state.scenario.pot))<1e-7);
 if(start<0)return null;
 const put={},rows=[];let currentBet=0;
 for(const v of ctx.ledger.slice(start+1)){
  if(v.type==='street'||v.street!==street)break;
  const before=Number(put[v.player]||0),paid=Number(v.paid||0),pot=Number(v.potBefore),call=Math.max(0,currentBet-before),amount=Number(v.amount);
  if(!Number.isFinite(paid)||paid<0||!Number.isFinite(pot))return null;
  if(v.type==='bet'&&currentBet===0&&amount>0&&pot>0&&Math.abs(amount-paid)<1e-7)rows.push({kind:'sizes',pct:100*amount/pot,player:v.player,label:`下注 ${fmt(amount)} BB`,formula:`${fmt(amount)} ÷ ${fmt(pot)}`});
  if(v.type==='raiseTo'&&currentBet>0&&amount>currentBet&&pot+call>0&&Math.abs(amount-before-paid)<1e-7)rows.push({kind:'raiseSizes',pct:100*(amount-currentBet)/(pot+call),player:v.player,label:`加注到 ${fmt(amount)} BB`,formula:`(${fmt(amount)} − ${fmt(currentBet)}) ÷ (${fmt(pot)} + ${fmt(call)})`});
  put[v.player]=before+paid;
  currentBet=Math.max(currentBet,put[v.player]);
 }
 return rows.length?{street,rows}:null;
}
function adoptObservedSizes(){const detail=observedSizes();if(!detail)throw Error('请先载入金额与街起点完整的行动记录。');for(const kind of['sizes','raiseSizes']){const values=String(state.settings[kind]||'').split(/[,，\s]+/).filter(Boolean).map(Number).filter(v=>Number.isFinite(v)&&v>0);for(const row of detail.rows.filter(v=>v.kind===kind))if(!values.some(v=>Math.abs(v-row.pct)<1e-4))values.push(Number(row.pct.toFixed(12)));state.settings[kind]=values.sort((a,b)=>a-b).join(',');}state.solveConfig=true;render();toast('已加入本街记录里的实际尺寸。检查范围、全下与加注上限后再求解。');$('.solver-config')?.scrollIntoView({behavior:'smooth',block:'center'});}
function renderObservedLedger(ctx){
 const labels={preflop:'翻前',flop:'翻牌',turn:'转牌',river:'河牌'},actions={post:'盲注',ante:'前注',raiseTo:'加注到',call:'跟注',check:'过牌',bet:'下注',fold:'弃牌',allin:'全下',refund:'返还',uncalled:'未跟注返还'},order=['preflop','flop','turn','river'],street=({3:'flop',4:'turn',5:'river'})[parseCards(state.scenario.board).length],streetIndex=order.indexOf(street),names=new Map();
 for(const snapshot of ctx.snapshots||[])for(const p of snapshot.scenario?.players||[])if(!names.has(p.id))names.set(p.id,p.position||p.name);
 for(const p of state.scenario.players||[])names.set(p.id,p.position||p.name);
 const group=name=>{const rows=ctx.ledger.filter(v=>v.street===name&&actions[v.action||v.type]);return rows.length?`<div class="ledger-street-block"><b class="ledger-street">${labels[name]}</b><div class="action-ledger-line">${rows.map(v=>`<span>${esc(names.get(v.player||v.actor)||v.position||v.player||v.actor||'')} ${esc(actions[v.action||v.type])}${numeric(v.amount??v.to)?' '+fmt(v.amount??v.to)+' BB':''}</span>`).join('')}</div></div>`:'';};
 const before=order.slice(0,Math.max(0,streetIndex)).map(group).join(''),current=group(street),future=order.slice(streetIndex+1).map(group).join(''),observed=observedSizes();
 return `<section class="panel notes-box"><div class="panel-header"><h3>${ctx.provenance?.kind==='hypothetical-fork'?'原始行动 · 仅作参照':'真实行动与当前研究起点'}</h3><span class="badge">保留原始记录</span></div><div class="panel-body">${before?`<div class="ledger-before"><h4 class="label">到这一街之前，已知的行动</h4>${before}</div>`:''}${current?`<details class="ledger-current" open><summary>${labels[street]||'当前街'}真实行动 · 用于定位决策</summary>${current}</details>`:''}${future?`<details class="ledger-future"><summary>之后的街 · 展开会看到未来行动</summary>${future}</details>`:''}<p class="help">模型从${labels[street]||'所选街'}第一个行动前开始。本街已记录行动需要沿对应策略分支查看；加注金额是本街总投入，跟注是本次投入。</p>${observed?`<div class="observed-sizes"><div class="row spread wrap"><h4>让策略树包含这手的真实尺寸</h4>${btn('加入建树尺寸','adopt-observed-sizes','small')}</div>${observed.rows.map(v=>`<p class="help">${esc(names.get(v.player)||v.player)} ${esc(v.label)}：${esc(v.formula)} = <strong>${fmt(v.pct,4)}%</strong> ${v.kind==='sizes'?'当前底池':'跟注后的底池'}</p>`).join('')}<p class="help">与现有本街尺寸合并，保留其他备选尺寸。求解后可直接回到原手牌中的具体决定。</p></div>`:''}<details style="margin-top:12px"><summary class="muted" style="font-size:11px;cursor:pointer">原始输入与识别假设 · 可能包含事后亮牌</summary><p class="notes-preview" style="margin-top:10px">${esc(ctx.raw)}</p><ul class="assumption-list">${(ctx.assumptions||[]).map(v=>`<li>${esc(typeof v==='string'?v:v.message)}</li>`).join('')}</ul></details></div></section>`;
}

const studyWithControls=renderStudy;
renderStudy=function(){let html=studyWithControls();const ctx=state.scenario.inputContext;if(ctx?.ledger?.length)html=html.replace('<div class="panel notes-box">',renderObservedLedger(ctx)+'<div class="panel notes-box">');return html;};


function strategyMatch(c){const q=(state.strategyFilter||'').toLowerCase().replace(/\s/g,'');if(!q)return true;const name=c.combo||c.hand||'';if(name.toLowerCase().includes(q)||sameHand(name,q))return true;try{return handClass(...cards(name)).toLowerCase()===q;}catch{return false;}}
function renderRangeEvolution(n){if(!n?.combos?.length||!n.reach||n.chance||n.terminal)return '';const total=n.combos.reduce((sum,c)=>sum+Number(c.reach||0),0);if(!total)return '';const marginals=state.nodeChance?.marginals||state.nodeChance,prior=Array.isArray(marginals)?marginals.find(v=>Number(v.player)===Number(n.actor)||v.playerId===n.actorId):null,priorRows=prior?.combos;const groups={};for(const c of n.combos){let hand;try{hand=handClass(...cards(c.combo));}catch{continue;}const mass=Number(c.reach||0)/total,g=groups[hand]??={hand,posterior:0,prior:0,actions:Array(n.actions.length).fill(0),combos:0};g.posterior+=mass;g.combos++;c.probabilities?.forEach((p,i)=>g.actions[i]+=mass*p);}if(priorRows)for(const c of priorRows){let h;try{h=handClass(...cards(c.combo));}catch{continue;}const g=groups[h]??={hand:h,posterior:0,prior:0,actions:Array(n.actions.length).fill(0),combos:0};g.prior+=Number(c.probability||0);}const largest=Object.values(groups).sort((a,b)=>priorRows?Math.abs(b.posterior-b.prior)-Math.abs(a.posterior-a.prior):b.posterior-a.posterior).slice(0,8);let matrix='';for(let i=0;i<13;i++)for(let j=0;j<13;j++){const h=i===j?GRID[i]+GRID[j]:i<j?GRID[i]+GRID[j]+'s':GRID[j]+GRID[i]+'o',g=groups[h];let offset=0;const stops=g?.posterior?g.actions.map((mass,k)=>{const start=offset;offset+=mass/g.posterior*100;return `${actionColor(n.actions[k],k)} ${start.toFixed(2)}% ${offset.toFixed(2)}%`;}).join(','):'';matrix+=`<button class="posterior-cell ${state.strategyFilter===h?'selected':''} ${g?.posterior?'present':''}" data-action="node-class" data-hand="${h}" style="${stops?'--strategy:linear-gradient(90deg,'+stops+')':''}" title="${h} · 当前条件占比 ${pct(g?.posterior||0,2)}${priorRows?' · 根先验 '+pct(g?.prior||0,2):''}"><span>${h}</span>${g?.posterior?`<small>${pct(g.posterior,0)}</small>`:''}</button>`;}return `<details class="range-evolution" open><summary><span>范围怎样走到这里</span><span class="muted" style="font-size:10px;font-weight:400">点击牌类筛选下方具体组合</span></summary><div class="posterior-grid"><div><div class="posterior-matrix">${matrix}</div><div class="strategy-legend">${n.actions.map((a,i)=>`<span><i style="background:${actionColor(a,i)}"></i>${esc(a.label||actionLabel(a.id))}</span>`).join('')}</div></div><div><div class="row spread"><h4>${priorRows?'先验 → 当前条件范围':'当前条件范围'}</h4>${state.strategyFilter?btn('清除筛选','clear-strategy-filter','ghost small'):''}</div><p class="help">${priorRows?'先验已处理所有玩家之间的撞牌；后验包含此前行动筛选和新公共牌的信息。':'后验按当前节点的合法到达质量归一化。'+(strategyCapabilities().limited?'当前引擎未提供可比较的联合先验。':'这份存档未保存联合先验；重新求解后可比较前后范围。')}</p><div class="posterior-rows">${largest.map(g=>`<button class="posterior-row" data-action="node-class" data-hand="${g.hand}"><strong>${g.hand}</strong><span class="mono muted">${priorRows?pct(g.prior,1)+' → ':''}${pct(g.posterior,1)}</span>${priorRows?`<span class="mono ${g.posterior>=g.prior?'positive':'negative'}">${signed((g.posterior-g.prior)*100)} pp</span>`:''}</button>`).join('')}</div><p class="help">色块表示每类牌内部的行动频率；格内数字是该类在此节点的条件占比。不要将这两种比例混为一谈。</p>${priorRows&&state.nodeChance?.exact===false?'<p class="help gold">先验来自本次训练采样分布，不是完整范围的精确边际。</p>':''}</div></div></details>`;}
const treeWithRunouts=renderTree;
renderTree=function(){const html=treeWithRunouts();if(!state.node||state.node.chance||state.node.terminal)return html;const marker='<div class="row spread wrap" style="margin:21px 0 11px">';return html.replace(marker,renderRangeEvolution(state.node)+marker);};

const interactiveCardRenderer=card;
card=function(c,small=false,extra=''){const html=interactiveCardRenderer(c,small,extra);return extra?html:html.replace(/^<button/,'<span').replace(/<\/button>$/,'</span>');};
const runAnalysis=analyze;
analyze=async function(){const pending=runAnalysis();requestAnimationFrame(()=>$('.research-bottom')?.scrollIntoView({behavior:'smooth',block:'start'}));return pending;};
const runStrategy=solve;
solve=async function(){const pending=runStrategy();requestAnimationFrame(()=>$('.research-bottom')?.scrollIntoView({behavior:'smooth',block:'start'}));return pending;};

async function explainCombo(combo){checkStrategyCapability('evBreakdown');if(!state.node||state.node.chance||!state.job?.id)throw Error('请先选择一个有决策的节点。');const found=state.node.combos?.find(c=>sameHand(c.combo,combo));if(!found)throw Error('请选择当前行动玩家范围内的具体组合。');state.strategyCombo=found.combo;state.strategyScope='hero';const current={jobId:state.job.id,nodeId:state.node.id,combo:found.combo,path:[...state.nodePath]};state.evDetail={...current,busy:true};render();try{const result=await api('/api/pro/jobs/'+encodeURIComponent(current.jobId)+'/explain',{path:current.path,combo:current.combo});state.evDetail={...current,result};}catch(e){state.evDetail={...current,error:e.message};}render();$('.ev-breakdown')?.scrollIntoView({behavior:'smooth',block:'start'});}
function breakdownTable(rows){if(!rows?.length)return '<p class="help">没有输出可显示的后续分支。</p>';return `<div class="table-scroll"><table class="data-table"><thead><tr><th>响应分支</th><th>概率</th><th>后续条件净 EV</th><th>对总 EV 的贡献</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.label||r.type||'终点')}${numeric(r.actor)?`<br><small class="muted">${esc(state.jobScenario?.players?.[r.actor]?.position||'')}</small>`:''}</td><td class="mono">${pct(r.probability,2)}</td><td class="mono">${signed(r.conditionalEV)} BB</td><td class="mono ${Number(r.evContribution)>=0?'positive':'negative'}">${numeric(r.evContribution)?signed(r.evContribution):'—'} BB</td></tr>`).join('')}</tbody></table></div>`;}
function renderBreakdown(){const d=state.evDetail;if(!d||d.jobId!==state.job?.id||d.nodeId!==state.node?.id)return '';const r=d.result;return `<section class="ev-breakdown"><div class="row spread wrap"><div><span class="eyebrow">WHY THIS ACTION EARNS OR LOSES</span><h3 style="margin-top:7px">${inlineHand(d.combo)} · 把每个动作的收益拆开</h3></div>${btn(icon('close'),'clear-breakdown','ghost small','aria-label="关闭收益拆解"')}</div>${d.busy?'<div class="empty"><span class="spinner"></span><p style="margin-top:12px">正在沿完整后续策略独立回算…</p></div>':d.error?`<div class="issue error">${esc(d.error)}</div>`:r?`<p class="help">先固定这手牌及当前行动，再按对手的合法响应拆分：分支概率 × 该分支的后续净 EV = 对当前动作 EV 的贡献。所有金额从当前决策点计算。</p><div class="breakdown-actions">${(r.actions||[]).map(a=>`<article class="breakdown-action"><div class="row spread wrap"><h4>${esc(a.label||actionLabel(a.id))}</h4><div class="row"><span class="badge">策略 ${pct(a.frequency,1)}</span><strong class="mono ${Number(a.ev)>=0?'positive':'negative'}">${signed(a.ev)} BB</strong></div></div><div style="margin-top:13px">${breakdownTable(a.responses)}</div>${a.outcomes?.length?`<details style="margin-top:13px"><summary class="muted" style="font-size:11px;cursor:pointer">按最终结果归类</summary><div style="margin-top:10px">${breakdownTable(a.outcomes)}</div></details>`:''}<p class="help">原求解 EV ${numeric(a.solverEV)?fmt(a.solverEV,6):'—'} BB · 独立回算 ${numeric(a.ev)?fmt(a.ev,6):'—'} BB</p></article>`).join('')}</div>${renderEVComparisons(r)}<div class="callout" style="margin-top:15px"><strong>多人底池里，一人弃牌不等于你立即赢得底池。</strong><br>分支的条件 EV 继续计算仍在池中的玩家、后续加注、摊牌与各层底池。</div>${numeric(r.maxDifference)?`<p class="help">本次独立回算与求解器 EV 的最大差值：${r.maxDifference<1e-9?'小于 0.000000001':fmt(r.maxDifference,10)} BB。表格按显示精度四舍五入；该一致性只针对当前模型与后续策略。</p>`:''}${r.limits?.length?`<details style="margin-top:10px"><summary class="muted" style="font-size:11px;cursor:pointer">拆解的条件与边界</summary><ul class="assumption-list">${r.limits.map(v=>`<li>${esc(v)}</li>`).join('')}</ul></details>`:''}`:''}</section>`;}
const treeWithRanges=renderTree;
renderTree=function(){let html=treeWithRanges();if(!state.node||state.node.chance||state.node.terminal)return html;for(const c of(state.node.combos||[])){const hand=c.combo;const marker=`data-combo="${esc(hand)}" title="将此组合加入个人训练">练这手</button>`;html=html.replace(marker,marker+` <button class="button ghost small" style="padding:1px 4px;font-size:9px" data-action="breakdown" data-combo="${esc(hand)}" title="沿后续策略拆解这手牌的行动收益">拆收益</button>`);}const hand=state.strategyCombo||state.jobScenario?.hero||state.scenario.hero,focus=state.node.combos?.find(c=>sameHand(c.combo,hand));if(focus){html=html.replace('<div class="action-grid">',`<div class="row" style="justify-content:flex-end;margin:9px 0">${btn(icon('branch')+'拆开 '+inlineHand(focus.combo)+' 的收益','breakdown','small',`data-combo="${esc(focus.combo)}"`)}</div><div class="action-grid">`);}const detail=renderBreakdown();if(detail){const marker='<details style="margin-top:20px">';if(html.includes(marker))html=html.replace(marker,detail+marker);else html+=detail;}return translateEngine(html);};

function renderEVComparisons(r){if(!r.comparisons?.length)return '';return `<details class="ev-comparisons" style="margin-top:18px"><summary>两个动作之间的 EV 差额，来自哪些结果</summary><p class="help">保持本次后续策略固定，把总差额逐项核对。贡献变化是当前模型的收益账本；不能单凭这一项证明某个独立因果机制。微小差异应结合求解残差阅读。</p>${r.comparisons.map(v=>`<div class="evidence-card" style="margin-top:12px"><div class="row spread wrap"><h4>${esc(v.alternative.label)} 相对 ${esc(v.baseline.label)}</h4><strong class="mono ${v.evDifference>=0?'positive':'negative'}">${v.evDifference>0?'+':''}${fmt(v.evDifference,4)} BB</strong></div><div class="table-scroll" style="margin-top:12px"><table class="data-table"><thead><tr><th>最终结果</th><th>${esc(v.baseline.label)} 概率 / 贡献</th><th>${esc(v.alternative.label)} 概率 / 贡献</th><th>贡献差额</th></tr></thead><tbody>${v.outcomes.filter(o=>Math.abs(o.baselineProbability)+Math.abs(o.alternativeProbability)>1e-12).map(o=>`<tr><td>${esc(o.label)}</td><td class="mono">${pct(o.baselineProbability,2)} / ${signed(o.baselineContribution)} BB</td><td class="mono">${pct(o.alternativeProbability,2)} / ${signed(o.alternativeContribution)} BB</td><td class="mono ${o.difference>=0?'positive':'negative'}">${signed(o.difference)} BB</td></tr>`).join('')}</tbody></table></div></div>`).join('')}</details>`;}

const studyWithLedger=renderStudy;
renderStudy=function(){let html=studyWithLedger();html=html.replace('<div class="run-actions">',`<div class="run-actions">${btn(icon(state.researchFocus?'edit':'expand')+(state.researchFocus?'编辑输入':'专注研究'),'research-focus','ghost small')}`);if(!state.researchFocus)return html;const s=state.tab==='tree'&&state.jobScenario?state.jobScenario:state.scenario;return `<div class="focused-research"><div class="focus-context"><div><span class="eyebrow">FOCUSED STUDY</span><h2>${esc(s.title)}</h2><p class="help">${s.players.map(p=>esc(p.position)).join(' · ')} · ${s.players.length} 人 · 起始底池 ${fmt(s.pot)} BB</p></div><div class="cards-row">${boardHTML(state.tab==='tree'?state.node?.board||s.board:s.board,true)}</div></div>${html}</div>`;};

function settingsFromSource(source={},resolved={}){const out={...clone(defaultSettings),...clone(source),locks:clone(source.locks||[])};if(resolved?.streets){for(const street of['turn','river']){out[street+'Sizes']=source[street+'Sizes']??resolved.streets[street]?.bets;out[street+'RaiseSizes']=source[street+'RaiseSizes']??resolved.streets[street]?.raises;}out.riverMaxRaises=resolved.maxRaises;}for(const field of['sizes','raiseSizes','turnSizes','turnRaiseSizes','riverSizes','riverRaiseSizes'])if(Array.isArray(out[field]))out[field]=out[field].join(',');return out;}
function importStreetSelector(p){if(!p.snapshots?.length)return '';const selected=p.metadata?.selectedStreet||p.snapshots.find(v=>compactBoard(v.scenario?.board)===compactBoard(p.scenario?.board))?.street;return `<label style="margin-top:14px"><span class="label">研究哪一街 · 同时切换牌面、底池、在池玩家与剩余筹码</span><select id="import-street">${p.snapshots.map(v=>`<option value="${esc(v.street)}" ${selected===v.street?'selected':''}>${({flop:'翻牌',turn:'转牌',river:'河牌'}[v.street])||v.street}起点 · ${fmt(v.scenario?.pot)} BB · ${v.scenario?.players?.length||0} 人</option>`).join('')}</select></label>`;}
async function selectImportStreet(street){if(!state.parse?.raw)return;const epoch=state.modalEpoch,signature=importSignature(),select=$('#import-street');select.disabled=true;try{const parsed=await api('/api/pro/parse',{text:state.parse.raw,format:'auto',unit:$('#import-unit').value,bigBlind:Number($('#import-big-blind').value),options:{street}});if($('#modal').open&&epoch===state.modalEpoch&&signature===importSignature()){state.parse=parsed;renderParsePreview();}}catch(e){toast(e.message,true);if(select.isConnected)select.disabled=false;}}
function currentInputContext(){return state.scenario.inputContext||state.jobScenario?.inputContext||state.job?.inputContext||state.cases.find(c=>c.jobId===state.job?.id&&c.inputContext)?.inputContext;}
async function showObservedPath(){if(currentInputContext()?.provenance?.kind==='hypothetical-fork')throw Error('当前是明确另建的假设研究，不能标为原手牌的精确实际决策。');if(!state.job?.id||!currentInputContext())throw Error('请先求解一份带有完整行动账本的导入牌局。');if(state.jobKey&&state.jobKey!==key())throw Error('输入已改变，请重新求解后匹配实际行动。');const jobId=state.job.id;state.observedBusy=true;state.observedError=null;render();try{const report=await api('/api/pro/jobs/'+encodeURIComponent(jobId)+'/observed-path',{inputContext:currentInputContext()});if(state.job?.id!==jobId)return;state.observed={jobId,report};const path=report.target?.path??report.endPath;if(!Array.isArray(path))throw Error('记录里没有可定位的决策路径。');await navigateTree(path);toast('已严格匹配行动账本，定位到实际决策。');}catch(e){state.observedError=e.message;}finally{state.observedBusy=false;render();}}
function renderObservedNav(){if(currentInputContext()?.provenance?.kind==='hypothetical-fork')return '<div class="callout">当前为假设研究，保留原牌谱作参照；不提供原手牌实际行动的精确匹配。</div>';if(!state.job?.id||!currentInputContext()?.ledger?.length)return '';const r=state.observed?.jobId===state.job.id?state.observed.report:null;return `<div class="observed-navigation"><div class="row spread wrap"><div><h4>从原始牌局回到实际决策</h4><p class="help">逐笔核对行动人、筹码与金额，只有树中存在完全相同的分支才会定位。</p></div>${btn(state.observedBusy?'<span class="spinner"></span>核对中…':icon('target')+'回到实际决策','observed-target','small',state.observedBusy||state.jobKey!==key()?'disabled':'')}</div>${r?.decisions?.length?`<select id="observed-decision" style="margin-top:12px;font-size:11px"><option value="">选择本街的某个实际决策点</option>${r.decisions.map((v,i)=>`<option value="${i}" ${JSON.stringify(v.path)===JSON.stringify(state.nodePath)?'selected':''}>${v.isHero?'Hero · ':''}${esc(v.actorName||v.actor)} ${esc(v.recordedLabel||v.recordedAction||'行动')}之前 · 底池 ${fmt(v.pot)} BB / 需跟 ${fmt(v.toCall)} BB</option>`).join('')}${r.pending?`<option value="pending" ${JSON.stringify(r.pending.path)===JSON.stringify(state.nodePath)?'selected':''}>尚未行动 · ${r.pending.isHero?'Hero · ':''}${esc(r.pending.actorName||'下一位玩家')} · 底池 ${fmt(r.pending.pot)} BB / 需跟 ${fmt(r.pending.toCall)} BB</option>`:''}</select>`:''}${state.observedError?`<div class="issue error">${esc(state.observedError)}</div><p class="help">可回到输入，核对真实尺寸或添加对应尺寸后重新求解；软件不会用最接近的下注替代真实行动。</p>`:''}</div>`;}
async function loadSavedCase(c){const scenario={...(c.scenario||c.state),...(c.inputContext?{inputContext:c.inputContext}:{})};applyScenario(scenario);state.caseId=c.id;if(c.settings)state.settings=settingsFromSource(c.settings);state.scenario.notes=c.notes||state.scenario.notes||'';touch();const expected=key();if(c.jobId)try{const j=await api('/api/pro/jobs/'+encodeURIComponent(c.jobId));if(key()!==expected)return;if(['complete','completed'].includes(j.status)&&key(j.scenario||j.input)===expected){state.job=j;state.jobScenario=clone(state.scenario);state.jobKey=expected;state.settings=settingsFromSource(j.settings,j.result?.settings);state.lockSignature=treeSignature();state.tab='tree';await loadNode();}}catch{toast('参数与原始账本已恢复；原求解不可用，可以重新计算。');}render();}
function strategyCapabilities(){const j=state.job||{},c=j.result?.capabilities||j.capabilities||state.nodeCapabilities||{},limited=c.actionEV===false||(c.actionEV===undefined&&/HUPostflop|TexasSolver/i.test(String(j.result?.engine||j.engine||'')));return {actionEV:c.actionEV??!limited,nodeLock:c.nodeLock??!limited,studyCards:c.studyCards??!limited,evBreakdown:c.evBreakdown??!limited,fullTree:c.fullTree??!limited,limited};}
const settingsWithTurn=renderSettings;
renderSettings=function(){let html=settingsWithTurn();if(parseCards(state.scenario.board).length!==3||state.scenario.players.length!==2)return html;html=html.replace('目标残差 · % 底池','双人停止目标 · % 底池');const extra=`<div class="divider"></div><div class="row spread wrap"><h4>双人翻牌 → 转牌 → 河牌</h4>${btn('使用三街小树起点','apply-hu-settings','small')}</div><p class="help">三条街使用同一个加注层数上限，每条街最多两个下注/加注尺寸。全街导出且独立核验成功时提供行动 EV 与最佳应对残差；仅导出当前街时，后续街仍参与求解，但无法独立核验整棵树。</p><div class="field-row four" style="margin-top:12px"><label><span class="label">转牌下注 · 底池 %</span><input data-setting="turnSizes" value="${esc(state.settings.turnSizes??state.settings.sizes)}"></label><label><span class="label">转牌加注 · 跟注后底池 %</span><input data-setting="turnRaiseSizes" value="${esc(state.settings.turnRaiseSizes??state.settings.raiseSizes)}"></label><label><span class="label">河牌下注 · 底池 %</span><input data-setting="riverSizes" value="${esc(state.settings.riverSizes??state.settings.sizes)}"></label><label><span class="label">河牌加注 · 跟注后底池 %</span><input data-setting="riverRaiseSizes" value="${esc(state.settings.riverRaiseSizes??state.settings.raiseSizes)}"></label></div><label style="margin-top:12px"><span class="label">策略浏览范围</span><select data-setting="outputScope"><option value="auto" ${!state.settings.outputScope||state.settings.outputScope==='auto'?'selected':''}>自动 · 大树仅导出当前街，并明确提示边界</option><option value="full" ${state.settings.outputScope==='full'?'selected':''}>要求全街可浏览 · 超出预算时拒绝</option><option value="current-street" ${state.settings.outputScope==='current-street'?'selected':''}>仅导出当前街 · 所有后续街参与求解</option></select></label>`;return html.replace('<p class="help">更多尺寸',extra+'<p class="help">更多尺寸');};
const statusWithIndependentMetrics=renderJobStatus;
renderJobStatus=function(){let html=statusWithIndependentMetrics();const j=state.job,d=j?.diagnostics||j?.result?.diagnostics;if(numeric(d?.reportedExploitabilityPctPot)){const value=d.reportedExploitabilityPctPot,target=Number(j.settings?.accuracy??state.settings.accuracy??.25),verified=d.independentlyVerified===true;if(!verified&&value>target)html=html.replace('策略求解完成','计算结束 · 原引擎指标未达目标');const scope=j.result?.scope;html+=`<div class="callout" style="margin:0 18px 16px"><strong>${verified?'独立最佳应对复算已完成':'原引擎报告指标 '+fmt(value,4)+'% 底池'}</strong><br>${verified?'本次双人优化残差采用独立复算的 exploitability（NashConv ÷ 2），为起始底池的 '+fmt(d.optimizationResidualPctPot,4)+'%。原引擎自行报告 '+fmt(value,4)+'%，单独保留用于追溯；残差不是逐组合 EV 的误差界。':'尚未经过本平台独立最佳应对复算，不与 RiverLab / TurnLab 的 NashConv 混用，也不是逐组合 EV 的误差界。'}${scope?`<br>参与求解：${(scope.solvedStreets||[]).map(v=>({flop:'翻牌',turn:'转牌',river:'河牌'}[v]||v)).join(' → ')}；可浏览：${(scope.exportedStreets||[]).map(v=>({flop:'翻牌',turn:'转牌',river:'河牌'}[v]||v)).join('、')}。`:''}</div>`;}return html;};
function checkStrategyCapability(name){if(strategyCapabilities()[name]===false)throw Error('当前引擎仅输出策略频率，暂不支持此项操作。请查看结果注明的计算能力。');}
function limitStrategyActions(html){const caps=strategyCapabilities(),map={'create-study-card':'studyCards','lock-node':'nodeLock','breakdown':'evBreakdown'};for(const[action,feature]of Object.entries(map))if(caps[feature]===false)html=html.replace(new RegExp('<button([^>]*data-action="'+action+'"[^>]*)>','g'),'<button$1 disabled aria-disabled="true" title="当前引擎尚不支持这项操作">');return html;}
const treeWithBreakdowns=renderTree;
renderTree=function(){const n=state.node;if(n?.outOfScope)return `<div class="tree-breadcrumb"><button data-action="tree-back" data-depth="0">本街起点</button>${state.nodePath.map((a,i)=>`<span class="faint">›</span><button data-action="tree-back" data-depth="${i+1}">${esc(actionLabel(a))}</button>`).join('')}</div><div class="empty"><span class="empty-icon">${icon('branch')}</span><h3>到达这份策略文件的展示边界</h3><p>${esc(n.reason||n.message||n.limits?.join('；')||'该节点没有导出可浏览的后续策略。不能据此推断玩家之后应该采用哪个动作。')}</p>${btn(icon('back')+'返回上一节点','tree-up','small')}</div>`;let html=treeWithBreakdowns();const caps=strategyCapabilities();if(n&&!n.chance&&!n.terminal&&n.combos?.length&&n.combos.every(c=>c.counterfactualReach===0)){html='<div class="callout warn" style="margin-bottom:16px"><strong>这条行动路径在当前对手策略下没有正的到达依据。</strong><br>显示的策略频率不能当作此处的实战建议；条件行动 EV 未定义，因此不提供训练评分或收益拆解。若实战确实出现了这条线，请检验起点范围，或在上游节点明确锁定实际响应后重新求解。</div>'+html;html=html.replace(/<button([^>]*data-action="(?:create-study-card|breakdown)"[^>]*)>/g,'<button$1 disabled aria-disabled="true">');}if(n&&caps.actionEV===false)html=`<div class="callout" style="margin-bottom:16px"><strong>这份结果提供真实策略频率，未输出行动 EV。</strong><br>下方的“—”表示未计算或未导出，不代表收益为零；当前结果不用于收益拆解、节点锁定或 EV 评分训练。完整性和精度以本次引擎报告为准。</div>`+html;const rake=state.job?.result?.rakeModel||state.nodeRake;if(n&&rake?.type==='fixed-cap-reached-at-root')html=`<div class="callout" style="margin-bottom:16px"><strong>已封顶的固定抽水：${fmt(rake.fixedRake)} BB</strong><br>起始台面底池 ${fmt(rake.grossStartingPot)} BB，扣除后 ${fmt(rake.netStartingPot)} BB。该固定金额在每个终局仅扣一次；下注尺寸仍按台面未扣抽水底池计算，后续新增投入与未被跟注返还不会重复抽水。</div>`+html;return renderSavedInputAssessment()+renderObservedNav()+limitStrategyActions(html);};

// Range hypotheses are re-solved independently; no probability is assigned to them.


function treeSettingsKey(settings){const size=v=>String(v??'').split(/[,，\s]+/).filter(Boolean).map(Number).sort((a,b)=>a-b);const streets=parseCards(state.jobScenario?.board||state.scenario.board).length,s={sizes:size(settings.sizes),raiseSizes:size(settings.raiseSizes),maxRaises:Number(settings.maxRaises??2),allIn:!!settings.allIn,locks:settings.locks||[]};if(streets<=4){s.riverSizes=size(settings.riverSizes??(streets===3?settings.sizes:'50'));s.riverRaiseSizes=size(settings.riverRaiseSizes??(streets===3?settings.raiseSizes:'50'));s.riverMaxRaises=streets===3?s.maxRaises:Number(settings.riverMaxRaises??0);s.riverToAct=Number(settings.riverToAct??state.jobScenario?.toAct??0);}if(streets===3){s.turnSizes=size(settings.turnSizes??settings.sizes);s.turnRaiseSizes=size(settings.turnRaiseSizes??settings.raiseSizes);}return JSON.stringify(s);}
function pendingTreeSettings(){return !!state.job?.settings&&!!state.node&&treeSettingsKey(state.settings)!==treeSettingsKey(settingsFromSource(state.job.settings,state.job.result?.settings));}
function renderSettingsNotice(){return `<div class="stale-notice settings-stale"><div class="grow">建树尺寸或响应约束已改变。下方仍是本次保存的求解结果，需重新求解才反映新设置。</div>${btn('恢复本次求解设置','restore-job-settings','ghost small')}</div>`;}
function refreshSettingsNotice(){const existing=$('.settings-stale'),pending=pendingTreeSettings();if(!pending)existing?.remove();else if(!existing)$('.result-tabs')?.insertAdjacentHTML('beforebegin',renderSettingsNotice());}
const studyWithResearchFocus=renderStudy;
renderStudy=function(){let html=studyWithResearchFocus();if(pendingTreeSettings())html=html.replace('<div class="result-tabs">',renderSettingsNotice()+'<div class="result-tabs">');return html;};

const settingsWithPostflop=renderSettings;
renderSettings=function(){let html=settingsWithPostflop();const allowed=parseCards(state.scenario.board).length===5&&state.scenario.players.length<=3,gpu=state.settings.engine==='gpu-river';const resource=`<div class="divider"></div><h4>本地计算资源</h4><div class="field-row" style="margin-top:12px"><label><span class="label">迭代算法 · 高级</span>${parseCards(state.scenario.board).length===3&&state.scenario.players.length===2?'<input value="DCFR · HUPostflop固定算法" disabled>':`<select data-setting="algorithm">${[['alternating-cfr-plus','交替 CFR+ · 默认'],['cfr-plus','CFR+'],['dcfr','DCFR']].map(([v,l])=>`<option value="${v}" ${(state.settings.algorithm||'alternating-cfr-plus')===v?'selected':''}>${l}</option>`).join('')}</select>`}</label><label><span class="label">策略引擎</span><select data-setting="engine"><option value="auto" ${!gpu?'selected':''}>自动选择 · 按牌局与街数使用 CPU 引擎</option><option value="gpu-river" ${gpu?'selected':''} ${!allowed?'disabled':''}>GPU策略 · 实验 · 河牌2–3人</option></select></label>${gpu?`<label><span class="label">GPU工作内存预算</span><select data-setting="gpuMemoryBytes">${[4e9,8e9,16e9].map(v=>`<option value="${v}" ${Number(state.settings.gpuMemoryBytes||4e9)===v?'selected':''}>${v/1e9} GB</option>`).join('')}</select></label><label><span class="label">全流程时间上限 · 秒</span><input data-setting="maxSeconds" type="number" min="1" max="14400" value="${state.settings.maxSeconds??1200}"></label>`:''}</div>${gpu?`<label class="adaptive-precision-option"><input type="checkbox" data-setting="adaptivePrecision" ${state.settings.adaptivePrecision?'checked':''}><span><strong>按独立精度目标提前停止</strong><small>达到上方目标残差即可停止；迭代次数和全流程时间仍为上限。每次检查都由 CPU 复算，不保证一定达标。</small></span></label><p class="help">这里的残差是整棵给定树内、允许偏离锁定的 NashConv / 初始底池。它不是逐手 EV 误差界；多人没有一般性收敛保证。</p>`:''}<p class="help">${gpu?'GPU计算完整合法发牌分布；结束后再由CPU独立复算最佳应对与行动EV。启动时会卸载本地语言模型释放显存；期间GPU权益计算需等待，教练仍可使用已有证据解释。小局面CPU通常更快。':'NVIDIA GPU用于范围权益和按需中文教练；河牌2–3人的策略迭代还可以显式切换GPU实验引擎。更大的树仍受显存与后续独立核验预算约束。不同算法速度可能不同，以本次独立残差判断数值质量。'}</p>${gpu&&!allowed?'<div class="issue error">局面已改为GPU策略不支持的街数或人数，请切回自动选择。</div>':''}`;return html.replace('<p class="help">更多尺寸',resource+'<p class="help">更多尺寸');};
const statusWithNativeVerification=renderJobStatus;
renderJobStatus=function(){let html=statusWithNativeVerification();const j=state.job;if(!j||j.settings?.engine!=='gpu-river')return html;const progress=j.progress||{},phase=progress.phase==='running'?progress.role:progress.phase,active=['queued','preparing','running','cancelling'].includes(j.status),phases={'cpu-independent-verification':'正在由 CPU 独立复算当前策略的最佳响应与行动 EV','gpu-preparing':'正在准备 GPU 发牌分布与行动树',prepared:'完整合法发牌分布与行动树已准备','gpu-training':'NVIDIA GPU 正在进行策略迭代','gpu-checkpoint':'正在固定当前平均策略，准备独立核验','precision-check-complete':'独立精度检查完成','gpu-continuing':'本次核验未达目标 · GPU 继续迭代','unloading-local-coach':'正在释放中文教练占用的显存'};if(active&&j.status!=='cancelling'&&phases[phase])html=html.replace('正在求解行动策略',phases[phase]);let extra='';if(active){extra='<p class="help">GPU 策略计算与独立验证期间暂占主要计算资源，只有完整核验的策略才会发布。</p>';if(numeric(progress.lastVerifiedNashConvPctPot)||phase==='precision-check-complete'&&numeric(progress.nashConvPctPot))extra+=`<p class="help">最近已核验残差 ${fmt(progress.lastVerifiedNashConvPctPot??progress.nashConvPctPot,5)}% 起始底池${progress.nextCheckIteration?' · 下一检查预计在 '+fmt(progress.nextCheckIteration,0)+' 轮':''}。这仍是中间检查，完整结果尚未发布。</p>`;}else if(['complete','completed'].includes(j.status)){const r=j.result||{},stats=j.stats||r.stats||{},d=j.diagnostics||r.diagnostics||{},checks=j.precisionChecks||r.precisionChecks||[],stop=j.stopReason||r.stopReason,labels={accuracy_target:'独立残差达到目标',iteration_limit:'达到迭代上限',time_limit:'达到全流程时间上限'},target=stats.targetAccuracyPctPot??j.settings.accuracy;extra=`<div class="gpu-precision-report"><div class="row spread wrap"><strong>${esc(labels[stop]||'GPU 计算已完成并独立核验')}</strong><span class="badge ${stats.targetReached===true?'green':'amber'}">${stats.targetReached===true?'本模型目标已达':stats.targetReached===false?'尚未达到本模型目标':'目标状态未报告'}</span></div><p class="help">独立残差 ${fmt(d.nashConvPctPot,5)}% / 目标 ${fmt(target,5)}% 起始底池。发布的是 ${fmt(stats.iterations,0)} 轮的已核验平均策略；根节点残差不能当作每一手行动 EV 的误差上界。</p>${stats.adaptiveStopping?`<p class="help">完成 ${stats.precisionChecks??checks.length} 次独立检查。${stats.timingIncomplete?'时间上限在后续迭代期间到达，未核验的额外迭代未发布。':numeric(stats.iterationsExecuted)&&stats.iterationsExecuted>stats.iterations?'本次还执行了后续迭代，但发布保留在最后完整核验的检查点。':''}多人自博弈不保证总能达到指定残差。</p>`:''}${checks.length?`<details><summary>各检查点的独立精度记录</summary><div class="table-scroll"><table class="data-table"><thead><tr><th>已核验迭代</th><th>NashConv · BB</th><th>残差 · % 底池</th><th>目标</th><th>本次核验用时</th></tr></thead><tbody>${checks.map(c=>`<tr><td>${fmt(c.iteration,0)}</td><td>${fmt(c.nashConv,6)}</td><td>${fmt(c.nashConvPctPot,6)}%</td><td>${c.targetReached?'达到':'未达到'}</td><td>${fmt(c.verificationSeconds,3)} 秒</td></tr>`).join('')}</tbody></table></div><p class="help">每个检查点绑定这一份输入和平均策略；后续检查不保证残差单调下降。锁定策略的偏离也包含在这里的残差中。</p></details>`:''}</div>`;}return extra&&html.endsWith('</div>')?html.slice(0,-6)+extra+'</div>':html;};

Object.assign(state,{experiments:[],experiment:null,sensitivityDraft:null,sensitivityCreating:false});
let sensitivityPoll=null;
function sensitivityEligible(){const j=state.job,n=state.node;if(/HUPostflop|TexasSolver/i.test(j?.engine||j?.result?.engine||'')||j?.settings?.engine==='hu-postflop')return {ok:false,reason:'HU 当前暂不提供同模型范围实验，请用多人河牌引擎重新建立研究。'};if(!j||!n||n.terminal||n.chance)return {ok:false,reason:'先打开一个有决策动作的河牌求解节点，再选择具体组合。'};if(state.jobKey!==key()||pendingTreeSettings())return {ok:false,reason:'当前输入或建树设置与求解结果不一致，请先恢复原局面和设置，或重新求解。'};if(parseCards(state.jobScenario?.board||j.scenario?.board).length!==5||j.result?.chance?.exact!==true||strategyCapabilities().actionEV===false)return {ok:false,reason:'目前需要从河牌起点建立、具有完整机会枚举与行动 EV 的求解结果。'};if(!n.combos?.some(c=>c.counterfactualReach>0))return {ok:false,reason:'这份结果缺少范围实验需要的到达证据，请使用当前引擎重新求解。'};return {ok:true};}
function sensitivityDraft(){const signature=state.job?.id+':'+state.node?.id;if(state.sensitivityDraft?.signature!==signature){const n=state.node,p=state.jobScenario?.players||state.scenario.players,combo=n?.combos?.find(c=>sameHand(c.combo,state.strategyCombo||state.jobScenario?.hero)&&c.counterfactualReach>0)||n?.combos?.find(c=>c.counterfactualReach>0);state.sensitivityDraft={signature,player:p.findIndex((_,i)=>i!==n?.actor),combo:combo?.combo||'',subset:'',scales:'25,50,100'};}return state.sensitivityDraft;}
function sensitivityRunning(r=state.experiment){return ['queued','running','cancelling'].includes(r?.status);}
function renderSensitivity(){const eligible=sensitivityEligible(),d=sensitivityDraft(),n=state.node,players=state.jobScenario?.players||state.scenario.players;let choices=[];try{choices=Object.keys(range(players[d.player]?.range||'',parseCards(state.jobScenario?.board||state.scenario.board)).groups);}catch{}return `<div class="row spread wrap"><div><span class="eyebrow">TEST THE RANGE ASSUMPTION</span><h3 style="margin-top:7px">范围估计错一点，行动会变多少？</h3></div>${btn(icon('refresh')+'更新实验记录','refresh-experiments','ghost small')}</div><div class="callout" style="margin-top:15px">每次只改变一位对手的一组起点组合权重，再让未锁定的策略重新优化。这检验的是你的范围假设，不等于已经证实对手的实战行为。</div>${eligible.ok?`<div class="sensitivity-form"><div class="field-row four"><label><span class="label">当前行动玩家的具体手牌</span><select data-sensitivity="combo">${n.combos.filter(c=>c.counterfactualReach>0).map(c=>`<option value="${esc(c.combo)}" ${sameHand(c.combo,d.combo)?'selected':''}>${esc(c.combo)}</option>`).join('')}</select></label><label><span class="label">改变哪位对手的起点范围</span><select data-sensitivity="player">${players.map((p,i)=>i!==n.actor?`<option value="${i}" ${i===Number(d.player)?'selected':''}>${esc(p.position)} · ${esc(p.name)}</option>`:'').join('')}</select></label><label><span class="label">牌类 / 具体组合 · 可组合输入</span><input data-sensitivity="subset" list="sensitivity-subsets" value="${esc(d.subset)}" placeholder="例如 KJs 或 AhQh,AhJh"><datalist id="sensitivity-subsets">${choices.map(h=>`<option value="${esc(h)}">`).join('')}</datalist></label><label><span class="label">原组合权重保留 · %</span><input data-sensitivity="scales" value="${esc(d.scales)}" placeholder="25,50,100"></label></div><div class="row spread wrap" style="margin-top:15px"><p class="help">2–5 个不同倍率，0% 以上且不超过 100%；100% 复用原解。每个新模型最多计算 120 秒，可中止。${state.job?.settings?.locks?.length?'沿用原解中的 '+state.job.settings.locks.length+' 项锁定约束。':''}</p>${btn(state.sensitivityCreating?'<span class="spinner"></span>创建中…':icon('branch')+'运行范围对照','start-sensitivity','primary',state.sensitivityCreating||sensitivityRunning()?'disabled':'')}</div></div>`:`<div class="empty"><h3>从可核验的策略开始</h3><p>${esc(eligible.reason)}</p>${btn('回到行动树','result-tab','small','data-value="tree"')}</div>`}<div id="sensitivity-result">${renderSensitivityResult()}</div><div id="sensitivity-history">${renderSensitivityHistory()}</div>`;}
function renderSensitivityResult(){const e=state.experiment;if(!e)return '<div class="coach-principle" style="margin-top:18px"><h4>先写一个会改变行动的假设</h4><p>例如：如果对手只有一半概率带着某组薄价值牌来到河牌，我的加注是否仍然赚钱？结果会分别给出每个假设里的 EV 和错选损失。</p></div>';if(sensitivityRunning(e)){const p=e.progress||{},index=Number(p.index??p.variant??0)+1,total=p.total||e.input?.scales?.length||'—';return `<div class="sensitivity-status"><div class="row spread"><div class="row"><span class="spinner"></span><strong>${e.status==='cancelling'?'正在停止实验并释放资源':'正在求解第 '+index+' / '+total+' 个范围假设'}</strong></div>${btn(e.status==='cancelling'?'正在停止…':'停止实验','cancel-sensitivity','danger small',e.status==='cancelling'?'disabled':'')}</div><p class="help">${numeric(p.scale)?'当前保留权重 '+pct(p.scale,0)+' · ':''}${p.iterations?'已迭代 '+fmt(p.iterations,0)+' 次。':''}完整对照完成后才会给出跨模型的损失结论。</p><div class="loading-line" style="margin-top:12px"></div></div>`;}if(e.status!=='complete'||!e.result)return `<div class="callout warn" style="margin-top:18px"><strong>${e.status==='cancelled'?'范围实验已停止':'本次范围实验未完成'}</strong><p>${esc(e.error||'保留已完成的计算记录，未生成不完整的稳健性结论。')}</p>${e.variants?.length?`<p class="help">已完成 ${e.variants.length} 个变体；可在计算历史中查看。</p>`:''}</div>`;const r=e.result,target=Number(r.settings?.accuracy),provisional=r.rows.some(v=>v.quality?.targetReached!==true||!numeric(v.quality?.residualPctPot)||numeric(v.quality?.residualPctPot)&&Number.isFinite(target)&&v.quality.residualPctPot>target);return `<div class="sensitivity-report"><div class="row spread wrap"><div><h3>${inlineHand(r.combo)} · 对 ${esc(r.playerName)} 的范围假设是否敏感</h3><p class="help">${esc(r.actorName)} 行动 · 节点底池 ${fmt(r.nodePot)} BB · 需跟 ${fmt(r.toCall)} BB · ${r.affectedCombos.length} 个受影响组合</p></div><span class="badge ${provisional?'amber':''}">${provisional?'部分模型精度尚待确认':'各模型分别报告残差'}</span></div><p class="help">每格上方是当前具体手牌的行动 EV，下方是相对该模型最佳动作的损失。没有给不同范围假设分配发生概率。</p><div class="table-scroll" style="margin-top:15px"><table class="data-table"><thead><tr><th>目标牌组保留权重</th>${r.actions.map(a=>`<th>${esc(a.label)}<br><small>EV / 错选损失 · BB</small></th>`).join('')}<th>计算证据</th><th></th></tr></thead><tbody>${r.rows.map(v=>`<tr><td><strong>${pct(v.scale,0)}</strong><br><small class="muted">受影响组合质量 ${fmt(v.affectedWeight)}</small></td>${v.actions.map(a=>`<td class="mono"><strong>${signed(a.ev)}</strong><br><small class="${a.loss>1e-6?'gold':'positive'}">损失 ${fmt(a.loss,4)}</small></td>`).join('')}<td class="muted">残差 ${fmt(v.quality?.residualPctPot,4)}% 底池<br>${fmt(v.diagnostics?.nashConv,5)} BB NashConv</td><td>${v.jobId?btn('打开此模型','sensitivity-variant','ghost small',`data-id="${esc(v.jobId)}"`):''}</td></tr>`).join('')}</tbody></table></div>${sensitivityReview.render(e)}<h4 style="margin-top:20px">在这组假设中，哪个动作的最坏错选损失更小</h4><div class="sensitivity-action-grid">${r.actions.map(a=>`<div class="evidence-card"><div class="row spread"><h4>${esc(a.label)}</h4>${r.minimaxRegretActions.includes(a.id)?`<span class="badge ${provisional?'amber':'green'}">${provisional?'本组数字较小 · 待核验':'本组假设内较稳健'}</span>`:''}</div><div class="sensitivity-regret mono">${fmt(a.maxRegret,4)} <small>BB</small></div><p class="help">最大模型内损失<br>EV 区间 ${signed(a.minEV)} ～ ${signed(a.maxEV)} BB</p></div>`).join('')}</div><p class="help">这是所选假设集内的最大损失比较，不是对所有可能对手范围的保证。微小差异应结合各行数值残差解读。</p><details style="margin-top:15px"><summary class="muted" style="font-size:11px;cursor:pointer">查看具体受影响组合与模型边界</summary><p class="help">${r.affectedCombos.map(c=>esc(c.combo)+' × '+fmt(c.weight)).join('；')}</p><p class="help">${esc(r.meaning)}</p><ul class="assumption-list">${(r.limits||[]).map(v=>`<li>${esc(v)}</li>`).join('')}</ul></details></div>`;}
function renderSensitivityHistory(){if(!state.experiments?.length)return '';return `<details style="margin-top:22px"><summary class="muted" style="font-size:12px;cursor:pointer">本机范围实验 · ${state.experiments.length} 次</summary><div class="table-scroll" style="margin-top:12px"><table class="data-table"><thead><tr><th>时间</th><th>牌组与手牌</th><th>状态</th><th></th></tr></thead><tbody>${state.experiments.map(e=>`<tr><td>${time(e.createdAt)}</td><td>${esc(e.input?.subset||e.result?.subset||'范围实验')} · ${esc(e.input?.combo||e.result?.combo||'')}</td><td>${esc(({running:'进行中',complete:'完成',failed:'未完成',cancelled:'已停止',cancelling:'停止中'}[e.status])||e.status)}</td><td>${btn('查看','load-sensitivity','ghost small',`data-id="${esc(e.id)}"`)}</td></tr>`).join('')}</tbody></table></div></details>`;}
async function loadExperiments(){try{const r=await api('/api/pro/experiments');state.experiments=Array.isArray(r)?r:r.experiments||[];const el=$('#sensitivity-history');if(el)el.innerHTML=renderSensitivityHistory();}catch(e){toast(e.message,true);}}
async function startSensitivity(){const eligible=sensitivityEligible();if(!eligible.ok)throw Error(eligible.reason);const d=sensitivityDraft(),scales=String(d.scales).split(/[,，\s]+/).filter(Boolean).map(v=>Number(v)/100);if(scales.length<2||scales.length>5||scales.some(v=>!Number.isFinite(v)||v<=0||v>1)||new Set(scales).size!==scales.length)throw Error('请输入2–5个不同的百分比，均大于0且不超过100。');if(!d.subset.trim())throw Error('请选择想改变权重的对手牌组，例如 KJs。');state.sensitivityCreating=true;render();try{state.experiment=await api('/api/pro/jobs/'+encodeURIComponent(state.job.id)+'/sensitivity',{player:Number(d.player),subset:d.subset.trim(),combo:d.combo,nodePath:[...state.nodePath],scales});await loadExperiments();await watchSensitivity();}finally{state.sensitivityCreating=false;render();}}
async function watchSensitivity(){clearTimeout(sensitivityPoll);const id=state.experiment?.id;if(!id)return;try{const e=await api('/api/pro/experiments/'+encodeURIComponent(id));if(state.experiment?.id!==id)return;state.experiment=e;const el=$('#sensitivity-result');if(el)el.innerHTML=renderSensitivityResult();const run=$('[data-action="start-sensitivity"]');if(run)run.disabled=sensitivityRunning(e)||state.sensitivityCreating;if(sensitivityRunning(e))sensitivityPoll=setTimeout(watchSensitivity,1800);else{await loadExperiments();loadJobs();}}catch(e){toast(e.message,true);}}
async function loadSensitivity(id){clearTimeout(sensitivityPoll);state.experiment=await api('/api/pro/experiments/'+encodeURIComponent(id));state.compareMode='sensitivity';state.tab='compare';render();if(sensitivityRunning())await watchSensitivity();}
async function openSensitivityVariant(id){const path=[...(state.experiment?.result?.nodePath||[])],j=await api('/api/pro/jobs/'+encodeURIComponent(id));applyScenario({...j.scenario,...(j.inputContext?{inputContext:j.inputContext}:{})});state.job=j;state.jobScenario=clone(state.scenario);state.jobKey=key();state.settings=settingsFromSource(j.settings,j.result?.settings);state.nodePath=path;state.tab='tree';await loadNode();nav('study');}
const comparisonWithNodeLocks=renderComparison;
renderComparison=function(){const tabs=`<div class="row wrap" style="margin-bottom:17px">${[['equity','范围权益对照'],['strategy','策略响应对照'],['sensitivity','范围稳健性']].map(([v,l])=>`<button class="pill ${state.compareMode===v?'active':''}" data-action="compare-mode" data-value="${v}">${l}</button>`).join('')}</div>`;if(state.compareMode==='sensitivity')return tabs+renderSensitivity();return comparisonWithNodeLocks().replace(/^<div class="row" style="margin-bottom:17px">[\s\S]*?<\/div>/,tabs);};
document.addEventListener('input',e=>{if(e.target.dataset.sensitivity&&state.sensitivityDraft)state.sensitivityDraft[e.target.dataset.sensitivity]=e.target.value;});
document.addEventListener('change',e=>{if(e.target.dataset.sensitivity==='player'){state.sensitivityDraft.player=Number(e.target.value);state.sensitivityDraft.subset='';render();}else if(e.target.dataset.sensitivity==='combo')state.sensitivityDraft.combo=e.target.value;});


function privateFolded(question,index){if(Array.isArray(question.nodeContext?.folded))return question.nodeContext.folded[index]===true;return question.nodeContext?.history?.some(h=>h.actorSeat===index&&h.type==='fold')||false;}
function renderPrivateRanges(question){const n=question.nodeContext||{},players=question.scenario?.players||[];return `<details class="training-ranges" open><summary>本题起点范围与当前筹码</summary><p class="help">这些范围属于研究起点。此前行动会继续筛选到达组合；此处不提前显示参考策略。</p>${players.map((p,i)=>{const spent=n.contributions?.[i],remaining=numeric(spent)?Math.max(0,Number(p.stack)-Number(spent)):null;return `<div class="training-range-player"><div class="row spread wrap"><strong>${esc(p.position)} · ${esc(p.name)}</strong>${i===n.actorSeat?'<span class="badge green">当前行动</span>':privateFolded(question,i)?'<span class="badge">已弃牌</span>':''}</div><p class="help">${numeric(remaining)?'当前剩余 '+fmt(remaining):'起点剩余 '+fmt(p.stack)} BB</p><code>${esc(p.range||'范围未提供')}</code></div>`;}).join('')}<p class="help">组合权重与阻断都影响参考结果；范围是题目条件，不代表已经观测到对手的真实范围。</p></details>`;}
const trainingWithQualityAndGuides=renderTraining;
renderTraining=function(){let html=trainingWithQualityAndGuides();if(state.lesson?.private){const question=state.lesson,n=question.nodeContext;html=html.replace('<span class="muted" style="font-size:11px">Hero</span>',`<span class="muted" style="font-size:11px">本题手牌${n?.actorName?' · '+esc(n.actorName):''}</span>`);const ranges=renderPrivateRanges(question),assumptions=html.match(/<ul class="assumption-list">[\s\S]*?<\/ul>/);if(assumptions)html=html.replace(assumptions[0],ranges+'<details class="training-model-details"><summary>模型条件与边界</summary>'+assumptions[0]+'</details>');else{const marker='<div class="divider"></div><p class="help">不要先猜软件期待的按钮。';html=html.replace(marker,ranges+marker);}if(!Number(question.scenario?.rake)){html=html.replace(/<div class="context-item"><span class="muted">抽水<\/span>[\s\S]*?<\/div>/,'<div class="context-item"><span class="muted">抽水</span><strong>无</strong></div>').replace(/<div class="context-item"><span class="muted">抽水封顶<\/span>[\s\S]*?<\/div>/,'');}}return html;};
function renderLearningEvidence(){const summary=state.summary||{},e=summary.learningEvidence||{},first=e.firstExposureTransfer||{},delayed=e.delayedRetrieval||{};return `<section class="section-gap learning-evidence"><div class="section-title"><h2>把熟悉、迁移和保持分开看</h2><small>来自不同的学习证据</small></div><div class="learning-evidence-grid"><div class="panel evidence-metric"><span class="eyebrow">FIRST EXPOSURE</span><h3>首次遇到的迁移题</h3><div class="learning-number">${numeric(first.accuracy)?pct(first.accuracy,0):'—'}</div><p class="help">${first.attempts??'—'} 道首次独立作答 · ${first.correct??'—'} 道判断一致</p><p>重复做熟悉的同一道题，不增加这项证据。</p></div><div class="panel evidence-metric"><span class="eyebrow">DELAYED RETRIEVAL</span><h3>间隔后的再次判断</h3><div class="learning-number">${numeric(delayed.accuracy)?pct(delayed.accuracy,0):'—'}</div><p class="help">${delayed.attempts??'—'} 次延迟复测 · ${delayed.correct??'—'} 次判断一致</p><p>${esc(e.delayedRule||'距同题上次作答至少20小时；未到时间的重复练习不计入这项统计。')}</p></div><div class="panel evidence-metric"><span class="eyebrow">REASONING EVIDENCE</span><h3>关键依据的完整度</h3><div class="learning-number">${numeric(summary.reasoningAverage)?fmt(summary.reasoningAverage,0)+'%':'—'}</div><p class="help">基于题目已定义的关键理由，包含选错理由的扣分</p><p>行动选对但理由遗漏，仍然值得复查；这不是对自由表达能力的自动打分。</p></div></div><p class="help">样本较少时先积累不同局面。这里显示教学任务内的证据，不证明真实牌桌上的技术增益。</p></section>`;}
const progressWithRealAttempts=renderProgress;
renderProgress=function(){let html=progressWithRealAttempts();html=html.replace('<div class="progress-grid section-gap">',renderLearningEvidence()+'<div class="progress-grid section-gap">');const skills=state.summary?.skills||[];if(skills.length){const table=`<section class="panel section-gap"><div class="panel-header"><h3>同样选对，推理质量可能不同</h3><span class="badge">按能力拆开</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>能力</th><th>练习 / 不同题</th><th>行动一致率</th><th>理由完整度</th><th>信心校准</th><th></th></tr></thead><tbody>${skills.map(skill=>{const target=state.lessons.find(l=>l.skill===skill.skill&&l.trainingRole==='transfer'&&!skill.lessons?.includes(l.id))||state.lessons.find(l=>l.skill===skill.skill);return `<tr><td>${esc(skill.theme||skill.skill)}</td><td>${skill.attempts||0} 次 / ${skill.lessons?.length||0} 题</td><td>${pct(skill.accuracy,0)}</td><td>${numeric(skill.reasoning)?fmt(skill.reasoning,0)+'%':'—'}</td><td>${numeric(skill.brier)?fmt(skill.brier,3):'—'} <small class="muted">Brier</small></td><td>${target?btn(skill.lessons?.includes(target.id)?'复习此能力':'检验一个新局面','lesson','ghost small',`data-id="${esc(target.id)}"`):''}</td></tr>`;}).join('')}</tbody></table></div><div class="panel-body"><p class="help">Brier记录判断信心与实际结果的偏差，0表示完全一致；不同难度、重复题与小样本不能直接比较，更不对应德州等级。先检查高信心错误，再观察新题与延迟复测。</p></div></section>`;html=html.replace('<div class="panel section-gap"><div class="panel-header"><h3>最近的判断</h3>',table+'<div class="panel section-gap"><div class="panel-header"><h3>最近的判断</h3>');}return html;};


function csvCell(value){if(value===null||value===undefined)return '';if(typeof value==='number')return Number.isFinite(value)?String(value):'';let text=String(value);if(/^[=+\-@\t\r]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"';}
function exportNodeCSV(){const n=state.node,j=state.job,s=state.jobScenario||j?.scenario;if(!j?.id||!n||n.terminal||n.chance||!n.combos?.length)throw Error('请打开一个具有组合策略的决策节点。');const rows=n.combos.filter(strategyMatch);if(!rows.length)throw Error('当前筛选没有组合。');const prior=(state.nodeChance?.marginals||j.result?.chance?.marginals||[]).find(p=>p.player===n.actor||p.playerId===n.actorId),canon=combo=>parseCards(combo).sort((a,b)=>a-b).join(','),marginals=new Map((prior?.combos||[]).map(c=>[canon(c.combo),c.probability]));const headers=['研究标题','求解任务','节点','当前公共牌','行动玩家','当前底池_BB','需跟注_BB','组合','起点输入权重','根联合先验','绝对到达质量','当前条件范围占比','反事实到达质量',...n.actions.flatMap(a=>[a.label+'_频率',a.label+'_条件行动EV_BB'])];const values=rows.map(c=>[s?.title||'',j.id,n.id,n.board||s?.board,s?.players?.[n.actor]?.position||n.actorId,n.pot,n.toCall,c.combo,c.weight,marginals.get(canon(c.combo)),c.reach,n.reach>0?c.reach/n.reach:null,c.counterfactualReach,...n.actions.flatMap((_,i)=>[c.probabilities?.[i],c.actionEV?.[i]])]);const csv='\uFEFF'+[headers,...values].map(row=>row.map(csvCell).join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=('PokerLab-'+(s?.title||'组合策略')+'-'+n.id).replace(/[<>:"/\\|?*]/g,'-')+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast(`已导出 ${rows.length} 个组合。空白EV表示未定义或未输出，不是0。`);}
const treeWithLearningContext=renderTree;
renderTree=function(){let html=treeWithLearningContext();if(state.node&&!state.node.chance&&!state.node.terminal&&state.node.combos?.length)html=html.replace('<h3>逐组合策略与行动 EV</h3>',`<h3>逐组合策略与行动 EV</h3>${btn(icon('download')+(state.strategyFilter?'导出筛选组合':'导出组合表'),'export-node-csv','ghost small')}`);return html;};



function privateReview(card){const by=state.studySummary?.byCard;return card?.review||(Array.isArray(by)?by.find(r=>(r.id||r.cardId)===card?.id):by?.[card?.id])||null;}
function privateReviewLabel(review){if(!review||review.newCard||review.stage==='new')return '新题 · 待首次判断';if(review.due)return review.stage==='provisional-review'?'模型暂定 · 到期核对':'到期复核';return ({learning:'已安排复核',relearning:'纠错后再测','delayed-review':'延迟复测','provisional-review':'模型暂定 · 保留复核'})[review.stage]||'已安排复核';}
function privateDueCards(){return state.studySummary?.due||state.privateCards.map(c=>privateReview(c)).filter(r=>r?.due).sort((a,b)=>(a.priority==='high'?-1:0)-(b.priority==='high'?-1:0)||Date.parse(a.nextDueAt)-Date.parse(b.nextDueAt));}
function renderPrivateDue(){const due=privateDueCards();if(!due.length)return '';return `<section class="panel private-review-queue section-gap"><div class="section-title"><div><span class="eyebrow">RETRIEVE BEFORE YOU REVIEW</span><h2 style="margin-top:7px">回到你研究过的真实节点</h2></div><span class="badge amber">${due.length} 题到期</span></div><p class="help">先隐藏旧策略，重新作答。短时间纠错与至少24小时后的复测分别记录，不把记住按钮当作掌握。</p><div class="private-review-list">${due.slice(0,3).map(r=>`<div class="row spread wrap"><div><strong>${esc(r.title||state.privateCards.find(c=>c.id===(r.id||r.cardId))?.publicQuestion?.title||'求解节点复核')}</strong><p class="help">${esc(privateReviewLabel(r))}${r.nextDueAt?' · '+time(r.nextDueAt):''}</p></div>${btn('先重新判断 '+icon('arrow'),'private-lesson','small',`data-id="${esc(r.id||r.cardId)}"`)}</div>`).join('')}</div>${due.length>3?`<p class="help">另有 ${due.length-3} 题；每次完成后重新安排下一项。</p>`:''}</section>`;}
function renderPrivateReviewEvidence(){const all=state.studySummary,s=all?.summary;if(!s)return '';const first=s.firstExposure||{},delayed=s.delayedRetrieval||{},metric=(title,e,description)=>`<div class="panel evidence-metric"><h3>${title}</h3><div class="learning-number">${numeric(e.eligibleAccuracy)?pct(e.eligibleAccuracy,0):'—'}</div><p class="help">${e.eligibleCount??0} 次精确且达自身残差目标的参考判断 · ${e.eligibleCorrect??0} 次一致</p><p>${description}</p><p class="help">含暂定模型的全部记录：${e.count??0} 次，${numeric(e.accuracy)?pct(e.accuracy,0):'—'} 一致。</p></div>`;return `<section class="section-gap private-learning-evidence"><div class="section-title"><h2>真实节点题 · 从首次判断到延迟保持</h2><span class="badge">${s.totalAttempts??0} 次实际作答</span></div><div class="private-evidence-grid">${metric('首次面对这一节点',first,'每个题卡只计第一次作答；练习次数不增加首次表现样本。')}${metric('至少24小时后的复测',delayed,'短时间纠错另行记录，不计入保持指标。模型质量未达标的题保留记录，但不混入上述参考统计。')}<div class="panel evidence-metric"><h3>下一次检验</h3><div class="learning-number">${s.dueCards??0}<small style="font-size:15px"> 题</small></div><p class="help">已做 ${s.seenCards??0} 张不同题卡 · 高信心错误 ${s.highConfidenceErrors??0} 次</p><p>复核间隔按实际答题与模型质量安排，属于透明的教学规则，不是实战胜率预测。</p>${privateDueCards().length?btn('开始节点题复核','due-private','small'):''}</div></div><details class="training-model-details"><summary>如何解释这份学习记录</summary><p class="help">${esc(Array.isArray(all.interpretation)?all.interpretation.join(' '):all.interpretation||'不同来源、不同模型质量、首次和重复判断分别报告。熟悉某个范围假设不等于已经识别真实对手。')}</p></details></section>`;}
const todayBeforePrivateReview=renderToday;
renderToday=function(){let html=todayBeforePrivateReview();const due=privateDueCards();if(due.length){html=html.replace(/<section class="panel focus-card">[\s\S]*?<\/section>/,`<section class="panel focus-card"><span class="badge green">${due.length} 道真实节点题到期</span><h2>先不看旧答案，<br>重建你的决策依据。</h2><p>从上次研究过的局面开始，检验间隔之后还能否独立判断。答完再对照范围、响应与逐动作收益。</p>${btn('开始今日节点复核 '+icon('arrow'),'due-private','primary')}</section>`);html=html.replace('<div class="section-gap"><div class="section-title"><h2>从你的问题开始</h2>',renderPrivateDue()+'<div class="section-gap"><div class="section-title"><h2>从你的问题开始</h2>');}return html.replace('已完成练习</span>','已完成课程练习</span>').replace('待复习项目</span>','课程待复习</span>');};
const trainingBeforePrivateReview=renderTraining;
renderTraining=function(){let html=trainingBeforePrivateReview();if(!state.lesson&&privateDueCards().length)html=html.replace('<div class="callout"',renderPrivateDue()+'<div class="callout"');if(state.lesson?.private&&state.feedback&&state.lessonReview){const r=state.lessonReview;html+=`<section class="panel private-review-next section-gap"><div class="row spread wrap"><div><span class="eyebrow">NEXT RETRIEVAL</span><h3 style="margin-top:7px">${r.nextDueAt?'下一次复核：'+time(r.nextDueAt):'这次判断已记录'}</h3></div><span class="badge">${esc(privateReviewLabel(r))}</span></div><p class="help">即时重做可帮助纠错；保持证据要等至少24小时后再次独立作答。暂定模型题会保留质量标记。</p></section>`;}return html;};
const progressBeforePrivateReview=renderProgress;
renderProgress=function(){return progressBeforePrivateReview()+renderPrivateReviewEvidence();};

const rangeBank=createRangeBank({api,esc,fmt,btn,icon,openModal,closeModal,toast,snapshot:()=>({player:state.scenario.players[state.selectedPlayer],board:state.scenario.board,title:state.scenario.title,format:state.scenario.format}),apply:(text,reference)=>{const p=state.scenario.players[state.selectedPlayer];p.range=text;const note='范围引用（'+p.position+'）：'+reference.title+'；来源 '+(reference.source||'用户保存的范围假设')+'；'+(reference.mode==='max-union'?'与当前范围按逐组合最大频率合并。':'作为当前范围假设。');if(!(state.scenario.notes||'').includes(note))state.scenario.notes=[state.scenario.notes,note].filter(Boolean).join('\n');touch();render();}});
const handInbox=createHandInbox({api,esc,fmt,time,btn,icon,inlineHand,openModal,closeModal,toast,onStudy:scenario=>{state.settings=clone(defaultSettings);applyScenario(scenario);},onShow:()=>{state.libraryMode='inbox';nav('library');},visible:()=>state.route==='library'&&state.libraryMode==='inbox'});
const libraryWithCasesAndBackups=renderLibrary;
renderLibrary=function(){return state.libraryMode==='inbox'?handInbox.render(libraryTabs()):libraryWithCasesAndBackups();};

function renderLoadStatus(){if(state.initialLoading)return '<div class="callout" style="margin-bottom:18px"><span class="spinner" style="margin-right:8px"></span>正在读取本机资料…</div>';const errors=Object.entries(state.loadErrors||{});if(!errors.length)return '';const names={metadata:'工作台配置',hardware:'计算状态',lessons:'训练课程',summary:'训练成绩',cases:'研究档案',jobs:'求解任务',privateCards:'个人题卡',studySummary:'节点题复习',catalog:'研究起点',guides:'主题路线',experiments:'范围实验'};return `<div class="callout warn" style="margin-bottom:18px"><div class="row spread wrap"><strong>部分资料尚未读取，空列表不代表记录不存在。</strong>${btn('重新连接','reload-data','small')}</div><p>${errors.map(([k])=>names[k]||k).join('、')}暂不可用。请保持本地服务运行，再重新读取。</p><details><summary style="font-size:11px;cursor:pointer">查看原因</summary>${errors.map(([k,e])=>`<p class="help">${esc(names[k]||k)}：${esc(e)}</p>`).join('')}</details></div>`;}
async function init(){if(state.initialLoading)return;state.initialLoading=true;state.loadErrors={};render();const tasks=[['metadata',()=>api('/api/pro/metadata')],['hardware',()=>api('/api/status')],['lessons',()=>api('/api/pro/training/lessons')],['summary',()=>api('/api/pro/training/summary')],['studySummary',()=>api('/api/pro/training/study-summary')],['cases',()=>api('/api/pro/cases')],['jobs',()=>api('/api/pro/jobs')],['privateCards',()=>api('/api/pro/training/study-cards')],['catalog',()=>api('/api/pro/library')],['guides',()=>api('/api/pro/training/guides')],['experiments',()=>api('/api/pro/experiments')]];await Promise.allSettled(tasks.map(async([k,fn])=>{try{const r=await fn();state[k]=['lessons','cases','jobs','privateCards','catalog','guides','experiments'].includes(k)?Array.isArray(r)?r:r[k]||r.cards||[]:r;}catch(e){state.loadErrors[k]=e.message;}}));if(state.caseId&&!state.loadErrors.cases&&!state.cases.some(c=>c.id===state.caseId))state.caseId=null;state.initialLoading=false;render();}


// v0.3 task-focused training modules share the exact source identity of the research workbench.
state.trainingMode=localStorage.getItem('pokerlab-v3-training-mode')||'play';
state.studyMode='workspace';state.activeProjectId=null;
const labSources=()=>({catalog:state.catalog||[],jobs:state.jobs||[],cases:state.cases||[],experiments:state.experiments||[]});
function currentLabSource(){return state.job?.id&&state.jobKey===key()&&!pendingTreeSettings()?{kind:'job',id:state.job.id,jobId:state.job.id,nodeId:state.node?.id,path:[...state.nodePath],title:state.jobScenario?.title||state.scenario.title,answerSeen:true}:state.scenario.inputContext?.sourceHandId?{kind:'hand',id:state.scenario.inputContext.sourceHandId,title:state.scenario.title}:state.caseId?{kind:'case',id:state.caseId,title:state.scenario.title}:{kind:'manual'};}
async function openSolvedNode({jobId,path=[],combo,projectId,evidence=false}={}){const token=Symbol('open-solved');state.labNodeRequest=token;const j=await api('/api/pro/jobs/'+encodeURIComponent(jobId));if(state.labNodeRequest!==token)return;if(!['complete','completed'].includes(j.status))throw Error('该模型尚未完成，不能展示为已验证策略。');const sc=j.scenario||j.input;if(!sc)throw Error('这份模型缺少可恢复的原始局面。');applyScenario({...clone(sc),...(j.inputContext?{inputContext:clone(j.inputContext)}:{})});state.job=j;state.jobScenario=clone(state.scenario);state.jobKey=key();state.settings=settingsFromSource(j.settings,j.result?.settings);state.lockSignature=treeSignature();state.nodePath=[...path];state.tab='tree';state.researchFocus=true;state.studyMode='workspace';if(projectId)state.activeProjectId=projectId;nav('study');await loadNode();if(state.labNodeRequest!==token)return;if(combo){state.strategyCombo=combo;state.strategyScope='hero';}render();window.scrollTo(0,0);if(evidence&&combo&&strategyCapabilities().evBreakdown)await explainCombo(combo);}
function showLabMode(mode){state.lesson=null;state.feedback=null;state.trainingMode=mode;localStorage.setItem('pokerlab-v3-training-mode',mode);nav('train');}
async function handleLearningTarget(target){switch(target.kind){case'study-project':return studyProjects.select(target.id);case'lesson':state.trainingMode='mechanism';state.pendingAssessment=!!target.assessment;await startLesson(target.id);return;case'study-card':state.trainingMode='mechanism';state.pendingAssessment=!!target.assessment;await loadPrivateCards();await startPrivateLesson(target.id);return;case'course-attempt':case'study-attempt':return openSavedAttempt(target);case'range-attempt':return rangeLab.resume(target.id);case'play-session':return playLab.resume(target.id);case'play-decision':await playLab.resume(target.sessionId);document.querySelector('[data-decision-id="'+CSS.escape(target.id)+'"]')?.scrollIntoView({behavior:'smooth',block:'center'});return;case'start-play':return playLab.configure({jobId:target.jobId,startingPath:target.path||[],projectId:target.projectId});case'job':return openSolvedNode({jobId:target.jobId||target.id,path:target.path||[],combo:target.combo,projectId:target.projectId});case'case':{await loadCases();const c=state.cases.find(c=>c.id===target.id);if(!c)throw Error('未能读取这个来源案例。');state.studyMode='workspace';await loadSavedCase(c);return;}case'hand':state.libraryMode='inbox';nav('library');await handInbox.activate();if(handInbox.selectHand)await handInbox.selectHand(target.id);return;case'experiment':{const experiment=await api('/api/pro/experiments/'+encodeURIComponent(target.id));await openSolvedNode({jobId:experiment.sourceJobId,path:experiment.input?.nodePath||[]});state.experiment=experiment;state.tab='compare';state.compareMode='sensitivity';render();return;}default:throw Error('这一来源暂不能直接打开，请保留记录并回到对应资料库。');}}
async function openSavedAttempt(target){const privateAttempt=target.kind==='study-attempt',rows=await api('/api/pro/training/'+(privateAttempt?'study-history':'history')),attempt=(Array.isArray(rows)?rows:rows.items||[]).find(a=>a.id===target.id);if(!attempt)throw Error('原始作答未保留在本机，不能据链接重建答案。');state.trainingMode='mechanism';state.pendingAssessment=false;if(privateAttempt){await loadPrivateCards();await startPrivateLesson(attempt.cardId);}else await startLesson(attempt.lessonId);state.answer=attempt.answer;state.reasons=attempt.reasonIds||[];state.freeReason=attempt.reason||'';state.confidence=attempt.confidence??60;state.feedback=attempt.feedback||attempt;state.savedAttempt=attempt;state.lastAttempt=attempt;render();window.scrollTo(0,0);}
const labDeps={api,esc,fmt,pct,signed,time,btn,icon,inlineHand,boardHTML,toast,openModal,closeModal,onOpenNode:openSolvedNode,sources:labSources,onProject:(source,question)=>studyProjects.newProject(source,question),onEvidence:(projectId,source,note)=>studyProjects.attachEvidence(projectId,source,note)};
const sensitivityReview=createSensitivityDebrief(labDeps);
const liveRecorder=createLiveRecorder({...labDeps,onStudy:scenario=>{state.activeProjectId=null;state.studyMode='workspace';state.settings=clone(defaultSettings);applyScenario(scenario);}});
const playLab=createPlayLab({...labDeps,onShow:()=>showLabMode('play')});
const rangeLab=createRangeConstructionLab({...labDeps,onShow:()=>showLabMode('range')});
const studyProjects=createStudyProjects({...labDeps,currentSource:currentLabSource,onShow:()=>{state.studyMode='projects';nav('study');},onTarget:handleLearningTarget,onActiveProject:id=>state.activeProjectId=id});
function labTabs(mode){return `<div class="lab-tabs">${[['play','连续决策'],['range','构建整段策略'],['balance','动态平衡实验'],['mechanism','机制与节点练习']].map(([id,label])=>btn(label,'lab-mode',mode===id?'active':'',`data-mode="${id}"`)).join('')}</div>`;}
const balanceLab=createBalanceExamples({...labDeps,onShow:()=>showLabMode('balance'),onRange:args=>rangeLab.open(args)});
const mechanismTrainingRenderer=renderTraining;
renderTraining=function(){const mode=state.lesson?'mechanism':state.trainingMode;if(mode==='mechanism')return labTabs(mode)+(state.savedAttempt?`<div class="callout"><strong>原作答回看 · ${time(state.savedAttempt.createdAt)}</strong><p>展示当时保存的答案与反馈，这次打开不产生新成绩。${state.savedAttempt.version&&state.lesson?.version&&state.savedAttempt.version!==state.lesson.version?'原题版本与当前题干不同，以下题干只作定位，原反馈未重新评分。':''}</p></div>`:'')+mechanismTrainingRenderer()+(state.feedback&&state.lastAttempt?`<div class="row" style="justify-content:flex-end;margin-top:18px">${btn('把这次判断变成研究问题','lab-project-attempt','small')}</div>`:'');if(mode==='balance')return labTabs(mode)+balanceLab.render();const compact=mode==='range'?!!rangeLab.state.question:!!(playLab.state.detail||playLab.state.setup||playLab.state.setupLoading);return `${compact?'':`<div class="page-heading lab-top-heading"><div><div class="eyebrow">PRIVATE PRACTICE LAB</div><h1 style="margin-top:6px">训练实验室</h1><p class="subtitle">先独立构建和执行，再回到证据里修正判断。</p></div>${btn('我的研究问题','project-show','small')}</div>`}${labTabs(mode)}${mode==='range'?rangeLab.render():playLab.render()}`;};
function inputIssuesBlocking(){const ctx=state.scenario.inputContext;return !!ctx&&ctx.provenance?.kind!=='hypothetical-fork'&&(ctx.issues||[]).some(i=>i.severity==='error');}
function inputProvenanceBanner(){const ctx=state.scenario.inputContext;if(!ctx)return '';const fork=ctx.provenance?.kind==='hypothetical-fork',errors=(ctx.issues||[]).filter(i=>i.severity==='error');return `<section class="input-provenance ${fork||errors.length?'needs-review':''}"><div class="row spread wrap"><div><strong>${fork?'假设研究 · 从原牌谱另建条件':errors.length?'原始输入还需要修正核对':ctx.sourceRecordingId?'来自现场动作记录 · 先重建所选街起点':'来自原始牌谱 · 求解前核对街起点'}</strong><p>${fork?esc(ctx.provenance.reason):errors.length?'仍有识别错误。可以保存草稿，但须修正原文并重新核对，或明确另建假设研究。':'原文与行动记录持续保留。求解时核对公共牌、底池、在场玩家和剩余筹码；范围由你另建假设。'}</p>${ctx.sourceRecordingId&&!fork?`<p>${ctx.decisionContext?.unit==='BB'&&numeric(ctx.decisionContext.pot)?'选定决定：'+esc(({flop:'翻牌',turn:'转牌',river:'河牌'}[ctx.decisionContext.street])||ctx.decisionContext.street)+' '+esc(ctx.decisionContext.actorId||'')+' · 当时底池 '+fmt(ctx.decisionContext.pot)+' BB'+(numeric(ctx.decisionContext.toCall)?' · 需跟 '+fmt(ctx.decisionContext.toCall)+' BB':'')+'。':''}下方从本街起点 ${fmt(state.scenario.pot)} BB 建树，筹码也使用该街开始时的数值；求解后点击“回到实际决策”定位到所选决定。</p>`:''}</div><div class="row wrap">${ctx.sourceRecordingId?btn('继续这份现场记录','live-resume','small',`data-id="${esc(ctx.sourceRecordingId)}"`):btn('修正原文并重建','lab-repair-input','ghost small')}${!fork?btn('明确另建假设','lab-fork-input','small'):''}</div></div>${errors.length&&!fork?'<ul class="assumption-list">'+errors.map(i=>'<li>'+esc(i.message||i.code)+'</li>').join('') :''}</section>`;}
function showHypotheticalFork(){const ctx=state.scenario.inputContext;if(!ctx)throw Error('当前没有需要保留的原始输入。');openModal('把当前参数明确作为假设研究','原始牌谱与原手牌编号仍保留。这个分支不再表示已核对的真实街起点，也不会匹配为原手牌实际行动。',`<div class="row wrap">${boardHTML(state.scenario.board,true)}<span class="badge">${state.scenario.players.length} 人 · 起点 ${fmt(state.scenario.pot)} BB</span></div><label class="label" for="hypothesis-reason" style="margin-top:22px">我改变或补设了什么？为什么这样研究？</label><textarea id="hypothesis-reason" rows="4" placeholder="例如：原记录没有说清加注是到18还是再加18；这次只研究加注到18的假设，不能称为已还原真实牌局。"></textarea><p class="help">新分支保留完整原文，不覆盖原手牌。之后保存时会建立新的案例。</p>`,btn('返回修正','close-modal','ghost')+btn('建立这个假设分支','lab-confirm-fork','primary'));}
function createHypotheticalFork(){const reason=$('#hypothesis-reason')?.value.trim();if(!reason||reason.length<5)throw Error('请写明改变或补设的条件，至少5个字符。');const scenario=clone(state.scenario);scenario.inputContext={...clone(scenario.inputContext),provenance:{kind:'hypothetical-fork',reason}};scenario.title=(scenario.title||'牌局研究')+' · 假设分支';scenario.notes=[scenario.notes,'假设分支：'+reason].filter(Boolean).join('\n');closeModal();applyScenario(scenario);toast('已另建假设分支，原文与手牌来源仍保留。');}
const studyBeforeProvenance=renderStudy;
renderStudy=function(){let html=studyBeforeProvenance();const ctx=state.scenario.inputContext,bad=ctx&&ctx.provenance?.kind!=='hypothetical-fork'&&(ctx.issues||[]).some(i=>i.severity==='error');html=html.replace('<div class="panel study-toolbar">',inputProvenanceBanner()+'<div class="panel study-toolbar">');if(bad)html=html.replace(/<button([^>]*data-action="(?:solve|analyze)"[^>]*)>/g,'<button$1 disabled title="先修正原文并重新核对，或明确另建假设研究">');return html;};
const studyBeforeProjects=renderStudy;
function activeProjectRail(){if(!state.activeProjectId)return '';const p=studyProjects.state.detail?.id===state.activeProjectId?studyProjects.state.detail:studyProjects.state.items.find(v=>v.id===state.activeProjectId);if(!p)return '';return `<div class="project-active-rail"><div><strong>${esc(p.question||p.title)}</strong><p>当前研究与这个问题关联；新的求解和训练可以作为下一条证据保留。</p></div><div class="row">${state.job?.id&&state.jobKey===key()&&!pendingTreeSettings()?btn('把当前结果带回问题','lab-evidence-current','primary small'):''}${btn('回到研究问题','project-open','small',`data-id="${esc(p.id)}"`)}${btn(icon('close'),'lab-unlink-project','ghost small','title="结束当前工作区关联，保留研究任务"')}</div></div>`;}
renderStudy=function(){return `<div class="study-mode-tabs">${btn('局面与策略','study-mode',state.studyMode!=='projects'?'active':'','data-mode="workspace"')}${btn('研究问题与证据','study-mode',state.studyMode==='projects'?'active':'','data-mode="projects"')}</div>${state.studyMode==='projects'?studyProjects.render():activeProjectRail()+studyBeforeProjects()}`;};
const runoutLab=createRunoutPlan({...labDeps,onShow:()=>{state.studyMode='runout';nav('study');},onPlay:args=>playLab.configure({jobId:args.jobId,startingPath:args.path,heroSeat:args.heroSeat,focusCombo:args.combo,projectId:args.projectId,answerSeen:true})});
const studyWithProjects=renderStudy;
renderStudy=function(){if(state.studyMode!=='runout')return studyWithProjects();return `<div class="study-mode-tabs">${btn('局面与策略','study-mode','','data-mode="workspace"')}${btn('研究问题与证据','study-mode','','data-mode="projects"')}<span class="badge">下一街计划</span></div>${runoutLab.render()}`;};
const treeBeforePracticeLab=renderTree;
renderTree=function(){let html=treeBeforePracticeLab();const n=state.node;if(n&&!n.terminal&&!n.chance&&state.job?.id){const mismatch=state.jobKey!==key()||pendingTreeSettings();const extra=mismatch?'disabled title="输入或设置已改变，请先恢复原模型"':'';html=`<div class="lab-node-launcher"><div><strong>把这个节点变成独立能力</strong><p>先执行完整行动线，或亲手分配整段范围；提交后再对照证据。</p></div><div class="row wrap">${btn(icon('train')+'连续决策','lab-play-current','small',extra)}${btn(icon('edit')+'构建整段策略','lab-range-current','small',extra)}${btn(state.activeProjectId?'把这个节点带回问题':'立一个研究问题','lab-project-current','ghost small')}</div></div>`+html;}if(state.job?.id&&parseCards(state.jobScenario?.board||state.scenario.board).length<5){html+=`<section class="panel construction-evaluation"><div><span class="eyebrow">BUILD A RIVER PLAN</span><h3>同一条行动线，下一街哪些牌会改变计划？</h3><p>先预测，再比较完整策略树里各张河牌的条件概率、组合策略和行动收益。</p></div>${btn('看下一街计划','lab-runout-current','small',state.jobKey!==key()||pendingTreeSettings()?'disabled':'')}</section>`;}return html;};
const todayBeforePrescriptions=renderToday;
renderToday=function(){let html=todayBeforePrescriptions();html=html.replace('<div class="quick-grid">','<div class="quick-grid live-input-quick">'+`<button class="panel quick-card" data-action="live-open">${icon('chip')}<div><h3>按动作记录现场牌局</h3><p>选座位与筹码，逐步录入，不必写牌谱格式。</p></div></button>`);html=html.replace(/<div class="welcome">[\s\S]*?<\/section><\/div>/,studyProjects.renderPrescription());return html;};
const progressBeforeLabs=renderProgress;
renderProgress=function(){const e=studyProjects.state.plan?.evidenceSummary;if(!e)return progressBeforeLabs();const blocks=[['firstExposure','本机首次作答'],['delayedRetrieval','至少24小时后的提取'],['shortGapPractice','短间隔纠错与加练']];return `<section class="panel lab-setup-card section-gap"><div class="section-title"><h2>新的判断，与熟悉的答案分开</h2><span class="badge">真实本机记录</span></div><div class="private-evidence-grid">${blocks.map(([k,t])=>{const b=e[k]||{};return `<div class="evidence-metric"><h3>${t}</h3><div class="learning-number">${numeric(b.accuracy)?pct(b.accuracy,0):'—'}</div><p class="help">${b.judged||0} 次有合格参考的判断 · ${b.distinctTasks||0} 个不同任务</p><p class="help">高信心分歧 ${b.highConfidenceErrors||0} 次 · 暂定参考 ${b.provisional||0} 条</p></div>`;}).join('')}</div><p class="help">${esc(e.lossAggregation||'本机首次仅表示任务身份的首次记录，未认证此前没见过答案。看过参考的研究加练单独保留；不跨街累计局部损失，不换算实战胜率。')}</p></section>`+progressBeforeLabs();};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;try{switch(b.dataset.action){case'lab-repair-input':state.importText=state.scenario.inputContext?.raw||'';state.importOptions={unit:state.scenario.inputContext?.sourceUnit||'BB',bigBlind:state.scenario.inputContext?.sourceBigBlind||1};showImport({repair:true});break;case'lab-fork-input':showHypotheticalFork();break;case'lab-confirm-fork':createHypotheticalFork();break;case'lab-evidence-current':if(state.activeProjectId)await studyProjects.attachEvidence(state.activeProjectId,currentLabSource());break;case'lab-project-draft':{const saved=await saveCase();if(!saved)break;studyProjects.newProject({kind:'case',id:saved.id,caseId:saved.id,handId:saved.inputContext?.sourceHandId,title:saved.title,scenarioKey:key(saved.scenario),answerSeen:!!(state.node&&state.jobKey===key()||state.analysis&&!stale())},(state.scenario.notes||'').split('\n').find(v=>v.trim()&&!v.startsWith('来源：'))||'');break;}case'lab-project-attempt':if(state.lastAttempt)studyProjects.newProject({kind:state.lesson?.private?'study-attempt':'course-attempt',id:state.lastAttempt.id,answerSeen:true},'这个决定依赖什么条件，哪些变化会使它反转？');break;case'lab-runout-current':await runoutLab.open({jobId:state.job.id,path:[...state.nodePath],projectId:state.activeProjectId});break;case'lab-unlink-project':state.activeProjectId=null;render();break;case'lab-mode':showLabMode(b.dataset.mode);if(b.dataset.mode==='play')await playLab.activate();if(b.dataset.mode==='range')await rangeLab.activate();if(b.dataset.mode==='balance')await balanceLab.activate();break;case'study-mode':state.studyMode=b.dataset.mode;render();if(state.studyMode==='projects')await studyProjects.activate();break;case'lab-play-current':await playLab.configure({jobId:state.job.id,startingPath:[...state.nodePath],heroSeat:state.node.actor,focusCombo:state.strategyCombo||state.jobScenario?.hero||'',projectId:state.activeProjectId,answerSeen:true});break;case'lab-range-current':await rangeLab.open({jobId:state.job.id,nodePath:[...state.nodePath],projectId:state.activeProjectId,answerSeen:true});break;case'lab-project-current':if(state.activeProjectId)await studyProjects.attachEvidence(state.activeProjectId,currentLabSource());else studyProjects.newProject(currentLabSource(),state.scenario.notes?.split('\n')[0]||'');break;case'nav':if(b.dataset.route==='train'){if(state.trainingMode==='play')await playLab.activate();if(state.trainingMode==='range')await rangeLab.activate();if(state.trainingMode==='balance')await balanceLab.activate();}if(b.dataset.route==='today'||b.dataset.route==='progress')await studyProjects.loadPlan();break;}}catch(err){toast(err.message,true);}});

const researchLab=createResearchLab({...labDeps,currentScenario:()=>clone(state.scenario),currentSolve:()=>{if(!state.job?.id||state.jobKey!==key()||pendingTreeSettings())throw Error('当前输入或建树设置已改变，请先打开原始求解或重新求解。');return {...clone(state.job),scenario:clone(state.jobScenario||state.job.scenario),path:[...state.nodePath],combo:state.strategyCombo||''};},onShow:()=>{state.studyMode='research';nav('study');}});
const studyBeforeResearch=renderStudy;
renderStudy=function(){if(state.studyMode==='research')return researchLab.render();let html=studyBeforeResearch();if(state.studyMode==='workspace'||!state.studyMode)html=html.replace('<div class="panel study-toolbar">',`<div class="research-launcher"><div><strong>用单一变化检验自己的判断</strong><p>比较翻前范围阶段、牌面权益，或只换一张牌重新求解。</p></div><div class="row wrap">${btn('范围阶段与权益曲线','open-equity-research','small')}${btn('换牌策略实验','open-board-research','small',!state.job?.id?'disabled title="先完成一次策略求解"':'')}</div></div><div class="panel study-toolbar">`);return html;};
const comparisonBeforeResearch=renderComparison;
renderComparison=function(){return `<div class="research-compare-links"><span class="help">更明确的单因素实验</span>${btn('范围阶段与权益曲线','open-equity-research','ghost small')}${btn('换一张公共牌','open-board-research','ghost small',!state.job?.id?'disabled':'')}</div>`+comparisonBeforeResearch();};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;try{if(b.dataset.action==='open-equity-research')await researchLab.open('equity');if(b.dataset.action==='open-board-research')await researchLab.fromCurrent();}catch(err){toast(err.message,true);}});
window.addEventListener('beforeunload',()=>persist());
init().then(()=>{studyProjects.activate();if(state.route==='train'){if(state.trainingMode==='play')playLab.activate();if(state.trainingMode==='range')rangeLab.activate();if(state.trainingMode==='balance')balanceLab.activate();}});

function renderSavedInputAssessment(){const p=state.node&&state.nodeProvenance;if(p?.kind!=='unverified-legacy')return '';return `<div class="callout warn" style="margin-bottom:15px"><strong>旧记录的原始输入尚未核对</strong><p>${esc(p.error||'原始记录无法完整重建。')}</p><p class="help">以下仅展示已保存参数对应的数学模型，不代表原实战已核对。请修正原文，或明确另建假设后重新计算。</p></div>`;}
